// Content for Be the Safe Adult (node g69, Parent Layer, Chapter 8) — NEW v2 build to GDD 69 (mechanic-embodying),
// the SAFEGUARDING KEYSTONE that closes the Parent Layer and underwrites the ENTIRE kids' journey: from My Body,
// My Rules (g02) onward the curriculum tells children to "tell a trusted adult" — this node makes sure that adult
// exists, notices, and responds right. MAXIMUM-CARE and trauma-informed; direct but never fear-mongering and never
// graphic. 84 researched, India-grounded scenarios across be-tellable → spot-the-signs → if-they-tell-you →
// the-law-and-the-call → safe-online-and-off → tools-and-respond, each encoded as one of the shared v2 play
// actions (strike-rewrite / role-play / branch / sort / match / spot / reflect) — no binary "tap the right card".
// Lead: strike-rewrite (bust the myth), role-play (say it), branch (your move). Six modes: be tellable (the
// biggest protection is a child who knows they can tell you anything — the open, no-blame door built on purpose;
// busts 'it won't happen to us' & 'they'd tell me anyway'; read silence as fear & threats, not betrayal), spot the
// signs (behavioural & physical signs and grooming red flags, told calmly without paranoia; MOST abuse is by a
// known, trusted adult, not a stranger — a child's sudden fear of a familiar person is a signal), if they tell you
// (the disclosure response that shapes everything: BELIEVE the child, stay calm rather than show horror or rage,
// tell them clearly it is NOT their fault, do not interrogate but let them talk at their own pace, then act and
// protect — never hush it up for the family's image), the law and the call (POCSO basics: any sexual offence
// against an under-18 is a crime and the child is ALWAYS the victim; reporting is obliged & protective; routes to
// Childline 1098, the police, the POCSO e-Box, and cybercrime 1930 for online abuse), safe online and off (online
// grooming, exploitation & sextortion are real and NEVER the child's fault — stay involved, keep the door open,
// keep evidence and report), tools and respond (the signs checklist, the disclosure-response steps, the helpline
// card — the child's safety always first). HIGH-CARE: educational and NOT legal advice; routes real concerns
// immediately to authorities; NEVER provides any detail that could enable harm; centres the child as ALWAYS the
// protected victim. Builds on Safety Squad (g08), My Body, My Rules (g02) and Firewall (g40). India: most child
// sexual abuse is by someone known to the family while silence, disbelief & victim-blaming remain common — which
// makes the safe, tellable, correctly-responding parent decisive; routes are Childline 1098, POCSO e-Box, the
// police and cybercrime 1930. gameId "be-the-safe-adult".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"sa-001","cat":"be-tellable","type":"strike-rewrite","hook":"\"It won't happen to my child, so I don't need to think about this.\"","myth":{"un":"It won't happen to my child, so I don't need to think about this.","re":"Harm can reach any child; the parents who protect best are the ones who prepare to be safe, tellable and ready to respond.","why":"Preparation protects; denial leaves a gap."},"relearn":"Harm can reach any child; being prepared, tellable and ready to respond is the strongest protection.","persona":"Kamla","source":"it can happen"},
  {"id":"sa-002","cat":"be-tellable","type":"strike-rewrite","hook":"\"My child would obviously tell me right away if anything happened.\"","myth":{"un":"My child would obviously tell me right away if anything happened.","re":"Children often stay silent from fear, confusion or shame; being warmly tellable, on purpose, is what makes telling possible.","why":"Tellability is built, not assumed."},"relearn":"Children often stay silent; being warmly, deliberately tellable is what makes a child able to come to you.","persona":"Kamla","source":"tellability is built"},
  {"id":"sa-003","cat":"be-tellable","type":"reflect","hook":"Lensy: the single biggest protection your child has is knowing they can tell you anything. Sit right?","prompt":"What do you think?","options":["Sits right","Tell me anything","I'll be that"],"affirm":"A child who knows they can tell their parent anything has the single strongest protection there is.","relearn":"The biggest protection your child has is knowing they can tell you anything.","persona":"Kamla","source":"biggest protection"},
  {"id":"sa-004","cat":"be-tellable","type":"sort","hook":"Sort: builds a tellable, open relationship, or quietly closes the door?","items":[{"id":"a","text":"Calm reactions to hard news"},{"id":"b","text":"Punishing the messenger"},{"id":"c","text":"'You can always come to me, no trouble'"},{"id":"d","text":"Big anger when they admit mistakes"},{"id":"e","text":"Thanking them for being honest"},{"id":"f","text":"Mocking the worry they brought you"}],"bins":[{"id":"open","label":"Builds tellability","valence":"pos"},{"id":"closes","label":"Closes the door","valence":"neg"}],"key":{"a":"open","b":"closes","c":"open","d":"closes","e":"open","f":"closes"},"relearn":"Calm reactions, 'no trouble for telling' and thanks build tellability; punishing the messenger, anger and mockery close the door.","persona":"any","source":"open or close"},
  {"id":"sa-005","cat":"be-tellable","type":"role-play","hook":"You want your child to know, before anything ever happens, that they can always come to you. You tell them.","setup":"Say it clearly:","yourLine":[{"text":"\"If anything ever scares or confuses you, or someone hurts you, you can always tell me, you'll never be in trouble.\"","best":true},{"text":"\"Don't bother me with small things, just behave.\""}],"relearn":"Telling a child in advance that they can always come to you, with no trouble, is what makes disclosure possible later.","persona":"Kamla","source":"tell them early"},
  {"id":"sa-006","cat":"be-tellable","type":"strike-rewrite","hook":"\"If a child keeps a worrying secret, it means they didn't trust me enough.\"","myth":{"un":"If a child keeps a worrying secret, it means they didn't trust me enough.","re":"Silence usually comes from an abuser's threats and a child's fear, not a failure of love; staying tellable invites them back.","why":"Don't read silence as betrayal."},"relearn":"A child's silence usually comes from fear and threats, not lack of trust; staying tellable invites them to come to you.","persona":"any","source":"silence isn't betrayal"},
  {"id":"sa-007","cat":"be-tellable","type":"reflect","hook":"Lensy: every calm, loving response to a small disclosure makes a big one possible. Worth building? ","prompt":"What's your take?","options":["Worth it","Small builds big","Building it"],"affirm":"Responding calmly and lovingly to small disclosures builds the trust that lets a child bring you the biggest things.","relearn":"Every calm, loving response to a small disclosure makes a big one possible.","persona":"any","source":"small builds big"},
  {"id":"sa-008","cat":"be-tellable","type":"spot","hook":"Spot the two reactions that make a child hide things from a parent.","scene":[{"id":"a","text":"Welcoming hard truths without blow-ups","trick":false},{"id":"b","text":"Reacting with panic, anger or blame","trick":true},{"id":"c","text":"'Nothing you tell me stops me loving you'","trick":false},{"id":"d","text":"Shaming them for 'shameful' topics","trick":true},{"id":"e","text":"Listening calmly all the way through","trick":false}],"why":"Panic, anger or blame, and shaming a child for the topic, both teach them to hide — the un-tellable reactions to catch.","relearn":"Panic, anger, blame and shame make a child hide; welcoming hard truths calmly and loving them keep them telling.","persona":"any","source":"genuinely tellable"},
  {"id":"sa-009","cat":"be-tellable","type":"branch","hook":"Your child tests you with a small, awkward admission.","options":[{"text":"Respond with calm and warmth, passing their test of safety","consequence":"They learn it's safe to tell you more.","outcome":"passed","best":true},{"text":"Overreact, teaching them to keep things from you","consequence":"Overreacting teaches them to hide the bigger things."}],"debrief":"Treat a small awkward admission as a safety test; pass it with calm warmth so they bring you more.","relearn":"Pass a child's small disclosure 'test' with calm warmth; overreacting teaches them to hide the big things.","persona":"Divya","source":"pass the test"},
  {"id":"sa-010","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Danger to children comes mainly from strangers.\"","myth":{"un":"Danger to children comes mainly from strangers.","re":"Most abuse is by someone the child knows and trusts, a relative, family friend or known adult, far more often than a stranger.","why":"Stranger-danger misses where most harm comes from."},"relearn":"Most child abuse is by someone known and trusted, not a stranger; knowing this is key to protecting your child.","persona":"Kamla","source":"known not stranger"},
  {"id":"sa-011","cat":"spot-the-signs","type":"sort","hook":"Sort: a possible warning sign worth noticing calmly, or ordinary childhood?","items":[{"id":"a","text":"Sudden fear of a particular person or place"},{"id":"b","text":"Wanting a new haircut"},{"id":"c","text":"New, unexplained distress, withdrawal or regression"},{"id":"d","text":"Outgrowing an old toy"},{"id":"e","text":"Flinching away from one familiar adult"},{"id":"f","text":"Asking to stay up a little later"}],"bins":[{"id":"sign","label":"Worth noticing","valence":"uhoh"},{"id":"ordinary","label":"Ordinary","valence":"pos"}],"key":{"a":"sign","b":"ordinary","c":"sign","d":"ordinary","e":"sign","f":"ordinary"},"relearn":"Sudden fear, unexplained distress or regression, and flinching from one adult are worth noticing; haircuts, outgrowing toys and bedtimes aren't.","persona":"any","source":"sign or ordinary"},
  {"id":"sa-012","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"A trusted, respectable adult could never be a risk to my child.\"","myth":{"un":"A trusted, respectable adult could never be a risk to my child.","re":"Abusers often seem trustworthy and respectable and use that trust to get access; staying gently alert protects your child.","why":"Respectability is not proof of safety."},"relearn":"Abusers often seem respectable and use trust to gain access; gentle alertness, not blind trust, protects a child.","persona":"Kamla","source":"respectability isn't safety"},
  {"id":"sa-013","cat":"spot-the-signs","type":"match","hook":"Match each grooming red flag to why it's worth attention.","pairs":[{"left":"Seeking lots of alone time with your child","right":"Access is how harm starts"},{"left":"Special gifts, secrets or favouritism","right":"Building secrecy and obligation"},{"left":"Ignoring your child's 'no'","right":"Testing and eroding limits"},{"left":"Asking your child to hide things","right":"Silence you can't overhear"},{"left":"Picking your child as the favourite","right":"Isolating them from others"}],"relearn":"Alone time, secrets, gifts, ignoring 'no' and favouritism are grooming red flags worth attention.","persona":"Kamla","source":"grooming flags"},
  {"id":"sa-014","cat":"spot-the-signs","type":"reflect","hook":"Lensy: noticing changes early, calmly and without paranoia, is part of being the safe adult. Sit right?","prompt":"What do you think?","options":["Sits right","Calm noticing","Not paranoia"],"affirm":"Calmly noticing changes in your child, without tipping into paranoia, is a core part of keeping them safe.","relearn":"Noticing changes early, calmly and without paranoia, is part of being the safe adult.","persona":"any","source":"calm noticing"},
  {"id":"sa-015","cat":"spot-the-signs","type":"spot","hook":"Spot the two ways of holding the risk that go wrong.","scene":[{"id":"a","text":"Trusting, but staying gently observant","trick":false},{"id":"b","text":"Suspecting everyone with paranoia","trick":true},{"id":"c","text":"Respecting your child's discomfort","trick":false},{"id":"d","text":"Assuming a respectable adult is never a risk","trick":true},{"id":"e","text":"Keeping the door open so they can tell you","trick":false}],"why":"Paranoia and assuming respectability equals safety go wrong; observing, respecting discomfort and an open door protect.","relearn":"Hold the risk by trusting yet observing, respecting discomfort and an open door — not paranoia or blind trust.","persona":"any","source":"calm protective"},
  {"id":"sa-016","cat":"spot-the-signs","type":"branch","hook":"Your child suddenly seems frightened of an adult they used to like.","options":[{"text":"Take it seriously, stay close, and gently find out why","consequence":"You act on an important signal.","outcome":"act-signal","best":true},{"text":"Dismiss it and make them spend time with the adult anyway","consequence":"Forcing the contact ignores your child's instinct."}],"debrief":"Take a child's sudden fear of an adult seriously; stay close and gently find out why, don't force contact.","relearn":"Treat sudden fear of a familiar adult as a signal; stay close and find out why, don't force the contact.","persona":"Kamla","source":"take fear seriously"},
  {"id":"sa-017","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If I never talk about safety, I keep my child innocent and protected.\"","myth":{"un":"If I never talk about safety, I keep my child innocent and protected.","re":"Silence leaves a child unprotected; age-appropriate body-safety and an open door make a child safer, not less innocent.","why":"Knowledge and openness are shields."},"relearn":"Silence doesn't protect; age-appropriate body-safety and an open door make a child safer, not less innocent.","persona":"any","source":"openness protects"},
  {"id":"sa-018","cat":"spot-the-signs","type":"sort","hook":"Sort: helps you spot harm early, or leaves your child exposed?","items":[{"id":"a","text":"Knowing the real warning signs"},{"id":"b","text":"Believing it can't happen to you"},{"id":"c","text":"Trusting your child's discomfort"},{"id":"d","text":"Forcing contact despite their fear"},{"id":"e","text":"Keeping an open, no-blame door"},{"id":"f","text":"Assuming respectability means safety"}],"bins":[{"id":"helps","label":"Helps spot it","valence":"pos"},{"id":"exposes","label":"Leaves them exposed","valence":"neg"}],"key":{"a":"helps","b":"exposes","c":"helps","d":"exposes","e":"helps","f":"exposes"},"relearn":"Knowing signs, trusting discomfort and an open door help; denial, forcing contact and assuming respectability is safety leave a child exposed.","persona":"any","source":"spot or expose"},
  {"id":"sa-019","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"If my child tells me something happened, I should question whether they're making it up.\"","myth":{"un":"If my child tells me something happened, I should question whether they're making it up.","re":"Believe your child; children very rarely lie about abuse, and being believed is vital to their safety and recovery.","why":"Believing is the first protection."},"relearn":"Believe your child if they disclose; children very rarely lie about this, and being believed is vital to their recovery.","persona":"Kamla","source":"believe them"},
  {"id":"sa-020","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"Showing my horror, anger or panic is the natural way to react to a disclosure.\"","myth":{"un":"Showing my horror, anger or panic is the natural way to react to a disclosure.","re":"Strong visible horror or rage can make a child shut down or feel blamed; staying calm and warm keeps them talking and safe.","why":"Your calm is what they need most."},"relearn":"Visible horror or rage can make a disclosing child shut down or feel blamed; stay calm and warm so they keep talking.","persona":"Kamla","source":"stay calm"},
  {"id":"sa-021","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"A child who was harmed must have done something to cause or allow it.\"","myth":{"un":"A child who was harmed must have done something to cause or allow it.","re":"A child is never to blame for abuse; the responsibility is entirely the abuser's, and the child needs to hear that clearly.","why":"The child is always the victim, never at fault."},"relearn":"A child is never to blame for abuse; tell them clearly it is not their fault and they did nothing wrong.","persona":"Kamla","source":"never the child's fault"},
  {"id":"sa-022","cat":"if-they-tell-you","type":"role-play","hook":"Your child haltingly tells you that someone has been hurting them. Your first words matter most of all.","setup":"Respond with calm love:","yourLine":[{"text":"\"Thank you for telling me, I believe you, it's not your fault, and I'm going to keep you safe.\"","best":true},{"text":"\"Are you sure? Why didn't you say something sooner?\""}],"relearn":"'I believe you, it's not your fault, I'll keep you safe' is the response that protects a child and aids their recovery.","persona":"Kamla","source":"first words"},
  {"id":"sa-023","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"I should press my child for every detail right away to get the full story.\"","myth":{"un":"I should press my child for every detail right away to get the full story.","re":"Don't interrogate; let the child share at their own pace in their own words, and leave detailed questioning to trained professionals.","why":"Listening, not interrogating, is the parent's job."},"relearn":"Don't interrogate a disclosing child; let them share at their own pace, and leave detailed questioning to professionals.","persona":"Kamla","source":"don't interrogate"},
  {"id":"sa-024","cat":"if-they-tell-you","type":"match","hook":"Match each disclosure-response step to what it does for the child.","pairs":[{"left":"Assure them they're safe","right":"Calms fear and shame"},{"left":"Believe and stay calm","right":"Keeps them talking, not shut down"},{"left":"Say it's not their fault","right":"Lifts the self-blame that silences them"},{"left":"Let the child talk, then act","right":"Their pace, then real protection"},{"left":"Get safe help, don't hush it","right":"Turns belief into lasting safety"}],"relearn":"Assure, believe and stay calm, say it's not their fault, let them talk then act, and get safe help: the steps that protect a disclosing child.","persona":"Kamla","source":"response steps"},
  {"id":"sa-025","cat":"if-they-tell-you","type":"reflect","hook":"Lensy: how you respond in that first moment shapes your child's safety and their healing. Feel the weight?","prompt":"What do you think?","options":["Feel it","First moment matters","I'll get it right"],"affirm":"A parent's response in the first moment of a disclosure profoundly shapes the child's safety and their healing.","relearn":"How you respond in that first moment shapes your child's safety and their healing.","persona":"Kamla","source":"first moment"},
  {"id":"sa-026","cat":"if-they-tell-you","type":"branch","hook":"Your child discloses something and part of you wants to keep it quiet to avoid scandal.","options":[{"text":"Reassure your child, then take protective action and report","consequence":"You put your child's safety above appearances.","outcome":"protect","best":true},{"text":"Hush it up to protect the family's image","consequence":"Hushing it up leaves a child unprotected."}],"debrief":"After a disclosure, reassure your child and take protective action, never hush it up for the family's image.","relearn":"Protect and report after a disclosure; silencing it for the family's image abandons your child.","persona":"Kamla","source":"safety over image"},
  {"id":"sa-027","cat":"if-they-tell-you","type":"spot","hook":"Lensy: a child has just disclosed. Spot the two responses that harm them.","scene":[{"id":"a","text":"'I believe you, it's not your fault'","trick":false},{"id":"b","text":"Blaming or doubting them out loud","trick":true},{"id":"c","text":"Staying calm and acting to protect","trick":false},{"id":"d","text":"Interrogating them for every detail","trick":true},{"id":"e","text":"'I'm glad you told me, you're safe now'","trick":false}],"why":"Blame, doubt, and interrogation harm a disclosing child; belief, calm, and 'I'm glad you told me' keep them safe.","relearn":"Keep a disclosing child safe with belief, 'it's not your fault', and calm protection; blame, doubt, and interrogation harm them.","persona":"Kamla","source":"safe response"},
  {"id":"sa-028","cat":"if-they-tell-you","type":"role-play","hook":"After a disclosure, your child asks if you still love them and if they're in trouble. You leave no doubt.","setup":"Leave no doubt:","yourLine":[{"text":"\"I love you completely, you are not in any trouble, you were so brave to tell me, and none of this is your fault.\"","best":true},{"text":"\"We'll discuss what you did wrong later.\""}],"relearn":"Unconditional love, 'not in trouble', 'so brave', 'not your fault' is exactly what a child needs to hear to begin healing.","persona":"Kamla","source":"no doubt"},
  {"id":"sa-029","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"What counts as abuse is fuzzy, and the child might share the blame.\"","myth":{"un":"What counts as abuse is fuzzy, and the child might share the blame.","re":"Under India's POCSO Act, any sexual offence against anyone under 18 is a crime, and the child is always the victim, never to blame.","why":"The law is clear: the child is the protected victim."},"relearn":"Under POCSO, any sexual offence against an under-18 is a crime and the child is always the victim, never to blame.","persona":"Kamla","source":"POCSO basics"},
  {"id":"sa-030","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"This is a private family matter; I shouldn't involve the authorities.\"","myth":{"un":"This is a private family matter; I shouldn't involve the authorities.","re":"Child abuse is a crime, not a private matter, and the law obliges reporting; the authorities exist to protect your child.","why":"Reporting protects the child and others."},"relearn":"Child abuse is a crime to report, not a private matter; the law obliges it, and reporting protects your child.","persona":"Kamla","source":"not private"},
  {"id":"sa-031","cat":"the-law-and-the-call","type":"match","hook":"Match each route to when it's for (India).","pairs":[{"left":"Childline 1098","right":"Help for a child in danger or distress"},{"left":"Police / POCSO e-Box","right":"Reporting a sexual offence against a child"},{"left":"Cybercrime 1930","right":"Online child abuse or exploitation"},{"left":"Emergency 112","right":"A child in immediate danger"},{"left":"This game","right":"The basics, not legal advice"}],"relearn":"Childline 1098, police or the e-Box, cybercrime 1930 and 112 are the routes to protect a child.","persona":"Kamla","source":"the routes"},
  {"id":"sa-032","cat":"the-law-and-the-call","type":"sort","hook":"Sort: the right action if a child is being abused, or the wrong one?","items":[{"id":"a","text":"Reporting to Childline or the police"},{"id":"b","text":"Keeping quiet to avoid scandal"},{"id":"c","text":"Believing and protecting the child"},{"id":"d","text":"Confronting the abuser alone, then dropping it"},{"id":"e","text":"Asking a route what to do next"},{"id":"f","text":"Telling the child to forget it"}],"bins":[{"id":"right","label":"Right action","valence":"pos"},{"id":"wrong","label":"Wrong action","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"wrong","e":"right","f":"wrong"},"relearn":"Reporting, believing and asking a route are right; the rest leave a child at risk.","persona":"any","source":"right vs wrong"},
  {"id":"sa-033","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: the law puts the child first and obliges adults to act; you are not overreacting by reporting. Clear?","prompt":"What do you think?","options":["Clear","Child first","Not overreacting"],"affirm":"The law places the child first and obliges adults to report; acting to protect a child is never overreacting.","relearn":"The law puts the child first and obliges adults to act; reporting isn't overreacting.","persona":"any","source":"child first"},
  {"id":"sa-034","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"Reporting will only make things worse for everyone.\"","myth":{"un":"Reporting will only make things worse for everyone.","re":"Not reporting leaves a child in danger and the abuser free to continue; reporting, with support, is how protection begins.","why":"Silence protects the abuser, not the child."},"relearn":"Not reporting leaves a child in danger; reporting, with support, is how real protection begins.","persona":"Kamla","source":"silence protects abuser"},
  {"id":"sa-035","cat":"the-law-and-the-call","type":"branch","hook":"You suspect a child, yours or another, may be being abused.","options":[{"text":"Act on the concern, report it, and let professionals investigate","consequence":"A child gets the protection they need.","outcome":"report","best":true},{"text":"Wait for certain proof before doing anything","consequence":"Waiting for 'proof' can leave a child in harm."}],"debrief":"Act on a reasonable concern of abuse by reporting it; you don't need certain proof to protect a child.","relearn":"Report a reasonable concern and let professionals investigate; you needn't have proof to act.","persona":"Vikram","source":"act on concern"},
  {"id":"sa-036","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two responses that fail to protect a child.","scene":[{"id":"a","text":"Reporting to the right authority","trick":false},{"id":"b","text":"Covering it up for the family","trick":true},{"id":"c","text":"Believing the child and getting help","trick":false},{"id":"d","text":"Paying the abuser to stay silent","trick":true},{"id":"e","text":"Calling Childline 1098 for guidance","trick":false}],"why":"Covering it up and paying off the abuser leave a child in danger; the rest protect them.","relearn":"Protect a child by reporting, believing and calling 1098 — not covering up or paying off.","persona":"any","source":"protective action"},
  {"id":"sa-037","cat":"safe-online-and-off","type":"strike-rewrite","hook":"\"Online dangers to children are exaggerated; the internet is basically safe for kids.\"","myth":{"un":"Online dangers to children are exaggerated; the internet is basically safe for kids.","re":"Online grooming, exploitation and sextortion are real risks; staying involved and keeping the door open protects a child online.","why":"Online harm is real, and parents help most by staying close."},"relearn":"Online grooming, exploitation and sextortion are real risks; staying involved and tellable protects a child online.","persona":"Vikram","source":"online harm is real"},
  {"id":"sa-038","type":"sort","persona":"any","source":"safe or exposed","hook":"Sort: a healthy online-safety habit, or one that leaves a child exposed?","items":[{"id":"a","text":"Talking openly about online risks"},{"id":"b","text":"Total secrecy about what kids do online"},{"id":"c","text":"'Tell me about anyone who makes you uneasy'"},{"id":"d","text":"Banning everything with no conversation"},{"id":"e","text":"Knowing how and where to report"},{"id":"f","text":"Pretending the internet has no risks"}],"bins":[{"id":"x","label":"Healthy safety","valence":"pos"},{"id":"y","label":"Leaves them exposed","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Open talk, an uneasy-flag invite and knowing how to report keep kids safer; secrecy, silent bans and denial expose them.","cat":"safe-online-and-off"},
  {"id":"sa-039","cat":"safe-online-and-off","type":"strike-rewrite","hook":"\"If my child is groomed or exploited online, it's their own fault for engaging.\"","myth":{"un":"If my child is groomed or exploited online, it's their own fault for engaging.","re":"Children are targeted and manipulated by skilled abusers; it is never the child's fault, and they need support, not blame.","why":"Manipulation isn't the child's fault."},"relearn":"Online grooming and exploitation are never the child's fault; abusers manipulate children, who need support, not blame.","persona":"Vikram","source":"not the child's fault"},
  {"id":"sa-040","cat":"safe-online-and-off","type":"branch","hook":"Your child is being pressured or threatened by someone online.","options":[{"text":"Reassure them it's not their fault, keep evidence, and report to cybercrime","consequence":"You respond protectively and act.","outcome":"report-online","best":true},{"text":"Get angry at the child and take the device away as punishment","consequence":"Anger and punishment make them hide the next, worse threat."}],"debrief":"If a child faces online threats, reassure them it's not their fault, keep evidence, and report (cybercrime 1930).","relearn":"Reassure and report (cybercrime 1930); don't punish a child for being targeted.","persona":"Vikram","source":"report online"},
  {"id":"sa-041","type":"match","persona":"any","source":"online practices","hook":"Match each online-safety practice to what it protects.","pairs":[{"left":"An open, no-blame door about online life","right":"A child who'll tell you about danger"},{"left":"Knowing the report routes (1930)","right":"Fast action if something happens"},{"left":"Age-appropriate involvement","right":"A safer online world for your child"},{"left":"Keeping evidence before reporting","right":"A report people can act on"},{"left":"Modelling safe choices yourself","right":"A child who copies the reflex"}],"relearn":"An open door, known routes, involvement, kept evidence and modelling each protect a child online.","cat":"safe-online-and-off"},
  {"id":"sa-042","cat":"safe-online-and-off","type":"reflect","hook":"Lensy: the same rule holds online and off, be the calm, tellable adult your child can turn to. Resonate?","prompt":"What do you think?","options":["Resonates","Online and off","Be tellable"],"affirm":"Online or off, the protection is the same: a calm, tellable adult the child can turn to without blame.","relearn":"Online and off, the rule is the same: be the calm, tellable adult your child can turn to.","persona":"any","source":"same online and off"},
  {"id":"sa-043","type":"spot","persona":"any","source":"safer online","hook":"Spot the two moves that make a child LESS safe online.","scene":[{"id":"a","text":"Staying involved and keeping the door open","trick":false},{"id":"b","text":"Reacting with rage so they hide things","trick":true},{"id":"c","text":"Knowing how and where to report","trick":false},{"id":"d","text":"Blaming them for being targeted","trick":true},{"id":"e","text":"Talking about online tricks before they happen","trick":false}],"why":"Rage that makes a child hide, and blaming a targeted child, make them less safe; involvement, reporting and early talk help.","cat":"safe-online-and-off","relearn":"Rage that makes a child hide and blaming a targeted child make them less safe; involvement and reporting help."},
  {"id":"sa-044","cat":"safe-online-and-off","type":"branch","hook":"Your child shows you a disturbing message from an online contact.","options":[{"text":"Stay calm, thank them, keep it as evidence, and report it","consequence":"Your child learns telling you works.","outcome":"calm-report","best":true},{"text":"Panic and blame them for talking to strangers","consequence":"Panic and blame teach them to hide future dangers."}],"debrief":"When a child shows you a disturbing online message, stay calm, thank them, keep evidence and report it.","relearn":"Thank a child for showing you a disturbing message and report it calmly; panic and blame teach them to hide.","persona":"Vikram","source":"calm and report"},
  {"id":"sa-045","cat":"tools-and-respond","type":"branch","hook":"You want to be genuinely ready to protect your child, not just hope for the best.","options":[{"text":"Learn the signs, the response steps, and save the helplines now","consequence":"You can act calmly and correctly if you ever need to.","outcome":"ready","best":true},{"text":"Assume you'll know what to do in the moment","consequence":"Hoping you'll just know leaves you unprepared."}],"debrief":"Be ready: learn the signs and disclosure-response steps and save the helplines before you ever need them.","relearn":"Prepare now; crisis is the hardest time to learn the signs, steps and helplines.","persona":"Kamla","source":"be ready"},
  {"id":"sa-046","cat":"tools-and-respond","type":"match","hook":"Match each tool to what it does.","pairs":[{"left":"The signs checklist","right":"Knowing what to notice, calmly"},{"left":"The disclosure-response steps","right":"Believe, calm, no blame, act"},{"left":"The helpline card (1098, 1930)","right":"Exactly who to call"},{"left":"The open, no-blame door","right":"Why a child comes to you at all"},{"left":"Calm preparation in advance","right":"Being ready before the moment"}],"relearn":"The signs checklist, the response steps, the helpline card, an open door and calm preparation are the safe-adult tools.","persona":"any","source":"the toolkit"},
  {"id":"sa-047","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"Once my child is older, none of this safeguarding matters anymore.\"","myth":{"un":"Once my child is older, none of this safeguarding matters anymore.","re":"Being tellable, alert and ready matters at every age, online and off; the safe adult stays the safe adult.","why":"Safeguarding is lifelong, not a stage."},"relearn":"Safeguarding matters at every age, online and off; being a tellable, ready adult never stops mattering.","persona":"any","source":"lifelong safeguarding"},
  {"id":"sa-048","cat":"tools-and-respond","type":"reflect","hook":"Lensy: the whole kids' journey tells children to 'tell a trusted adult', this is the node that makes that adult real. Feel it?","prompt":"What do you think?","options":["Feel it","Make it real","Be that adult"],"affirm":"Every part of a child's learning tells them to tell a trusted adult; being that adult is what makes all of it work.","relearn":"The whole journey tells kids to tell a trusted adult; you are the node that makes that adult real.","persona":"any","source":"make it real"},
  {"id":"sa-049","cat":"tools-and-respond","type":"role-play","hook":"A friend's child has disclosed something and the friend is panicking. You want to guide them to respond right.","setup":"Guide them calmly:","yourLine":[{"text":"\"Believe your child, stay calm, tell them it's not their fault, and let's call Childline 1098 together.\"","best":true},{"text":"\"Don't tell anyone, just deal with it quietly at home.\""}],"relearn":"Guiding a panicking friend to believe, stay calm, not blame and call Childline is exactly the right, protective help.","persona":"Divya","source":"guide a friend"},
  {"id":"sa-050","cat":"tools-and-respond","type":"sort","hook":"Sort: the right priority when a child may be in danger, or the wrong one?","items":[{"id":"a","text":"The child's immediate safety"},{"id":"b","text":"Avoiding embarrassment"},{"id":"c","text":"Getting them the right help fast"},{"id":"d","text":"Protecting an adult's reputation"},{"id":"e","text":"Believing and reassuring the child"},{"id":"f","text":"Keeping it quiet for the family"}],"bins":[{"id":"right","label":"Right priority","valence":"pos"},{"id":"wrong","label":"Wrong priority","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"wrong","e":"right","f":"wrong"},"relearn":"The child's safety, fast help and believing them are right priorities; embarrassment, reputation and secrecy aren't.","persona":"any","source":"right priority"},
  {"id":"sa-051","cat":"tools-and-respond","type":"spot","hook":"Spot the two lines that are NOT the safe-adult mindset.","scene":[{"id":"a","text":"'My child's safety comes before everything'","trick":false},{"id":"b","text":"'Our image matters more than this'","trick":true},{"id":"c","text":"'I believe, I stay calm, I act'","trick":false},{"id":"d","text":"'Better to keep this quiet for the family'","trick":true},{"id":"e","text":"'My door is always open, no blame'","trick":false}],"why":"'Image over this' and 'keep it quiet' aren't the safe-adult mindset; safety-first, 'believe-calm-act' and an open door are.","relearn":"The safe adult puts safety first, lives 'I believe, I stay calm, I act' and keeps an open door, never image over the child.","persona":"Kamla","source":"safe-adult mindset"},
  {"id":"sa-052","cat":"tools-and-respond","type":"reflect","hook":"Lensy: be tellable, notice the signs, believe and stay calm, know the law and the call. You complete the whole circle. Ready?","prompt":"What's your take?","options":["Ready","I complete the circle","Be the safe adult"],"affirm":"Being tellable, noticing signs, believing and staying calm, and knowing the law and the call make you the safe adult the whole journey needs.","relearn":"Be tellable, notice the signs, believe and stay calm, know the law and the call, and you are the safe adult.","persona":"any","source":"complete the circle"},
  {"id":"sa-053","cat":"tools-and-respond","type":"role-play","hook":"Your co-parent wants to keep a disclosure quiet to avoid family conflict. You want to hold the line for your child.","setup":"Hold the line:","yourLine":[{"text":"\"Our child's safety comes first, we believe them, we protect them, and we report, together.\"","best":true},{"text":"\"Fine, let's keep it quiet to keep the peace.\""}],"relearn":"Holding the line that the child's safety comes first, and reporting together, protects the child over family peace.","persona":"Vikram","source":"hold the line"},
  {"id":"sa-054","cat":"be-tellable","type":"role-play","hook":"Your child admits to a mistake they were scared to mention. You want to reward the honesty, not the error.","setup":"Reward the honesty:","yourLine":[{"text":"\"I'm really glad you told me, that took courage, let's sort it out together.\"","best":true},{"text":"\"How could you? You're in big trouble now.\""}],"relearn":"Praising the courage to tell, even about a mistake, keeps the door open for the things that matter most.","persona":"Divya","source":"reward honesty"},
  {"id":"sa-055","cat":"be-tellable","type":"sort","hook":"Sort: makes a child more likely to confide, or less?","items":[{"id":"a","text":"Calm, listening responses"},{"id":"b","text":"Mocking or dismissing their worries"},{"id":"c","text":"'No topic is off-limits with me'"},{"id":"d","text":"Big reactions that scare them"},{"id":"e","text":"Believing them the first time"},{"id":"f","text":"Telling their secrets to relatives"}],"bins":[{"id":"more","label":"More likely to tell","valence":"pos"},{"id":"less","label":"Less likely","valence":"neg"}],"key":{"a":"more","b":"less","c":"more","d":"less","e":"more","f":"less"},"relearn":"Calm listening, 'no topic off-limits' and being believed make a child confide; mockery, scary reactions and gossip make them clam up.","persona":"any","source":"more or less"},
  {"id":"sa-056","cat":"be-tellable","type":"branch","hook":"You're tempted to react with anger to keep your child 'in line'.","options":[{"text":"Choose calm connection so they stay willing to tell you things","consequence":"You protect the channel they may one day need.","outcome":"channel","best":true},{"text":"Rule by fear and lose their confidences","consequence":"Ruling by fear closes the channel just when it matters most."}],"debrief":"Choose calm connection over fear; a child who fears you stops telling you what you most need to hear.","relearn":"Keep the telling-channel open with calm connection; fear closes it exactly when a child needs it.","persona":"Vikram","source":"keep the channel"},
  {"id":"sa-057","cat":"be-tellable","type":"role-play","hook":"You want to make a simple family promise about telling. You say it warmly to your kids.","setup":"Make the promise:","yourLine":[{"text":"\"In our home, you can tell us anything, and we will listen, believe you, and help, always.\"","best":true},{"text":"\"Children should be seen and not heard in this house.\""}],"relearn":"A clear family promise to listen, believe and help builds the tellability that keeps children safe.","persona":"Priya","source":"family promise"},
  {"id":"sa-058","cat":"be-tellable","type":"match","hook":"Match each parent habit to the message a child receives.","pairs":[{"left":"Listening without interrupting","right":"What I feel matters to them"},{"left":"Calm with bad news","right":"I won't get in trouble for telling"},{"left":"Following through to help","right":"Telling actually changes things"},{"left":"Keeping a promise to them","right":"I can trust what they say"},{"left":"Honouring their 'no'","right":"My boundaries are respected here"}],"relearn":"Listening, staying calm, following through, keeping promises and honouring 'no' tell a child that confiding in you is safe.","persona":"any","source":"habit to message"},
  {"id":"sa-059","cat":"spot-the-signs","type":"role-play","hook":"You want to gently check in on a child who seems withdrawn, without alarming them.","setup":"Check in gently:","yourLine":[{"text":"\"You've seemed a bit quiet lately, I'm here and I love you, is there anything you want to tell me?\"","best":true},{"text":"\"What's wrong with you these days? Snap out of it.\""}],"relearn":"A gentle, loving check-in invites a withdrawn child to open up, where impatience makes them retreat further.","persona":"Meena","source":"gentle check-in"},
  {"id":"sa-060","cat":"spot-the-signs","type":"sort","hook":"Sort: a reason to gently pay closer attention, or just normal variation?","items":[{"id":"a","text":"Sudden secrecy and fear around one adult"},{"id":"b","text":"A normal phase of moodiness"},{"id":"c","text":"Unexplained marks plus distress"},{"id":"d","text":"Preferring friends to family outings"},{"id":"e","text":"Going silent and clingy after one person's visits"},{"id":"f","text":"Getting tired of an old hobby"}],"bins":[{"id":"attention","label":"Pay attention","valence":"uhoh"},{"id":"normal","label":"Normal variation","valence":"pos"}],"key":{"a":"attention","b":"normal","c":"attention","d":"normal","e":"attention","f":"normal"},"relearn":"Sudden fear, marks plus distress and new silence after a visit warrant attention; moodiness and bored hobbies are normal.","persona":"any","source":"attention or normal"},
  {"id":"sa-061","cat":"spot-the-signs","type":"branch","hook":"Another adult dismisses your concern about how someone behaves around your child.","options":[{"text":"Trust your instinct and keep your child safe anyway","consequence":"You act as the safe adult regardless.","outcome":"trust-instinct","best":true},{"text":"Let yourself be talked out of your worry","consequence":"Being talked out of a real worry can leave them exposed."}],"debrief":"Trust your protective instinct about someone around your child, even if another adult dismisses your concern.","relearn":"Act on your protective instinct even if others dismiss it; better safe than sorry where a child is concerned.","persona":"Kamla","source":"trust your instinct"},
  {"id":"sa-062","cat":"spot-the-signs","type":"match","hook":"Match each protective practice to what it guards against.","pairs":[{"left":"Knowing grooming red flags","right":"Manipulation by a trusted adult"},{"left":"Respecting your child's 'no'","right":"Eroded boundaries"},{"left":"Staying gently observant","right":"Harm going unnoticed"},{"left":"Trusting your child's discomfort","right":"Their instinct being overruled"},{"left":"Holding the known-adult risk in mind","right":"False comfort in respectability"}],"relearn":"Knowing flags, respecting a child's 'no', staying observant, trusting discomfort and remembering the known-adult risk each guard against how harm takes hold.","persona":"Kamla","source":"practice guards"},
  {"id":"sa-063","cat":"spot-the-signs","type":"spot","hook":"Spot the two off-balance ways to handle the risk.","scene":[{"id":"a","text":"Warm trust plus quiet vigilance","trick":false},{"id":"b","text":"Blind trust that nobody known could harm a child","trick":true},{"id":"c","text":"Believing a child's discomfort","trick":false},{"id":"d","text":"Total paranoia, treating everyone as a danger","trick":true},{"id":"e","text":"Keeping an open, no-blame door","trick":false}],"why":"Blind trust and total paranoia are both off-balance; warm vigilance, belief and an open door keep a child safe.","relearn":"Keep a child safe with warm trust, quiet vigilance, believing their discomfort and an open door.","persona":"any","source":"balanced safety"},
  {"id":"sa-064","cat":"if-they-tell-you","type":"role-play","hook":"Your child is crying and struggling to get the words out. You want to make it safe to speak.","setup":"Make it safe:","yourLine":[{"text":"\"Take your time, you're safe now, I'm right here and I'm listening, whatever it is.\"","best":true},{"text":"\"Stop crying and just tell me exactly what happened, now.\""}],"relearn":"Gently giving a child time and safety to speak, at their own pace, helps far more than pressing for a fast account.","persona":"Kamla","source":"make it safe"},
  {"id":"sa-065","cat":"if-they-tell-you","type":"sort","hook":"Sort each response to a child who has disclosed: does it help them, or harm them?","items":[{"id":"a","text":"'I believe you and it's not your fault'"},{"id":"b","text":"'Are you sure you didn't imagine it?'"},{"id":"c","text":"Staying calm and protective"},{"id":"d","text":"Anger that frightens them into silence"},{"id":"e","text":"'I'm so glad you told me'"},{"id":"f","text":"Pressing them for every detail at once"}],"bins":[{"id":"helps","label":"Helps the child","valence":"pos"},{"id":"harms","label":"Harms them","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Belief, 'not your fault', calm protection, and 'I'm glad you told me' help; doubt, frightening anger, and pressing for detail harm a disclosing child.","persona":"Kamla","source":"helps or harms"},
  {"id":"sa-066","cat":"if-they-tell-you","type":"branch","hook":"Your child begs you not to tell anyone about what they disclosed.","options":[{"text":"Reassure them, but gently explain you must get safe help to protect them","consequence":"You honour their feelings and their safety.","outcome":"safe-help","best":true},{"text":"Promise total secrecy to calm them","consequence":"Promising total secrecy can trap you both and leave them unprotected."}],"debrief":"Don't promise a disclosing child total secrecy; reassure them, and gently get the safe help that protects them.","relearn":"Reassure a frightened child, but get safe help; promising to tell no one can endanger them.","persona":"Kamla","source":"no secrecy promise"},
  {"id":"sa-067","cat":"if-they-tell-you","type":"role-play","hook":"Days after a disclosure, your child seems to be checking whether you still see them the same way. You reassure them.","setup":"Reassure warmly:","yourLine":[{"text":"\"Nothing about what happened changes how much I love you or how proud I am of you for telling me.\"","best":true},{"text":"\"Let's just put it behind us and never speak of it.\""}],"relearn":"Reassuring a child that the disclosure changed nothing about your love, and not silencing it, supports their healing.","persona":"Kamla","source":"still the same love"},
  {"id":"sa-068","cat":"the-law-and-the-call","type":"role-play","hook":"You're scared to make the report and want to talk yourself into it. You picture the call.","setup":"Make the call:","yourLine":[{"text":"\"I need to report something to protect a child, can you help me with what to do next?\"","best":true},{"text":"\"Actually, maybe it's not my place, I'll stay out of it.\""}],"relearn":"A simple call to report and protect a child is exactly your place; the people on the line will guide you through it.","persona":"Vikram","source":"make the report"},
  {"id":"sa-069","cat":"the-law-and-the-call","type":"sort","hook":"Sort: aligns with protecting the child, or works against it?","items":[{"id":"a","text":"Reporting a sexual offence against a child"},{"id":"b","text":"Treating the child as partly to blame"},{"id":"c","text":"Keeping the child as the protected victim"},{"id":"d","text":"Hiding it to shield an adult"},{"id":"e","text":"Letting professionals investigate"},{"id":"f","text":"Settling it privately for money"}],"bins":[{"id":"protects","label":"Protects the child","valence":"pos"},{"id":"against","label":"Works against it","valence":"neg"}],"key":{"a":"protects","b":"against","c":"protects","d":"against","e":"protects","f":"against"},"relearn":"Reporting, keeping the child as victim and letting pros investigate align; the rest work against it.","persona":"any","source":"protects or against"},
  {"id":"sa-070","cat":"the-law-and-the-call","type":"branch","hook":"You worry that reporting will bring shame on the family.","options":[{"text":"Put the child's safety first and report; shame belongs to the abuser, not the child","consequence":"You protect the child as the law intends.","outcome":"child-first","best":true},{"text":"Protect the family name over the child","consequence":"Protecting the family name leaves the child in harm and the abuser free."}],"debrief":"Report to protect the child even if you fear family shame; the shame belongs to the abuser, never the child.","relearn":"Choose the child's safety over the family name; the shame is the abuser's.","persona":"Kamla","source":"child over name"},
  {"id":"sa-071","cat":"the-law-and-the-call","type":"match","hook":"Match each fact under the law to what it means.","pairs":[{"left":"An offence vs an under-18 is a crime","right":"It must be taken seriously"},{"left":"The child is always the victim","right":"Never blame the child"},{"left":"Reporting is obliged","right":"Acting is required, not optional"},{"left":"An under-18 cannot consent","right":"Their 'yes' can't make it legal"},{"left":"This is the basics","right":"Route real concerns to authorities"}],"relearn":"An offence against a child is a serious crime; the child is the victim; reporting is required.","persona":"Kamla","source":"law facts"},
  {"id":"sa-072","cat":"the-law-and-the-call","type":"sort","hook":"Sort: a route that gets a child protection, or a dead end?","items":[{"id":"a","text":"Childline 1098"},{"id":"b","text":"Telling no one and hoping"},{"id":"c","text":"The police or POCSO e-Box"},{"id":"d","text":"Just warning the abuser off"},{"id":"e","text":"Cybercrime 1930 for online harm"},{"id":"f","text":"Posting about it on social media"}],"bins":[{"id":"route","label":"A real route","valence":"pos"},{"id":"deadend","label":"A dead end","valence":"neg"}],"key":{"a":"route","b":"deadend","c":"route","d":"deadend","e":"route","f":"deadend"},"relearn":"Childline 1098, police or e-Box and cybercrime 1930 get protection; the rest are dead ends.","persona":"any","source":"route or dead end"},
  {"id":"sa-073","cat":"the-law-and-the-call","type":"branch","hook":"You're unsure whether what you've learned is 'serious enough' to report.","options":[{"text":"Report it and let the professionals decide; you don't have to be certain","consequence":"A child gets a proper, expert assessment.","outcome":"let-pros","best":true},{"text":"Decide it's probably nothing and drop it","consequence":"Deciding it's 'probably nothing' can leave real harm unaddressed."}],"debrief":"Report a concern even if unsure it's serious enough; professionals assess it, you needn't be certain.","relearn":"Report when unsure; let professionals decide, rather than dropping a concern that may be real.","persona":"Vikram","source":"let pros decide"},
  {"id":"sa-074","cat":"safe-online-and-off","type":"role-play","hook":"You want your child to feel safe telling you about anything creepy online. You set that up.","setup":"Set it up warmly:","yourLine":[{"text":"\"If anyone online ever makes you uncomfortable or asks for something odd, just tell me, you'll never be in trouble.\"","best":true},{"text":"\"If you talk to strangers online, that's your own fault.\""}],"relearn":"Promising no-trouble openness about anything creepy online makes a child far likelier to tell you before harm grows.","persona":"Vikram","source":"creepy online"},
  {"id":"sa-075","type":"sort","persona":"any","source":"protect or expose","hook":"Sort: protects a child online, or leaves them exposed?","items":[{"id":"a","text":"An open, no-blame door about online life"},{"id":"b","text":"Shaming them for being targeted"},{"id":"c","text":"Knowing how to report (1930)"},{"id":"d","text":"Assuming the internet is harmless"},{"id":"e","text":"Keeping evidence of online abuse"},{"id":"f","text":"Punishing a child who tells you"}],"bins":[{"id":"x","label":"Protects online","valence":"pos"},{"id":"y","label":"Leaves exposed","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"An open door, knowing how to report and keeping evidence protect; shaming, assuming harmlessness and punishing telling expose.","cat":"safe-online-and-off"},
  {"id":"sa-076","cat":"safe-online-and-off","type":"branch","hook":"Your child confides that they shared something online they now regret and are scared.","options":[{"text":"Reassure them it's not the end, keep evidence, and get help to handle it","consequence":"You turn fear into a handled situation.","outcome":"handled","best":true},{"text":"Shame and punish them, deepening the fear","consequence":"Shame and punishment make them hide future danger."}],"debrief":"If a child regrets something shared online, reassure them, keep evidence and get help; don't shame them.","relearn":"Meet an online regret with reassurance and support; shame drives the next danger underground.","persona":"Vikram","source":"reassure and handle"},
  {"id":"sa-077","type":"match","persona":"Vikram","source":"risk to move","hook":"Match each online risk to a protective parent move.","pairs":[{"left":"Online grooming","right":"Stay involved and keep the door open"},{"left":"Pressure or threats","right":"Keep evidence and report to 1930"},{"left":"Regret over something shared","right":"Calm support, not punishment"},{"left":"A stranger wanting to meet","right":"Calmly refuse and explain why"},{"left":"A child gone secretive online","right":"A gentle, no-blame check-in"}],"relearn":"Grooming, threats, regret, a meet-up request and new secrecy each meet a protective move that keeps a child safe and talking.","cat":"safe-online-and-off"},
  {"id":"sa-078","cat":"safe-online-and-off","type":"role-play","hook":"A friend is panicking that their child is being targeted online. You want to steady them toward action.","setup":"Steady them toward action:","yourLine":[{"text":"\"Stay calm, support your child, save the messages, and report to cybercrime 1930, that's how you protect them.\"","best":true},{"text":"\"Just smash the phone and hope it stops.\""}],"relearn":"Steadying a friend toward reassurance, evidence and reporting protects the child better than a panicked over-reaction.","persona":"Divya","source":"steady to action"},
  {"id":"sa-079","type":"spot","persona":"any","source":"safest online","hook":"Spot the two reactions that put a child at risk online.","scene":[{"id":"a","text":"Being the calm, tellable adult about online life","trick":false},{"id":"b","text":"Reacting so harshly they hide things","trick":true},{"id":"c","text":"Knowing the report routes","trick":false},{"id":"d","text":"Telling them they should have known better","trick":true},{"id":"e","text":"Keeping the door open after a scare","trick":false}],"why":"A harsh reaction that makes them hide, and 'you should have known better', put a child at risk; calm, routes and an open door protect.","cat":"safe-online-and-off","relearn":"A harsh reaction that makes them hide, and 'you should have known better', put a child at risk online."},
  {"id":"sa-080","cat":"tools-and-respond","type":"role-play","hook":"You want to set up your phone so the right help is one tap away. You tell your co-parent the plan.","setup":"Make it concrete:","yourLine":[{"text":"\"Let's save Childline 1098 and cybercrime 1930 now, so if we ever need them, help is one tap away.\"","best":true},{"text":"\"We'll look up numbers if something ever happens.\""}],"relearn":"Saving the key helplines in advance means that in a frightening moment, the right help is instantly to hand.","persona":"Vikram","source":"save the numbers"},
  {"id":"sa-081","cat":"tools-and-respond","type":"sort","hook":"Sort: a green-flag safe-adult habit, or one to change?","items":[{"id":"a","text":"An open, no-blame door"},{"id":"b","text":"Punishing children for telling the truth"},{"id":"c","text":"Knowing the signs and routes"},{"id":"d","text":"Assuming it could never happen"},{"id":"e","text":"Saving the helpline numbers"},{"id":"f","text":"Promising a child total secrecy"}],"bins":[{"id":"green","label":"Green-flag habit","valence":"pos"},{"id":"change","label":"Habit to change","valence":"neg"}],"key":{"a":"green","b":"change","c":"green","d":"change","e":"green","f":"change"},"relearn":"An open door, knowing the routes and saved numbers are green flags; punishing honesty, denial and secrecy promises aren't.","persona":"any","source":"green or change"},
  {"id":"sa-082","cat":"tools-and-respond","type":"branch","hook":"You realise you've been avoiding learning about this because it's frightening.","options":[{"text":"Face it calmly now, so you can protect calmly later","consequence":"Your preparedness becomes your child's safety.","outcome":"prepared","best":true},{"text":"Keep avoiding it and stay unprepared","consequence":"Avoiding it leaves you unready when it matters."}],"debrief":"Face this hard topic calmly now so you can respond calmly and protect your child if you ever need to.","relearn":"Prepare despite the fear; an informed, ready parent is a child's safety when it counts.","persona":"Kamla","source":"face it now"},
  {"id":"sa-083","cat":"tools-and-respond","type":"match","hook":"Match a moment to the safe-adult tool for it.","pairs":[{"left":"A child seems withdrawn","right":"A gentle, open check-in"},{"left":"A child discloses","right":"Believe, stay calm, no blame, act"},{"left":"You need to report abuse","right":"Childline 1098"},{"left":"Harm came from online","right":"Cybercrime 1930"},{"left":"A child is in danger now","right":"Emergency 112"}],"relearn":"Each moment has its tool: a check-in for withdrawal, the steps on a disclosure, and the right helpline to report.","persona":"Kamla","source":"moment to tool"},
  {"id":"sa-084","cat":"tools-and-respond","type":"role-play","hook":"Your child has come through something hard with your support, and you want to affirm them. You tell them.","setup":"Affirm them:","yourLine":[{"text":"\"You were so brave, none of it was your fault, and I will always be here as the person you can tell anything.\"","best":true},{"text":"\"Let's never mention this again, it's embarrassing.\""}],"relearn":"Affirming a child's bravery, their blamelessness and your permanent open door supports healing far more than silence.","persona":"Kamla","source":"affirm them"},
  {"id":"sa-900","cat":"be-tellable","type":"strike-rewrite","hook":"\"If something was really wrong, my child would just blurt it out at dinner.\"","myth":{"un":"If something was really wrong, my child would just blurt it out at dinner.","re":"Children often hold the hardest things back the longest; they tell when they already feel safe, so you build that safety first.","why":"Telling follows safety, not the other way round."},"relearn":"Children hold the hardest things back the longest; they open up only after they already feel safe with you.","persona":"Kamla","source":"hardest held longest"},
  {"id":"sa-901","cat":"be-tellable","type":"strike-rewrite","hook":"\"A child who really loved me would never keep a secret from me.\"","myth":{"un":"A child who really loved me would never keep a secret from me.","re":"Silence is about fear and threats, never about love; a child can adore you and still be too frightened to speak.","why":"Read silence as fear, not as proof of less love."},"relearn":"A child can love you deeply and still stay silent out of fear; silence is never a measure of their love.","persona":"any","source":"love and silence"},
  {"id":"sa-902","cat":"be-tellable","type":"strike-rewrite","hook":"\"Talking to my kids about body-safety will just scare them and steal their innocence.\"","myth":{"un":"Talking to my kids about body-safety will just scare them and steal their innocence.","re":"Calm, age-appropriate body-safety makes a child safer and more confident, not less innocent; not knowing is what leaves them exposed.","why":"Knowing keeps a child safe; silence leaves the gap an abuser uses."},"relearn":"Calm, age-appropriate body-safety makes a child safer and more confident, not less innocent.","persona":"Priya","source":"safer not less innocent"},
  {"id":"sa-903","cat":"be-tellable","type":"strike-rewrite","hook":"\"My child tells me everything already, so I don't need to do anything special.\"","myth":{"un":"My child tells me everything already, so I don't need to do anything special.","re":"A child who shares small things may still freeze on the frightening ones; saying out loud 'you can tell me anything, no trouble' is what covers those too.","why":"Everyday chatter and a frightening secret are not the same channel."},"relearn":"A chatty child can still freeze on the scary things; say out loud that they can tell you anything, no trouble.","persona":"Vikram","source":"chatty but frozen"},
  {"id":"sa-904","cat":"be-tellable","type":"strike-rewrite","hook":"\"If I react strongly when they confess small lies, they'll learn to be honest.\"","myth":{"un":"If I react strongly when they confess small lies, they'll learn to be honest.","re":"Big reactions teach a child that honesty is dangerous, so they hide more; calm responses to small confessions are what build real honesty.","why":"Children avoid whatever brings a blow-up — including telling you."},"relearn":"Strong reactions to small confessions teach a child that honesty is dangerous; calm builds real honesty.","persona":"any","source":"reaction teaches hiding"},
  {"id":"sa-905","cat":"be-tellable","type":"strike-rewrite","hook":"\"Being a strict, feared parent keeps kids in line and safe.\"","myth":{"un":"Being a strict, feared parent keeps kids in line and safe.","re":"A child who fears your anger hides exactly the trouble you most need to hear; warmth, not fear, keeps the telling-channel open.","why":"Fear closes the door an abuser most wants closed."},"relearn":"A feared parent gets silence on the things that matter most; warmth keeps a child willing to tell you.","persona":"Kamla","source":"feared closes door"},
  {"id":"sa-906","cat":"be-tellable","type":"strike-rewrite","hook":"\"Other people's kids get hurt because their parents were careless. Mine are fine.\"","myth":{"un":"Other people's kids get hurt because their parents were careless. Mine are fine.","re":"Harm can reach any child in any home; 'it can't touch us' is the complacency that leaves a family unprepared.","why":"Believing you're immune is what stops you building protection."},"relearn":"Harm can reach any child in any home; 'it can't touch us' is the complacency that leaves you unready.","persona":"Divya","source":"no family immune"},
  {"id":"sa-907","cat":"be-tellable","type":"strike-rewrite","hook":"\"If I tell my child they can come to me 'with anything', they'll bring me endless nonsense.\"","myth":{"un":"If I tell my child they can come to me 'with anything', they'll bring me endless nonsense.","re":"A child who feels free to bring small things is exactly the child who will bring the big, frightening one; the small stuff is the practice run.","why":"Every small telling rehearses the day it really counts."},"relearn":"Welcoming the small tellings is how a child learns to bring you the big, frightening one too.","persona":"any","source":"small is practice"},
  {"id":"sa-908","cat":"be-tellable","type":"strike-rewrite","hook":"\"My child is shy and quiet by nature, so there's no point trying to make them open up.\"","myth":{"un":"My child is shy and quiet by nature, so there's no point trying to make them open up.","re":"Even a quiet child tells when telling feels safe; you build that with steady, no-blame openness, not by forcing words.","why":"Tellability is about safety you offer, not your child's temperament."},"relearn":"Even a quiet child will tell when it feels safe; build that with steady, no-blame openness over time.","persona":"Meena","source":"quiet still tells"},
  {"id":"sa-909","cat":"be-tellable","type":"strike-rewrite","hook":"\"If anything happened, I'd just be able to tell from my child's face.\"","myth":{"un":"If anything happened, I'd just be able to tell from my child's face.","re":"Frightened children often hide their distress well; you can't rely on reading them, so you build a door they'll choose to walk through.","why":"A built, open door beats hoping you'll guess."},"relearn":"You can't rely on reading a frightened child's face; build an open door they'll choose to come through.","persona":"Vikram","source":"cannot just read them"},
  {"id":"sa-910","cat":"be-tellable","type":"strike-rewrite","hook":"\"Disclosure is the school's or counsellor's job; at home we just keep things normal.\"","myth":{"un":"Disclosure is the school's or counsellor's job; at home we just keep things normal.","re":"A child tells the adult they feel safest with, and for most that is a parent at home; being tellable yourself is not something to outsource.","why":"You may be the very person your child chooses to tell."},"relearn":"A child tells whoever feels safest — often a parent at home; being tellable is your job, not only the school's.","persona":"any","source":"not outsourced"},
  {"id":"sa-911","cat":"be-tellable","type":"reflect","hook":"Lensy: a child decides you're 'safe to tell' long before anything ever happens. Worth getting ready now?","prompt":"What's your take?","options":["Worth it","Get ready now","Build it early"],"affirm":"Children decide who is safe to tell well before they ever need to; building that door early is real protection.","relearn":"Children decide who is safe to tell long before they need to; build that openness early, on purpose.","persona":"Kamla","source":"safe decided early"},
  {"id":"sa-912","cat":"be-tellable","type":"reflect","hook":"Lensy: 'You can tell me anything and I'll never stop loving you.' Imagine saying that to your child today.","prompt":"How does that land?","options":["I'll say it","Lands warm","They should hear it"],"affirm":"Hearing 'you can tell me anything and I'll never stop loving you' is exactly the safety a child needs to speak.","relearn":"Telling a child 'you can tell me anything and I'll never stop loving you' gives them the safety to speak up.","persona":"Priya","source":"never stop loving"},
  {"id":"sa-913","cat":"be-tellable","type":"reflect","hook":"Lensy: the way you handle the small worry today is the rehearsal for the big one later. Sit right?","prompt":"What do you think?","options":["Sits right","It's rehearsal","Handle small well"],"affirm":"How you meet a small worry is the rehearsal a child remembers when they have a frightening one to bring you.","relearn":"How you handle a child's small worry is the rehearsal for whether they bring you the big, frightening one.","persona":"any","source":"small is rehearsal"},
  {"id":"sa-914","cat":"be-tellable","type":"reflect","hook":"Lensy: a child's silence is almost always fear, not a sign they don't trust or love you. Worth remembering?","prompt":"What's your take?","options":["Worth remembering","It's fear","Not betrayal"],"affirm":"Reading silence as fear rather than betrayal keeps you gentle and open — exactly what helps a child come back.","relearn":"A child's silence is almost always fear, not betrayal; reading it that way keeps you open and gentle.","persona":"Kamla","source":"silence is fear"},
  {"id":"sa-915","cat":"be-tellable","type":"reflect","hook":"Lensy: you don't have to be a perfect parent to be a tellable one — just a calm, no-blame door. Agree?","prompt":"How does that sit?","options":["I agree","Just be the door","Calm, no blame"],"affirm":"You don't need to be perfect to be tellable; a calm, no-blame door is what a child actually needs from you.","relearn":"You don't have to be a perfect parent to be a tellable one — just a calm, no-blame door a child can reach.","persona":"Meena","source":"not perfect, tellable"},
  {"id":"sa-916","cat":"be-tellable","type":"reflect","hook":"Lensy: when your child says 'can I tell you something?', the next ten seconds matter more than anything. Feel that?","prompt":"What do you think?","options":["I feel it","Ten seconds matter","Stay calm then"],"affirm":"Those first calm, welcoming seconds after 'can I tell you something?' decide whether the rest ever comes out.","relearn":"The first calm, welcoming seconds after 'can I tell you something?' decide whether the rest ever comes out.","persona":"any","source":"first ten seconds"},
  {"id":"sa-917","cat":"be-tellable","type":"reflect","hook":"Lensy: if you've reacted with anger to a telling before, you can repair it and reopen the door. Believe that?","prompt":"What's your take?","options":["I believe it","I can repair","Reopen the door"],"affirm":"Even after a harsh reaction, a calm repair — 'I'm sorry I snapped, you can always tell me' — reopens the door.","relearn":"Even after reacting harshly, a calm repair reopens the door: 'I'm sorry I snapped; you can always tell me.'","persona":"Vikram","source":"repair reopens"},
  {"id":"sa-918","cat":"be-tellable","type":"reflect","hook":"Lensy: 'no topic is too embarrassing for us to talk about' is a gift you can give your child. Worth giving?","prompt":"How does that land?","options":["Worth giving","Nothing's too awkward","I'll offer it"],"affirm":"Telling a child 'no topic is too embarrassing for us' removes the shame that keeps the scariest things hidden.","relearn":"'No topic is too embarrassing for us' removes the shame that keeps the scariest things hidden from you.","persona":"any","source":"nothing too awkward"},
  {"id":"sa-919","cat":"be-tellable","type":"role-play","hook":"Bedtime feels calm. You want to plant the open-door message before anything ever goes wrong. You say it gently.","setup":"Plant the message:","yourLine":[{"text":"\"Anytime someone makes you feel scared, yucky or confused, you come tell me — even at midnight, even if they said not to.\"","best":true},{"text":"\"Just be a good kid and don't get into any trouble, okay?\""}],"relearn":"Telling a child in advance to come to you even if someone said not to dismantles the secrecy abusers rely on.","persona":"Kamla","source":"even if they said not to"},
  {"id":"sa-920","cat":"be-tellable","type":"role-play","hook":"Your child blurts out a worry, then mumbles 'never mind, forget it'. You don't want the door to close. You answer.","setup":"Keep the door open:","yourLine":[{"text":"\"It's okay, take your time — I'm here and I'm not going anywhere whenever you're ready.\"","best":true},{"text":"\"Fine, if you don't want to say it, don't waste my time.\""}],"relearn":"When a child half-tells then retreats, patient 'take your time, I'm here' keeps the door open for the rest.","persona":"Divya","source":"take your time"},
  {"id":"sa-921","cat":"be-tellable","type":"role-play","hook":"Your child admits they broke an expensive thing and were terrified to say so. You want to reward the telling.","setup":"Reward the telling:","yourLine":[{"text":"\"Thank you for telling me — that was brave. Things can be fixed; what matters is you can always come to me.\"","best":true},{"text":"\"Do you know how much that cost? You should have just hidden it.\""}],"relearn":"Thanking a child for a hard admission — over the broken thing — teaches that telling you is always the safe choice.","persona":"any","source":"thank the telling"},
  {"id":"sa-922","cat":"be-tellable","type":"role-play","hook":"Your child says an uncle's tickling 'games' make them uncomfortable. You want to honour that, not brush it off.","setup":"Honour the discomfort:","yourLine":[{"text":"\"I'm so glad you told me. You never have to play any game that feels wrong — I'll make sure it stops.\"","best":true},{"text":"\"Don't be silly, he's family. Don't make a fuss over a little tickling.\""}],"relearn":"Believing a child's discomfort with a relative — and acting on it — teaches that their 'no' is always heard at home.","persona":"Kamla","source":"honour discomfort"},
  {"id":"sa-923","cat":"be-tellable","type":"role-play","hook":"Your child asks a frank question about their body. You want to answer warmly so questions stay welcome.","setup":"Keep questions welcome:","yourLine":[{"text":"\"That's a good question — I'm glad you asked me. You can always ask me anything about your body.\"","best":true},{"text":"\"Chhi, who taught you to talk like that? We don't discuss such dirty things.\""}],"relearn":"Answering body questions calmly — 'glad you asked, you can ask me anything' — keeps a child coming to you, not strangers.","persona":"Priya","source":"glad you asked"},
  {"id":"sa-924","cat":"be-tellable","type":"role-play","hook":"Your child confesses they lied earlier today about where they were. You want honesty to feel safer than hiding.","setup":"Make honesty safe:","yourLine":[{"text":"\"It took courage to come clean. I'd much rather you tell me the truth than ever feel you have to hide from me.\"","best":true},{"text":"\"Liar. From now on I won't believe a single word you say.\""}],"relearn":"Valuing the truth-telling over the lie keeps a child choosing honesty with you, even when it's hard.","persona":"Vikram","source":"truth over hiding"},
  {"id":"sa-925","cat":"be-tellable","type":"role-play","hook":"Your autistic son shows you he's upset but struggles to find the words. You want him to know telling is safe, his way.","setup":"Meet him his way:","yourLine":[{"text":"\"Take your time, there's no rush. You can show me, draw it, or write it — whatever helps you tell me.\"","best":true},{"text":"\"Use your words properly or I can't help you. Stop being difficult.\""}],"relearn":"Letting a child tell their own way — words, drawing, showing — makes you tellable for a child who finds speech hard.","persona":"Meena","source":"tell your own way"},
  {"id":"sa-926","cat":"be-tellable","type":"role-play","hook":"Your child hesitantly says a cousin asked them to keep a 'secret game' between them. You want to keep the door wide open.","setup":"Open the door wider:","yourLine":[{"text":"\"Thank you for telling me — secrets that make you uneasy are exactly the ones to bring me. You did right.\"","best":true},{"text":"\"If you promised it was a secret, you shouldn't be telling me. Keep your word.\""}],"relearn":"Praising a child for breaking an uneasy 'secret' teaches that no one — not even a cousin — outranks telling you.","persona":"any","source":"uneasy secrets to me"},
  {"id":"sa-927","cat":"be-tellable","type":"role-play","hook":"You realise you snapped earlier when your child tried to tell you something. You want to repair it before bed.","setup":"Repair it:","yourLine":[{"text":"\"I'm sorry I got short with you earlier. You did nothing wrong by telling me — please always come to me.\"","best":true},{"text":"\"What's done is done. Don't bring it up again, it irritates me.\""}],"relearn":"A calm repair after snapping — 'sorry, you did nothing wrong by telling me' — restores a child's trust to tell again.","persona":"Divya","source":"repair before bed"},
  {"id":"sa-928","cat":"be-tellable","type":"role-play","hook":"Your child says they feel awkward when a tuition teacher hugs them too long. You want to fully back them up.","setup":"Back them up:","yourLine":[{"text":"\"You're right to tell me, and you're right to feel that. Your body, your rules — I'll sort this out for you.\"","best":true},{"text":"\"He's your teacher, just be respectful. Don't go imagining bad things about elders.\""}],"relearn":"Backing a child's 'this felt wrong' about any adult — and acting — proves telling you is always worth it.","persona":"Kamla","source":"body your rules"},
  {"id":"sa-929","cat":"be-tellable","type":"role-play","hook":"You're about to leave your kids with a relative for the holidays. You want to refresh the open-door promise first.","setup":"Refresh the promise:","yourLine":[{"text":"\"While I'm away, if anything ever feels wrong, call me straight away — no one can stop you telling me, ever.\"","best":true},{"text":"\"Behave for them and don't trouble me with phone calls while I'm gone.\""}],"relearn":"Reissuing the open-door promise before time apart — 'no one can stop you telling me' — keeps you reachable.","persona":"any","source":"reachable while away"},
  {"id":"sa-930","cat":"be-tellable","type":"sort","hook":"Sort: builds a tellable, open door, or quietly closes it?","items":[{"id":"a","text":"'You can tell me anything, no trouble'"},{"id":"b","text":"Calmly thanking them for hard news"},{"id":"c","text":"Letting them finish without interrupting"},{"id":"d","text":"Blowing up when they admit a mistake"},{"id":"e","text":"Mocking their worry as 'silly'"},{"id":"f","text":"Saying 'good kids don't have such problems'"}],"bins":[{"id":"open","label":"Builds the door","valence":"pos"},{"id":"closes","label":"Closes the door","valence":"neg"}],"key":{"a":"open","b":"open","c":"open","d":"closes","e":"closes","f":"closes"},"relearn":"Welcome, calm thanks and patient listening build the door; blow-ups, mockery and shaming quietly close it.","persona":"any","source":"build or close door"},
  {"id":"sa-931","cat":"be-tellable","type":"sort","hook":"Sort: a reason a child stays silent, or a reason they feel safe to tell?","items":[{"id":"a","text":"Afraid of an abuser's threats"},{"id":"b","text":"Ashamed and confused about it"},{"id":"c","text":"Scared the parent will be angry"},{"id":"d","text":"Knows they won't be in trouble"},{"id":"e","text":"Trusts the parent stays calm"},{"id":"f","text":"Was told 'you can always come to me'"}],"bins":[{"id":"silent","label":"Why they stay silent","valence":"uhoh"},{"id":"safe","label":"Why they feel safe to tell","valence":"pos"}],"key":{"a":"silent","b":"silent","c":"silent","d":"safe","e":"safe","f":"safe"},"relearn":"Threats, shame and fear of anger keep a child silent; calm, no-blame and a standing invitation make telling safe.","persona":"any","source":"silent or safe"},
  {"id":"sa-932","cat":"be-tellable","type":"sort","hook":"Sort: words that open a child up, or words that shut them down?","items":[{"id":"a","text":"'I'm glad you told me'"},{"id":"b","text":"'Take your time, I'm listening'"},{"id":"c","text":"'Nothing changes my love for you'"},{"id":"d","text":"'Why would you even say that?'"},{"id":"e","text":"'Don't make up stories'"},{"id":"f","text":"'Stop bothering me with this'"}],"bins":[{"id":"open","label":"Opens them up","valence":"pos"},{"id":"shut","label":"Shuts them down","valence":"neg"}],"key":{"a":"open","b":"open","c":"open","d":"shut","e":"shut","f":"shut"},"relearn":"'Glad you told me', 'take your time' and 'nothing changes my love' open a child; doubt and dismissal shut them.","persona":"Kamla","source":"open or shut words"},
  {"id":"sa-933","cat":"be-tellable","type":"sort","hook":"Sort: a true belief about tellability, or a myth that gets in the way?","items":[{"id":"a","text":"Tellability is built on purpose"},{"id":"b","text":"Silence is usually fear, not betrayal"},{"id":"c","text":"Even a quiet child tells when it's safe"},{"id":"d","text":"'A loving child would always blurt it out'"},{"id":"e","text":"'It can't happen in our family'"},{"id":"f","text":"'Talking about it steals their innocence'"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"true","d":"myth","e":"myth","f":"myth"},"relearn":"Tellability is built, silence is fear, and quiet kids tell when safe; the blurting, immunity and innocence ideas are myths.","persona":"any","source":"true or myth tellable"},
  {"id":"sa-934","cat":"be-tellable","type":"sort","hook":"Sort: a habit that makes you reachable, or one that makes you hard to reach?","items":[{"id":"a","text":"Sitting at their level to listen"},{"id":"b","text":"Putting the phone down for them"},{"id":"c","text":"Saying 'you can wake me anytime'"},{"id":"d","text":"Always being too busy to talk"},{"id":"e","text":"Half-listening while distracted"},{"id":"f","text":"Brushing off 'small' worries"}],"bins":[{"id":"reach","label":"Reachable","valence":"pos"},{"id":"hard","label":"Hard to reach","valence":"neg"}],"key":{"a":"reach","b":"reach","c":"reach","d":"hard","e":"hard","f":"hard"},"relearn":"Listening at their level, full attention and 'wake me anytime' make you reachable; being busy or distracted doesn't.","persona":"Vikram","source":"reachable or not"},
  {"id":"sa-935","cat":"be-tellable","type":"sort","hook":"Sort: a moment that builds trust to tell, or a moment that spends it?","items":[{"id":"a","text":"Keeping a promise you made them"},{"id":"b","text":"Believing them when it's awkward"},{"id":"c","text":"Following through to actually help"},{"id":"d","text":"Laughing off what worried them"},{"id":"e","text":"Telling their secret to relatives"},{"id":"f","text":"Punishing them for being honest"}],"bins":[{"id":"build","label":"Builds trust","valence":"pos"},{"id":"spend","label":"Spends trust","valence":"neg"}],"key":{"a":"build","b":"build","c":"build","d":"spend","e":"spend","f":"spend"},"relearn":"Kept promises, belief and follow-through build a child's trust to tell; broken trust, gossip and punishment spend it.","persona":"any","source":"build or spend trust"},
  {"id":"sa-936","cat":"be-tellable","type":"sort","hook":"Sort: a response that says 'telling me was right', or one that says 'you shouldn't have told'?","items":[{"id":"a","text":"'You did the right thing telling me'"},{"id":"b","text":"A calm, steady, warm tone"},{"id":"c","text":"Staying close and reassuring"},{"id":"d","text":"Scolding them for 'tattling'"},{"id":"e","text":"Visible disgust at what they said"},{"id":"f","text":"'Now look what trouble you've caused'"}],"bins":[{"id":"right","label":"Telling was right","valence":"pos"},{"id":"wrong","label":"You shouldn't have told","valence":"neg"}],"key":{"a":"right","b":"right","c":"right","d":"wrong","e":"wrong","f":"wrong"},"relearn":"'You did right', a warm tone and reassurance reward telling; scolding, disgust and blame teach a child to never tell again.","persona":"any","source":"right or wrong to tell"},
  {"id":"sa-937","cat":"be-tellable","type":"sort","hook":"Sort: an everyday way to keep the door open, or a way that lets it drift shut?","items":[{"id":"a","text":"A daily 'anything on your mind?' chat"},{"id":"b","text":"Naming feelings together openly"},{"id":"c","text":"Repairing quickly after you snap"},{"id":"d","text":"Only talking when they're in trouble"},{"id":"e","text":"Treating questions as nuisances"},{"id":"f","text":"Making them feel they over-share"}],"bins":[{"id":"open","label":"Keeps it open","valence":"pos"},{"id":"drift","label":"Lets it drift shut","valence":"neg"}],"key":{"a":"open","b":"open","c":"open","d":"drift","e":"drift","f":"drift"},"relearn":"Daily check-ins, naming feelings and quick repairs keep the door open; trouble-only talk and nuisance reactions let it drift shut.","persona":"Divya","source":"open or drift"},
  {"id":"sa-938","cat":"be-tellable","type":"spot","hook":"Spot the two lines that quietly teach a child NOT to tell you.","scene":[{"id":"a","text":"'You can tell me anything, no trouble ever'","trick":false},{"id":"b","text":"'Don't bring such shameful things to me'","trick":true},{"id":"c","text":"'Take your time, I'm right here'","trick":false},{"id":"d","text":"'If you tattle, you'll be punished'","trick":true},{"id":"e","text":"'I'm always glad when you come to me'","trick":false}],"why":"'Don't bring shameful things' and 'if you tattle, you'll be punished' teach a child that telling you is dangerous — the lines to catch.","relearn":"Shaming and threatening a child for telling close the door; warmth and 'no trouble' keep it open.","persona":"any","source":"lines that silence"},
  {"id":"sa-939","cat":"be-tellable","type":"spot","hook":"Spot the two parent reactions that make a child hide the next thing.","scene":[{"id":"a","text":"Thanking them calmly for telling","trick":false},{"id":"b","text":"Exploding in anger at the news","trick":true},{"id":"c","text":"Listening without interrupting","trick":false},{"id":"d","text":"Mocking the worry as 'drama'","trick":true},{"id":"e","text":"Staying warm and reassuring","trick":false}],"why":"Exploding in anger and mocking the worry teach a child that telling brings pain — those are the reactions to catch and avoid.","relearn":"Anger and mockery in response to a telling make a child hide the next thing; calm thanks and warmth invite more.","persona":"Vikram","source":"reactions that hide"},
  {"id":"sa-940","cat":"be-tellable","type":"spot","hook":"Spot the two beliefs that leave a parent un-tellable.","scene":[{"id":"a","text":"'I build my child's trust on purpose'","trick":false},{"id":"b","text":"'My child would obviously just blurt it out'","trick":true},{"id":"c","text":"'Silence is fear, so I stay gentle'","trick":false},{"id":"d","text":"'It can never happen in our family'","trick":true},{"id":"e","text":"'No topic is off-limits with me'","trick":false}],"why":"'They'd obviously blurt it out' and 'it can't happen to us' are the false beliefs that stop a parent building tellability — the ones to catch.","relearn":"Assuming a child would just blurt it out, or that harm can't reach your family, are the myths that leave you un-tellable.","persona":"any","source":"beliefs leave untellable"},
  {"id":"sa-941","cat":"be-tellable","type":"spot","hook":"Spot the two phrases that make telling feel shameful for a child.","scene":[{"id":"a","text":"'I'm so glad you trusted me with this'","trick":false},{"id":"b","text":"'What will people say if this gets out?'","trick":true},{"id":"c","text":"'Nothing you say changes my love'","trick":false},{"id":"d","text":"'Good children never have such problems'","trick":true},{"id":"e","text":"'You did the brave, right thing'","trick":false}],"why":"'What will people say' and 'good children never have such problems' load a child with shame and blame — the phrases to catch.","relearn":"Reputation-worry and 'good children don't have problems' shame a child silent; pride in their telling does the opposite.","persona":"Kamla","source":"shameful phrases"},
  {"id":"sa-942","cat":"be-tellable","type":"spot","hook":"Spot the two things that close a child's door, even when you mean well.","scene":[{"id":"a","text":"Putting your phone away to listen fully","trick":false},{"id":"b","text":"Interrogating them with rapid questions","trick":true},{"id":"c","text":"Letting them tell it at their own pace","trick":false},{"id":"d","text":"Promising you'll 'never tell a soul'","trick":true},{"id":"e","text":"Staying calm when it's hard to hear","trick":false}],"why":"Rapid interrogation overwhelms a child, and total secrecy can't be promised — both undermine safe telling, so catch them.","relearn":"Even well-meant interrogation or a 'never tell a soul' promise harm telling; calm, paced, honest listening helps.","persona":"any","source":"well-meant but closing"},
  {"id":"sa-943","cat":"be-tellable","type":"spot","hook":"Spot the two messages that teach a child their 'no' won't be heard at home.","scene":[{"id":"a","text":"'Your body, your rules — always'","trick":false},{"id":"b","text":"'Hug auntie or you'll be rude'","trick":true},{"id":"c","text":"'You never have to be touched if you don't want'","trick":false},{"id":"d","text":"'Stop fussing, sit on his lap'","trick":true},{"id":"e","text":"'If a touch feels wrong, tell me'","trick":false}],"why":"Forcing a hug 'or you'll be rude' and 'sit on his lap' override a child's no — teaching their boundary doesn't count.","relearn":"Forcing affection 'to be polite' teaches a child their no doesn't count; honouring their boundary keeps them tellable.","persona":"Priya","source":"no won't be heard"},
  {"id":"sa-944","cat":"be-tellable","type":"spot","hook":"Spot the two ways a parent accidentally teaches 'don't come to me'.","scene":[{"id":"a","text":"Welcoming the hard conversation","trick":false},{"id":"b","text":"Saying 'figure it out yourself'","trick":true},{"id":"c","text":"Sitting with their feelings","trick":false},{"id":"d","text":"'I'm too tired for your nonsense'","trick":true},{"id":"e","text":"Thanking them for bringing it to you","trick":false}],"why":"'Figure it out yourself' and 'too tired for your nonsense' tell a child their problems aren't welcome — the moves to catch.","relearn":"Brushing a child off with 'figure it out' or 'too tired' teaches them not to come to you; welcoming the talk reverses it.","persona":"Divya","source":"don't come to me"},
  {"id":"sa-945","cat":"be-tellable","type":"branch","hook":"Your child whispers something at a relative's house 'felt weird' but won't say more.","options":[{"text":"Stay calm, thank them, say they can share when ready","consequence":"They feel safe and, in time, tell you the rest.","outcome":"safe","best":true},{"text":"Demand every detail now, voice rising","consequence":"Pressed, they clam up: 'nothing, forget it'."}],"debrief":"Meet a half-telling with calm thanks and patience, not interrogation — that's how the rest comes out safely.","relearn":"When a child half-tells, stay calm, thank them and leave the door open; pressure makes them shut down.","persona":"Kamla","source":"half disclosure"},
  {"id":"sa-946","cat":"be-tellable","type":"branch","hook":"You're exhausted and your child says 'can I tell you something?' at a bad moment.","options":[{"text":"Stop, turn to them, say 'yes, I'm listening'","consequence":"They learn you're reachable, even when busy.","outcome":"reachable","best":true},{"text":"Say 'not now' and keep scrolling","consequence":"They learn telling depends on your mood, and hesitate."}],"debrief":"Even tired, turning toward 'can I tell you something?' protects the channel; 'not now' teaches them telling can wait.","relearn":"Turn toward a child's 'can I tell you something?' even when busy; 'not now' makes telling depend on your mood.","persona":"Vikram","source":"bad moment telling"},
  {"id":"sa-947","cat":"be-tellable","type":"branch","hook":"Your child admits they hid a broken phone for a week, scared of your reaction.","options":[{"text":"Thank them for the truth, focus on courage, not the phone","consequence":"They learn honesty with you beats hiding.","outcome":"honesty","best":true},{"text":"Erupt about the cost, ground them for the lie","consequence":"They decide hiding is the safer bet next time."}],"debrief":"Reward the courage to tell over the broken thing; punishing the honesty trains a child to hide bigger things later.","relearn":"When a child confesses something they hid in fear, reward the honesty — punishing it trains them to hide more.","persona":"any","source":"hid the phone"},
  {"id":"sa-948","cat":"be-tellable","type":"branch","hook":"Before a long trip away, you want your kids to know they can always reach you.","options":[{"text":"Tell them: 'If anything feels wrong, call me — no one can stop you'","consequence":"They carry a clear, standing permission to reach you.","outcome":"permission","best":true},{"text":"Just say 'behave and don't trouble anyone'","consequence":"They hear 'don't fuss', and stay quiet if something's wrong."}],"debrief":"Say the open-door promise out loud before time apart; an unspoken assumption isn't clear permission.","relearn":"Before time apart, say it plainly: they can always call, no one can stop them telling.","persona":"Divya","source":"reach trip"},
  {"id":"sa-949","cat":"be-tellable","type":"branch","hook":"Your child says a favourite coach gives 'secret treats' and to keep it quiet.","options":[{"text":"Thank them, praise breaking the secret, quietly look into it","consequence":"They learn uneasy secrets belong with you.","outcome":"alert","best":true},{"text":"Scold them for nearly breaking a promise","consequence":"They learn to keep adults' secrets from you."}],"debrief":"Praise a child for reporting a 'keep it secret' request and check it; never teach them to honour adult secrecy.","relearn":"When a child reports a secret an adult told them to keep, praise the telling and check it — don't side with secrecy.","persona":"any","source":"secret treats"},
  {"id":"sa-950","cat":"be-tellable","type":"branch","hook":"You overreacted when your child tried to tell you about a problem at school.","options":[{"text":"Apologise: 'you did nothing wrong telling me — always come to me'","consequence":"The repair restores their trust to tell you.","outcome":"repaired","best":true},{"text":"Pretend it didn't happen, hope they forget","consequence":"The unrepaired moment makes them hesitate next time."}],"debrief":"A sincere repair after overreacting reopens the door; left unaddressed, one harsh reaction can quietly close it.","relearn":"After overreacting to a telling, repair it: apologise and reaffirm the open door — silence lets it stay shut.","persona":"Vikram","source":"repair overreaction"},
  {"id":"sa-951","cat":"be-tellable","type":"branch","hook":"Your child mentions casually that an older neighbour shows them 'funny videos' alone.","options":[{"text":"Stay calm, thank them, keep it easy, quietly take steps","consequence":"They stay open while you act to keep them safe.","outcome":"open","best":true},{"text":"Gasp, panic and fire questions","consequence":"Scared by your reaction, they won't mention it again."}],"debrief":"Meet a casual mention of a worrying adult with calm thanks and quiet action — panic or dismissal closes the door.","relearn":"When a child casually mentions a worrying adult, stay calm, thank them and act quietly; panic silences them.","persona":"Kamla","source":"funny videos neighbour"},
  {"id":"sa-952","cat":"be-tellable","type":"branch","hook":"Your son finds it hard to put feelings into words and is clearly upset.","options":[{"text":"Slow down, offer ways to tell — talking, drawing, or showing","consequence":"He shares, and learns telling you is always possible.","outcome":"possible","best":true},{"text":"Insist he 'use his words' or get no help","consequence":"Stuck and pressured, he gives up and keeps it in."}],"debrief":"For a child who struggles with words, offering other ways to tell keeps you tellable; 'use your words' shuts him out.","relearn":"Offer a child who struggles with words other ways to tell — drawing, showing — so telling stays possible.","persona":"Meena","source":"hard to find words"},
  {"id":"sa-953","cat":"be-tellable","type":"match","hook":"Match each thing a parent does to the message the child receives.","pairs":[{"left":"Listening without interrupting","right":"What I have to say matters"},{"left":"Staying calm at bad news","right":"I won't be in trouble for telling"},{"left":"Keeping a promise you made","right":"I can trust what you say"},{"left":"Following through to help","right":"Telling you actually changes things"},{"left":"'No topic is off-limits'","right":"Nothing is too shameful to bring"}],"relearn":"Listening, calm, kept promises, follow-through and 'nothing off-limits' all tell a child that confiding in you is safe.","persona":"any","source":"do to message"},
  {"id":"sa-954","cat":"be-tellable","type":"match","hook":"Match each reason a child stays silent to what truly helps them speak.","pairs":[{"left":"Afraid of getting in trouble","right":"'You'll never be in trouble for telling'"},{"left":"Ashamed of what happened","right":"'It's not your fault, and I'm proud you told me'"},{"left":"Scared you'll get angry","right":"A calm, steady response"},{"left":"Was threatened to keep quiet","right":"'No one can stop you telling me'"},{"left":"Thinks you're too busy","right":"Full attention, phone down"}],"relearn":"Fear, shame, threats and feeling unimportant keep a child silent; reassurance, calm, permission and attention free them to tell.","persona":"Kamla","source":"silence to remedy"},
  {"id":"sa-955","cat":"be-tellable","type":"match","hook":"Match each myth about telling to the truth that replaces it.","pairs":[{"left":"'They'd blurt it out at once'","right":"Children hold the hardest things back longest"},{"left":"'Silence means they distrust me'","right":"Silence is usually fear, not betrayal"},{"left":"'It can't happen in our family'","right":"Harm can reach any child, any home"},{"left":"'Talking steals their innocence'","right":"It makes a child safer, not less innocent"},{"left":"'A quiet child won't tell'","right":"Even a quiet child tells when safe"}],"relearn":"The blurt-it-out, distrust, immunity and innocence ideas are myths; the truths make you tellable.","persona":"any","source":"myth to truth tell"},
  {"id":"sa-956","cat":"be-tellable","type":"match","hook":"Match each calm parent line to what it does for the child.","pairs":[{"left":"'Take your time, I'm here'","right":"Removes the pressure to rush"},{"left":"'I'm so glad you told me'","right":"Rewards the courage to speak"},{"left":"'This is not your fault'","right":"Lifts the shame off them"},{"left":"'I'll help you, whatever it is'","right":"Promises they won't face it alone"},{"left":"'You can always come back to me'","right":"Keeps the door open for next time"}],"relearn":"Patient, glad, no-blame, supportive and open-door lines each do real work to make a child feel safe enough to keep telling.","persona":"Divya","source":"line to effect"},
  {"id":"sa-957","cat":"be-tellable","type":"match","hook":"Match each everyday habit to how it builds a tellable home.","pairs":[{"left":"A daily 'anything on your mind?' chat","right":"Makes telling a normal, easy habit"},{"left":"Naming feelings out loud together","right":"Gives a child words for what's wrong"},{"left":"Repairing quickly after you snap","right":"Shows mistakes don't break the bond"},{"left":"Honouring their 'no' to a hug","right":"Proves their boundaries are respected"},{"left":"Keeping their confidences private","right":"Builds trust you won't expose them"}],"relearn":"Check-ins, feeling-words, repair, honouring 'no' and confidences are the bricks of a tellable home.","persona":"Vikram","source":"habit to home"},
  {"id":"sa-958","cat":"be-tellable","type":"match","hook":"Match each parent's worry to the reassuring truth about being tellable.","pairs":[{"left":"'I'll scare them by raising it'","right":"Calm, age-fit talk reassures, not scares"},{"left":"'I'm not a perfect parent'","right":"You need only be a calm, no-blame door"},{"left":"'I already snapped once'","right":"A sincere repair reopens the door"},{"left":"'My child is too shy'","right":"Even a quiet child tells when it's safe"},{"left":"'They'll bring me endless trifles'","right":"Small tellings rehearse the big one"}],"relearn":"Every common worry about being tellable has a reassuring truth — none is a reason to leave the door closed.","persona":"Meena","source":"worry to reassurance"},
  {"id":"sa-959","cat":"be-tellable","type":"match","hook":"Match each early promise to why it protects a child.","pairs":[{"left":"'Tell me even if someone said not to'","right":"Dismantles the secrecy abusers rely on"},{"left":"'You'll never be in trouble for telling'","right":"Removes fear of punishment"},{"left":"'Wake me anytime, day or night'","right":"Makes you reachable at the worst moment"},{"left":"'No touch you dislike is okay'","right":"Frames their body boundary as the rule"},{"left":"'Nothing changes my love for you'","right":"Takes shame off the table early"}],"relearn":"Said early, these promises strip away secrecy, fear, distance and shame — what keeps a child silent.","persona":"Kamla","source":"promise to protection"},
  {"id":"sa-990","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"If what my child describes sounds far-fetched, it probably didn't really happen.\"","myth":{"un":"If what my child describes sounds far-fetched, it probably didn't really happen.","re":"Children very rarely invent abuse; a confusing or partial account is normal, so believe them and let the details come later.","why":"Belief comes first, sense-making comes later."},"relearn":"A child's account can sound confused or incomplete and still be true; believe them, and don't treat oddness as proof they made it up.","persona":"Kamla","source":"sounds far-fetched"},
  {"id":"sa-991","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"My child told me weeks after it happened, so they're probably exaggerating now.\"","myth":{"un":"My child told me weeks after it happened, so they're probably exaggerating now.","re":"Delay is one of the most normal things about disclosure; fear and confusion keep children silent, and a late telling is just as real.","why":"A delay is fear, not a lie."},"relearn":"Children often disclose long after harm; treat a delayed telling as real and brave, never as a sign they are exaggerating.","persona":"Kamla","source":"told weeks later"},
  {"id":"sa-992","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"If I stay calm while my child tells me something awful, they'll think I don't care.\"","myth":{"un":"If I stay calm while my child tells me something awful, they'll think I don't care.","re":"Your calm tells a child it is safe to keep talking; a steady, warm face reassures far more than visible shock or rage.","why":"Calm reads as safety, not as not caring."},"relearn":"Staying calm during a disclosure is an act of care, not coldness; it keeps a child talking instead of frightening them into silence.","persona":"Vikram","source":"calm means uncaring"},
  {"id":"sa-993","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"When my child discloses, I should march straight to confront the person they named.\"","myth":{"un":"When my child discloses, I should march straight to confront the person they named.","re":"Comfort your child and get safe help first; rushing to confront can frighten the child and put their safety at risk.","why":"Protect the child first, confront nothing alone."},"relearn":"After a disclosure, comfort the child and get safe help rather than confronting the named person yourself, which can endanger the child.","persona":"any","source":"confront first"},
  {"id":"sa-994","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"My child seemed calm telling me, so it can't have been serious.\"","myth":{"un":"My child seemed calm telling me, so it can't have been serious.","re":"Children disclose in all kinds of ways, sometimes flatly or matter-of-factly; a calm telling can carry the most serious news.","why":"How they tell you isn't how big it is."},"relearn":"A child may disclose serious harm calmly or flatly; never measure how serious it is by how upset they seem while telling you.","persona":"Divya","source":"seemed calm"},
  {"id":"sa-995","cat":"if-they-tell-you","type":"strike-rewrite","hook":"\"If my child says they're partly to blame, I should agree so they learn to be careful.\"","myth":{"un":"If my child says they're partly to blame, I should agree so they learn to be careful.","re":"A child is never to blame for abuse; when they blame themselves, your job is to say clearly that the fault is entirely the adult's.","why":"Self-blame is the wound, not the lesson."},"relearn":"When a child blames themselves, correct it gently and firmly: the fault is the adult's alone, and the child did nothing to cause it.","persona":"Kamla","source":"partly to blame"},
  {"id":"sa-996","cat":"if-they-tell-you","type":"role-play","hook":"Your child whispers that an uncle has been touching them and begs you not to be angry. Your first words set the tone.","setup":"Open the door wide:","yourLine":[{"text":"\"I'm not angry with you at all. I believe you, none of this is your fault, and I'm so glad you told me.\"","best":true},{"text":"\"Why would your own uncle do that? Are you sure you understood it right?\""}],"relearn":"'I'm not angry with you, I believe you, it's not your fault, I'm glad you told me' is the response that keeps a child safe and talking.","persona":"Kamla","source":"don't be angry"},
  {"id":"sa-997","cat":"if-they-tell-you","type":"role-play","hook":"Your child goes quiet halfway through telling you something hard, watching your face to see if it's safe to go on.","setup":"Keep the door open:","yourLine":[{"text":"\"It's okay, take all the time you need. I'm right here and nothing you say will change how much I love you.\"","best":true},{"text":"\"Come on, out with it, I don't have all day for this.\""}],"relearn":"Patience and steady warmth let a child finish a hard disclosure at their own pace; rushing or impatience shuts the door.","persona":"any","source":"goes quiet"},
  {"id":"sa-998","cat":"if-they-tell-you","type":"role-play","hook":"After disclosing, your child asks, 'Am I going to get in trouble?' You answer in one breath.","setup":"Leave no doubt:","yourLine":[{"text":"\"You are not in any trouble. You did the right thing telling me, and I'm going to keep you safe.\"","best":true},{"text":"\"Well, that depends on what exactly you did to let this happen.\""}],"relearn":"A disclosing child needs to hear plainly that they are not in trouble and did the right thing by telling you.","persona":"Vikram","source":"am I in trouble"},
  {"id":"sa-999","cat":"if-they-tell-you","type":"role-play","hook":"Your child says the person told them it was 'our special secret' and that telling would break the family. You reassure them.","setup":"Undo the secret:","yourLine":[{"text":"\"You were right to tell me. A grown-up who needs a secret like that is the one in the wrong, never you.\"","best":true},{"text":"\"Maybe we should keep this between us so nobody gets upset.\""}],"relearn":"Praise a child for breaking a coerced secret; an adult who demands such secrecy is at fault, and the child is never wrong for telling.","persona":"Kamla","source":"special secret"},
  {"id":"sa-1000","cat":"if-they-tell-you","type":"role-play","hook":"Your teenager admits something happened but says, 'Forget it, I shouldn't have said anything.' You hold the door open.","setup":"Stay steady and warm:","yourLine":[{"text":"\"I'm really glad you said it. We can go as slow as you want, and I'm not going anywhere.\"","best":true},{"text":"\"Fine, if you don't want to talk about it then just drop it.\""}],"relearn":"When a child tries to take back a disclosure, gently reassure them you are glad they told you and you will go at their pace.","persona":"any","source":"forget it"},
  {"id":"sa-1001","cat":"if-they-tell-you","type":"branch","hook":"Your child tells you a coaching tutor has been hurting them. Your mind races.","options":[{"text":"Believe and reassure them, then quietly arrange safe help","consequence":"They feel believed and you keep them safe.","outcome":"protect","best":true},{"text":"Demand the whole story in detail to 'be sure' first","consequence":"Interrogating can make a frightened child shut down."},{"text":"Tell them to avoid the tutor but say nothing to anyone","consequence":"Silence leaves the child unprotected."}],"debrief":"After a disclosure: believe, reassure, then get safe help.","relearn":"Believe, reassure, then get help, not interrogation or silence.","persona":"any","source":"tutor disclosure"},
  {"id":"sa-1002","cat":"if-they-tell-you","type":"branch","hook":"Your child discloses, then panics: 'Please don't tell Papa, he'll be furious.'","options":[{"text":"Reassure them, and gently say you must get safe help","consequence":"They feel held and you still protect them.","outcome":"safe-help","best":true},{"text":"Promise you'll never tell a soul, to calm them","consequence":"Total secrecy can leave them unprotected."},{"text":"Tell them to stop worrying and handle it without them","consequence":"Shutting them out leaves them unheard and afraid."}],"debrief":"Never promise total secrecy; reassure them and get safe help.","relearn":"Reassure a frightened child but never promise total secrecy.","persona":"Kamla","source":"don't tell papa"},
  {"id":"sa-1003","cat":"if-they-tell-you","type":"branch","hook":"Late at night your child wakes you to say a relative did something to them.","options":[{"text":"Hold them, say you believe them, it's not their fault","consequence":"They feel safe enough to rest and keep talking.","outcome":"hold","best":true},{"text":"Snap that it's late and you'll deal with it tomorrow","consequence":"Dismissal teaches them not to come to you again."},{"text":"Wake the house and demand answers at once","consequence":"A panicked scene can frighten them into silence."}],"debrief":"Meet a night-time disclosure with calm belief; panic closes the door.","relearn":"Meet any disclosure, even an inconvenient one, with calm belief.","persona":"any","source":"woken at night"},
  {"id":"sa-1004","cat":"if-they-tell-you","type":"reflect","hook":"Lensy: the very first thing your face does when a child tells you something hard is a message they read instantly.","prompt":"Sit with that.","options":["My face speaks first","I'll soften it","Calm and warm"],"affirm":"A child reads your first expression in an instant; a calm, warm face tells them it is safe to keep telling you the truth.","relearn":"Your first expression is a message; keeping it calm and warm tells a child it is safe to keep talking.","persona":"any","source":"your face first"},
  {"id":"sa-1005","cat":"if-they-tell-you","type":"reflect","hook":"Lensy: 'I believe you, it's not your fault, I'm glad you told me, I'll keep you safe.' Picture saying it before you ever need to.","prompt":"What do you notice?","options":["I can say this","Rehearse it","Ready, not scared"],"affirm":"Knowing the four lines before you need them, believe you, not your fault, glad you told me, I'll keep you safe, lets calm lead when it counts.","relearn":"Rehearsing the believing words before you ever need them helps calm guide your response in the real moment.","persona":"any","source":"rehearse the words"},
  {"id":"sa-1006","cat":"if-they-tell-you","type":"match","hook":"Match each thing a child says after disclosing to the reassurance they need.","pairs":[{"left":"'Are you angry with me?'","right":"'Never with you, I'm proud you told me'"},{"left":"'Is this my fault?'","right":"'Not even a little, the fault is the grown-up's'"},{"left":"'Will I get in trouble?'","right":"'No trouble at all, you did the right thing'"},{"left":"'Do you still love me?'","right":"'Completely, nothing changes that'"},{"left":"'Don't tell anyone, please'","right":"'I'll keep you safe, with safe help'"}],"relearn":"After disclosing, a child needs to hear: not angry, not your fault, no trouble, still loved, kept safe.","persona":"Kamla","source":"questions to answers"},
  {"id":"sa-1007","cat":"if-they-tell-you","type":"match","hook":"Match each disclosure-response move to why it protects the child.","pairs":[{"left":"Believe them right away","right":"Belief is the first protection a child feels"},{"left":"Keep your voice steady","right":"Steadiness keeps a frightened child talking"},{"left":"Say plainly it's not their fault","right":"Lifts the self-blame that silences children"},{"left":"Let them talk at their own pace","right":"Their pace keeps them from shutting down"},{"left":"Get safe help afterwards","right":"Turns belief into real protection"}],"relearn":"Belief protects, calm keeps them talking, no-blame frees them, help shields them.","persona":"any","source":"move to reason"},
  {"id":"sa-1008","cat":"if-they-tell-you","type":"sort","hook":"Sort each first reaction to a disclosure: keeps your child safe and talking, or shuts them down?","items":[{"id":"a","text":"'I believe you, and none of this is your fault'"},{"id":"b","text":"'Are you sure? That doesn't sound like him'"},{"id":"c","text":"Staying calm and listening to the end"},{"id":"d","text":"Shouting in shock so they freeze"},{"id":"e","text":"'I'm so glad you told me'"},{"id":"f","text":"Demanding every detail at once"}],"bins":[{"id":"keeps-safe","label":"Keeps them safe","valence":"pos"},{"id":"shuts-down","label":"Shuts them down","valence":"neg"}],"key":{"a":"keeps-safe","b":"shuts-down","c":"keeps-safe","d":"shuts-down","e":"keeps-safe","f":"shuts-down"},"relearn":"Belief, calm, and 'I'm glad you told me' keep a child talking; doubt and shock shut them down.","persona":"any","source":"safe or shut down"},
  {"id":"sa-1009","cat":"if-they-tell-you","type":"sort","hook":"Sort each line a parent might say after a disclosure: a reassurance the child needs, or a harm to avoid?","items":[{"id":"a","text":"'You were so brave to tell me'"},{"id":"b","text":"'Why didn't you stop it yourself?'"},{"id":"c","text":"'I'll keep you safe, I promise'"},{"id":"d","text":"'We'll never speak of this again'"},{"id":"e","text":"'None of this changes how I love you'"},{"id":"f","text":"'What did you do to make this happen?'"}],"bins":[{"id":"reassure","label":"Reassurance to give","valence":"pos"},{"id":"harm","label":"Harm to avoid","valence":"neg"}],"key":{"a":"reassure","b":"harm","c":"reassure","d":"harm","e":"reassure","f":"harm"},"relearn":"Praising bravery, promising safety, and steady love reassure a child; blame, silencing, and 'what did you do' harm them.","persona":"Kamla","source":"reassure or harm"},
  {"id":"sa-1010","cat":"if-they-tell-you","type":"spot","hook":"Lensy: a parent is mid-disclosure with their child. Spot the two reactions that shut a child down.","scene":[{"id":"a","text":"'I believe you, take your time'","trick":false},{"id":"b","text":"'Are you making this up for attention?'","trick":true},{"id":"c","text":"Keeping a calm, steady voice","trick":false},{"id":"d","text":"Yelling in horror until they freeze","trick":true},{"id":"e","text":"'It's not your fault, I'm glad you told me'","trick":false}],"why":"Doubting the child and reacting with horror shut a disclosure down; belief, calm, and no-blame keep it safe.","relearn":"The reactions that shut a child down are doubt and horror; belief, calm, and 'not your fault' keep them talking.","persona":"any","source":"shut-down reactions"},
  {"id":"sa-1011","cat":"if-they-tell-you","type":"spot","hook":"Lensy: read this parent's response to a disclosure. Spot the two lines that put blame on the child.","scene":[{"id":"a","text":"'None of this is your fault'","trick":false},{"id":"b","text":"'You should have known better than to go there'","trick":true},{"id":"c","text":"'I'm glad you trusted me with this'","trick":false},{"id":"d","text":"'Why did you let it happen so many times?'","trick":true},{"id":"e","text":"'The grown-up is in the wrong, not you'","trick":false}],"why":"'You should have known' and 'why did you let it happen' blame the child; the fault is the adult's, never the child's.","relearn":"Lines like 'you should have known' wrongly blame the child; the fault is the adult's alone.","persona":"Kamla","source":"blame-the-child lines"},
  {"id":"sa-1080","type":"strike-rewrite","persona":"Vikram","source":"groomers aren't only strangers","hook":"\"Online danger only comes from creepy strangers, not people my child already knows.\"","myth":{"un":"Online danger only comes from creepy strangers, not people my child already knows.","re":"The known-adult risk works online too: a relative or coach who DMs your child privately, earning secrecy, can groom them.","why":"Most abuse is by someone the child knows, online included."},"relearn":"The known-adult grooming risk applies online too; a trusted person earning secrecy in private chats is a red flag.","cat":"safe-online-and-off"},
  {"id":"sa-1081","type":"strike-rewrite","persona":"any","source":"snooping isn't safety","hook":"\"Reading every message and tracking their phone is how I keep my child safe online.\"","myth":{"un":"Reading every message and tracking their phone is how I keep my child safe online.","re":"Safety is staying close and tellable, not surveillance-as-control; heavy spying pushes a child to hide the very thing you need to hear.","why":"A child who fears snooping stops telling you when something goes wrong."},"relearn":"Online safety is staying close and keeping the door open, not surveillance that makes a child hide trouble.","cat":"safe-online-and-off"},
  {"id":"sa-1082","type":"strike-rewrite","persona":"Vikram","source":"sextortion is not the child's fault","hook":"\"If my child gets blackmailed over a photo they sent, they brought it on themselves.\"","myth":{"un":"If my child gets blackmailed over a photo they sent, they brought it on themselves.","re":"A sextorted child is a victim of a skilled abuser, never at fault even if they sent something; they need belief and help, not blame.","why":"Blame makes a frightened child pay the blackmailer instead of telling you."},"relearn":"A child blackmailed over an image is a victim; respond with belief and report to cybercrime 1930, never blame.","cat":"safe-online-and-off"},
  {"id":"sa-1083","type":"strike-rewrite","persona":"any","source":"banning everything backfires","hook":"\"The safest thing is to ban phones and the internet completely until my child is grown.\"","myth":{"un":"The safest thing is to ban phones and the internet completely until my child is grown.","re":"Banning everything out of fear teaches nothing and isolates a child; staying involved and talking openly builds real online judgement.","why":"A child with no guidance is least ready when they finally get online."},"relearn":"Blanket bans out of fear don't protect; staying involved and talking openly builds a child's online judgement.","cat":"safe-online-and-off"},
  {"id":"sa-1084","type":"strike-rewrite","persona":"Vikram","source":"games have strangers too","hook":"\"It's only a children's game, so the people my child chats with in it must be other kids.\"","myth":{"un":"It's only a children's game, so the people my child chats with in it must be other kids.","re":"Game and app chats let adults pose as kids; an online 'friend' offering gifts, secrets and isolation is a grooming flag wherever it appears.","why":"Abusers go where children are, including kids' games."},"relearn":"Anyone can pose as a child in game chats; grooming flags, gifts, secrets, isolation, count online too.","cat":"safe-online-and-off"},
  {"id":"sa-1085","type":"strike-rewrite","persona":"any","source":"deleting evidence helps no one","hook":"\"If something nasty happens online, the kindest thing is to delete it all so we can forget it.\"","myth":{"un":"If something nasty happens online, the kindest thing is to delete it all so we can forget it.","re":"Deleting wipes the proof needed to act; calmly keep screenshots and chats as evidence, then report it.","why":"Without evidence, the people who can stop the abuser have little to work with."},"relearn":"Don't delete in a panic; calmly keep evidence (screenshots, chats) and report online abuse to cybercrime 1930.","cat":"safe-online-and-off"},
  {"id":"sa-1086","type":"strike-rewrite","persona":"Vikram","source":"silence can be a danger sign","hook":"\"My child suddenly hides the screen and went secretive, but that's just normal teenage privacy.\"","myth":{"un":"My child suddenly hides the screen and went secretive, but that's just normal teenage privacy.","re":"New fear, hiding the screen or sudden secrecy online can be a sign something is wrong; check in gently and stay the open door.","why":"Sudden online secrecy can mean a child is being pressured or threatened."},"relearn":"Sudden online secrecy or screen-hiding deserves a gentle check-in, not a shrug; stay the open, tellable door.","cat":"safe-online-and-off"},
  {"id":"sa-1087","type":"strike-rewrite","persona":"any","source":"online harm is real harm","hook":"\"Whatever happens on a screen isn't real, so online stuff can't really hurt my child.\"","myth":{"un":"Whatever happens on a screen isn't real, so online stuff can't really hurt my child.","re":"Online grooming, exploitation and sextortion cause real fear and harm; treat an online threat as seriously as one in person.","why":"The fear and coercion a child feels online are entirely real."},"relearn":"Online grooming, exploitation and sextortion are real harm; take an online threat as seriously as one in person.","cat":"safe-online-and-off"},
  {"id":"sa-1088","type":"sort","persona":"any","source":"grooming flag or ordinary","hook":"Sort: a grooming red flag online, or an ordinary one?","items":[{"id":"a","text":"An adult online asks your child to keep their chats a secret"},{"id":"b","text":"A classmate messages about tomorrow's homework"},{"id":"c","text":"An online 'friend' sends gifts and recharge codes"},{"id":"d","text":"A cousin shares a funny video in the family group"},{"id":"e","text":"A new contact tries to move chat to a private, hidden app"},{"id":"f","text":"A teammate in a game says 'good match, play tomorrow?'"}],"bins":[{"id":"x","label":"Grooming red flag","valence":"neg"},{"id":"y","label":"Ordinary, harmless","valence":"pos"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Secrecy, gifts and hidden chats are flags; homework and game chat are ordinary.","cat":"safe-online-and-off"},
  {"id":"sa-1089","type":"sort","persona":"Vikram","source":"protective or risky response","hook":"Your child shows you a scary online message. Sort each reaction: protective, or risky?","items":[{"id":"a","text":"Thank them calmly for showing you"},{"id":"b","text":"Shout and grab the phone in anger"},{"id":"c","text":"Save screenshots before anything is deleted"},{"id":"d","text":"Tell them it's their own fault for chatting"},{"id":"e","text":"Report it to cybercrime 1930"},{"id":"f","text":"Make them promise never to mention it again"}],"bins":[{"id":"x","label":"Protective","valence":"pos"},{"id":"y","label":"Risky","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Stay calm, keep evidence and report; anger, blame and forced silence push a child to hide the next danger.","cat":"safe-online-and-off"},
  {"id":"sa-1090","type":"sort","persona":"any","source":"stay close or surveil","hook":"Sort: staying close and tellable, or surveillance-as-control that backfires?","items":[{"id":"a","text":"Asking with interest who they game and chat with"},{"id":"b","text":"Secretly reading every private message"},{"id":"c","text":"Agreeing on which apps are okay together"},{"id":"d","text":"Threatening to track their location all day"},{"id":"e","text":"'Tell me about anyone online who makes you uneasy'"},{"id":"f","text":"Punishing them for any new app you didn't approve"}],"bins":[{"id":"x","label":"Staying close","valence":"pos"},{"id":"y","label":"Surveillance-control","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Interest, shared rules and an open invite keep a child tellable; spying and punishment make them hide.","cat":"safe-online-and-off"},
  {"id":"sa-1091","type":"sort","persona":"any","source":"share online or keep private","hook":"Sort: safe to share with an online contact your child just met, or keep private?","items":[{"id":"a","text":"Your home address and which school they attend"},{"id":"b","text":"A favourite cartoon character"},{"id":"c","text":"Live location and when the house is empty"},{"id":"d","text":"That they like cricket"},{"id":"e","text":"Private photos of themselves"},{"id":"f","text":"Their nickname in a public game"}],"bins":[{"id":"x","label":"Keep private","valence":"neg"},{"id":"y","label":"Okay to share","valence":"pos"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Address, school, live location and private photos stay private with a new online contact; harmless likes are fine.","cat":"safe-online-and-off"},
  {"id":"sa-1092","type":"sort","persona":"Divya","source":"believe or blame online","hook":"Your child confides about something that went wrong online. Sort: believing, or blaming?","items":[{"id":"a","text":"'I'm glad you told me, this isn't your fault'"},{"id":"b","text":"'You should have known better than to reply'"},{"id":"c","text":"'We'll sort this out together'"},{"id":"d","text":"'What did you do to make them do that?'"},{"id":"e","text":"'You're not in trouble for telling me'"},{"id":"f","text":"'This is why I never trusted you online'"}],"bins":[{"id":"x","label":"Believing","valence":"pos"},{"id":"y","label":"Blaming","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"'It's not your fault, you're not in trouble, we'll sort it together' keeps a child talking; blame shuts them down.","cat":"safe-online-and-off"},
  {"id":"sa-1093","type":"sort","persona":"any","source":"report route fit","hook":"Sort each situation: report mainly via cybercrime 1930, or reach for Childline 1098?","items":[{"id":"a","text":"A stranger online is pressuring your child for photos"},{"id":"b","text":"Your child needs to talk to a child-help counsellor"},{"id":"c","text":"Someone is threatening to leak your child's images"},{"id":"d","text":"You want child-protection guidance and support"},{"id":"e","text":"An account is sextorting your child for money"},{"id":"f","text":"A frightened child needs a caring helpline to call"}],"bins":[{"id":"x","label":"Cybercrime 1930","valence":"tell"},{"id":"y","label":"Childline 1098","valence":"tell"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Grooming, leaks and sextortion go to cybercrime 1930; child support to Childline 1098.","cat":"safe-online-and-off"},
  {"id":"sa-1094","type":"sort","persona":"Vikram","source":"builds safety or exposes online","hook":"Sort each parent move online: builds safety, or leaves a child exposed?","items":[{"id":"a","text":"Keeping screens in shared family spaces"},{"id":"b","text":"Letting a young child video-call unknown adults alone"},{"id":"c","text":"Talking about online tricks before they happen"},{"id":"d","text":"Assuming a kids' app needs no supervision"},{"id":"e","text":"Knowing how and where to report"},{"id":"f","text":"Ignoring who your child meets in games"}],"bins":[{"id":"x","label":"Builds safety","valence":"pos"},{"id":"y","label":"Leaves exposed","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Shared-space screens, early talk and knowing how to report build safety; unsupervised calls and ignoring contacts expose.","cat":"safe-online-and-off"},
  {"id":"sa-1095","type":"sort","persona":"any","source":"true or myth online","hook":"Sort each online-safety belief: a true one to keep, or a myth to drop?","items":[{"id":"a","text":"A sextorted child is a victim, never at fault"},{"id":"b","text":"If they sent a photo, it's their own problem"},{"id":"c","text":"Keep evidence, then report online abuse"},{"id":"d","text":"Online harm isn't real because it's just a screen"},{"id":"e","text":"An online 'friend' earning secrecy is a red flag"},{"id":"f","text":"Strangers are the only online danger"}],"bins":[{"id":"x","label":"True, keep it","valence":"pos"},{"id":"y","label":"Myth, drop it","valence":"neg"}],"key":{"a":"x","b":"y","c":"x","d":"y","e":"x","f":"y"},"relearn":"Victims aren't at fault, keep evidence and report, secrecy is a flag; the rest are myths.","cat":"safe-online-and-off"},
  {"id":"sa-1096","type":"branch","persona":"Vikram","source":"in-game friend wants private app","hook":"Your child says a new gaming friend wants to chat on a private app, kept secret.","options":[{"text":"Stay calm, talk it through, and explain why secret private chats aren't okay","consequence":"Your child learns the flag and keeps telling you.","outcome":"coached","best":true},{"text":"Snatch the device and ban all games as punishment","consequence":"They feel punished for telling you and hide the next contact.","outcome":"hidden"}],"debrief":"A new contact pushing secret private chat is a grooming flag; coach your child calmly.","cat":"safe-online-and-off","relearn":"Secret private chat with a new contact is a grooming flag; coach calmly."},
  {"id":"sa-1097","type":"branch","persona":"any","source":"threat to leak a photo","hook":"Your teen says someone online threatens to share a private photo unless they pay.","options":[{"text":"Reassure them it's not their fault, save the evidence, stop paying, and report to cybercrime 1930","consequence":"You treat them as a victim and act to stop it.","outcome":"reported","best":true},{"text":"Pay the blackmailer quietly to make it disappear","consequence":"Paying invites more demands and the threat grows.","outcome":"worse"}],"debrief":"Sextortion: reassure it's not their fault, keep evidence, never pay, report to cybercrime 1930.","cat":"safe-online-and-off","relearn":"Sextortion: reassure, keep evidence, never pay, report to cybercrime 1930."},
  {"id":"sa-1098","type":"branch","persona":"Divya","source":"younger child on video calls","hook":"You find your young child on a video call with an adult 'fan' from a kids' app.","options":[{"text":"End the call gently, stay calm, and talk about who it's safe to call","consequence":"Your child stays open while you close the risk.","outcome":"steered","best":true},{"text":"Scream at them and smash the tablet","consequence":"Terror teaches them to hide the next call from you.","outcome":"hidden"}],"debrief":"Adults reach kids inside 'kids' apps; end it calmly and talk, don't terrify them into hiding it.","cat":"safe-online-and-off","relearn":"Adults can reach kids in 'kids' apps; end the contact calmly and talk, don't terrify your child."},
  {"id":"sa-1099","type":"branch","persona":"Vikram","source":"child admits sending something","hook":"Your child admits they sent a photo to an online friend and now feel sick about it.","options":[{"text":"Tell them it's not the end and not their fault, keep evidence, and get help together","consequence":"Fear becomes a problem you handle as a team.","outcome":"handled","best":true},{"text":"Tell them they've ruined everything and ground them","consequence":"Shame buries the next, bigger danger from you.","outcome":"buried"}],"debrief":"When a child regrets what they sent, lead with 'not your fault', keep evidence, get help, not shame.","cat":"safe-online-and-off","relearn":"Meet an online regret with 'not your fault', keep evidence and get help, not shame."},
  {"id":"sa-1100","type":"branch","persona":"any","source":"relative DMing the child privately","hook":"You see a relative messaging your child privately at night, asking them to keep it secret.","options":[{"text":"Gently check in with your child and set that private secret chats with adults aren't okay","consequence":"You act on the known-adult flag without panic.","outcome":"checked","best":true},{"text":"Decide a relative could never be a risk and ignore it","consequence":"Respectability blinds you to a grooming pattern.","outcome":"missed"}],"debrief":"The known-adult risk works online; a relative earning private secrecy is a flag.","cat":"safe-online-and-off","relearn":"The known-adult risk works online; check in calmly, don't dismiss it."},
  {"id":"sa-1101","type":"branch","persona":"any","source":"coach moved chat off the group","hook":"Your child's tuition teacher now messages only your child, away from the class group.","options":[{"text":"Move the chat back to a parent-visible group and ask why one-to-one was needed","consequence":"You keep contact open and break the isolation.","outcome":"open","best":true},{"text":"Feel flattered the teacher takes special interest and leave it","consequence":"Favouritism and isolation, key grooming flags, go unchecked.","outcome":"unchecked"}],"debrief":"Private one-to-one contact and special favour are grooming flags; keep adult-child chat visible.","cat":"safe-online-and-off","relearn":"Private one-to-one contact and special favour are grooming flags online."},
  {"id":"sa-1102","type":"branch","persona":"Vikram","source":"don't punish the messenger","hook":"Your child shows you a creepy DM the moment it arrives, nervous about how you'll react.","options":[{"text":"Thank them warmly for telling you fast, stay calm, and decide what to do together","consequence":"Telling you works, so they'll do it again next time.","outcome":"reinforced","best":true},{"text":"React with visible disgust and take the phone for a month","consequence":"They learn telling you costs them, so they stop.","outcome":"deterred"}],"debrief":"Reward fast telling with calm thanks; punishing the messenger teaches a child to hide.","cat":"safe-online-and-off","relearn":"Reward fast telling with calm thanks; punishing the messenger makes them hide."},
  {"id":"sa-1103","type":"branch","persona":"any","source":"keep evidence before reporting","hook":"Someone online is harassing your child; you want to report it, the messages still there.","options":[{"text":"Screenshot the messages and profile first, then report to cybercrime 1930","consequence":"The report has proof and can actually be acted on.","outcome":"evidenced","best":true},{"text":"Block and delete everything immediately to feel safe","consequence":"You wipe the proof the report needed.","outcome":"noproof"}],"debrief":"Before reporting online abuse, keep the evidence, then report to cybercrime 1930.","cat":"safe-online-and-off","relearn":"Keep the evidence, screenshots and profile, then report online abuse to cybercrime 1930."},
  {"id":"sa-1104","type":"branch","persona":"any","source":"door open after a scare","hook":"After an online scare blows over, your child seems to want to talk but keeps stopping.","options":[{"text":"Say calmly that they can tell you anything, anytime, with no trouble, and wait","consequence":"The open door invites the rest when they're ready.","outcome":"opened","best":true},{"text":"Interrogate them for every detail right now","consequence":"Pressure makes them clam up and trust you less.","outcome":"clammed"}],"debrief":"Keep the door open after a scare; offer no-trouble openness, don't interrogate.","cat":"safe-online-and-off","relearn":"Keep the door open after a scare; offer no-trouble openness and don't interrogate."},
  {"id":"sa-1105","type":"branch","persona":"Vikram","source":"model the safe behaviour","hook":"Your kids watch how you handle a stranger's friend request that seems too eager and personal.","options":[{"text":"Decline it out loud and explain why an eager stranger online is a flag","consequence":"They learn the reflex by watching you model it.","outcome":"modelled","best":true},{"text":"Accept it to seem friendly while telling kids to be careful","consequence":"Your action contradicts your advice and confuses them.","outcome":"mixed"}],"debrief":"Kids learn online safety by watching you; decline the over-eager stranger out loud.","cat":"safe-online-and-off","relearn":"Kids learn by watching you; decline the over-eager online stranger out loud and say why."},
  {"id":"sa-1106","type":"branch","persona":"any","source":"online contact wants to meet","hook":"Your child says an online friend they've never met wants to meet alone this weekend.","options":[{"text":"Stay calm, say no to meeting alone, and talk through why with them","consequence":"You stop the risk while keeping them talking to you.","outcome":"prevented","best":true},{"text":"Let them go since the friend seems nice in chat","consequence":"An unknown adult could be behind a kind-seeming profile.","outcome":"exposed"}],"debrief":"Meeting an online-only contact alone is a real risk; calmly refuse and explain.","cat":"safe-online-and-off","relearn":"Meeting an online-only contact alone is a real risk; calmly refuse and explain why."},
  {"id":"sa-1107","type":"match","persona":"any","source":"grooming flag to plain meaning","hook":"Match each online grooming flag to what it's really doing.","pairs":[{"left":"'Keep our chats just between us'","right":"Building secrecy to isolate the child"},{"left":"Sending gifts and game recharge codes","right":"Buying trust and a sense of debt"},{"left":"'You're more mature than other kids'","right":"Flattery and favouritism to lower guard"},{"left":"Moving chat to a private hidden app","right":"Cutting off adults who might notice"},{"left":"Ignoring 'I don't want to' online","right":"Pushing past the child's boundaries"}],"relearn":"Secrecy, gifts, flattery, hidden apps and boundary-pushing are the online grooming flags.","cat":"safe-online-and-off"},
  {"id":"sa-1108","type":"match","persona":"Vikram","source":"online situation to right route","hook":"Match each online situation to where you'd report or get help.","pairs":[{"left":"Stranger pressuring your child for photos","right":"Cybercrime 1930"},{"left":"Child needs a caring helpline to talk to","right":"Childline 1098"},{"left":"A child in immediate danger right now","right":"Emergency 112"},{"left":"A local crime you want acted on","right":"The police"},{"left":"You're unsure and want child-safety advice","right":"Childline 1098 can guide you"}],"relearn":"Online exploitation goes to cybercrime 1930; other routes are Childline 1098, the police and emergency 112.","cat":"safe-online-and-off"},
  {"id":"sa-1109","type":"match","persona":"Vikram","source":"calm online response steps","hook":"Match each step of a calm response to an online scare with why it matters.","pairs":[{"left":"Stay calm and thank them","right":"Keeps the child telling you, not hiding"},{"left":"Say 'it's not your fault'","right":"Lifts the shame a victim feels"},{"left":"Keep screenshots and chats","right":"Gives the report something to act on"},{"left":"Report to cybercrime 1930","right":"Brings in people who can stop it"},{"left":"Leave the door open after","right":"Lets the rest come out in time"}],"relearn":"Stay calm, no blame, keep evidence, report to 1930, leave the door open, each step protects the child.","cat":"safe-online-and-off"},
  {"id":"sa-1110","type":"match","persona":"any","source":"online myth to truth","hook":"Match each online-safety myth to the truth that corrects it.","pairs":[{"left":"'It's only a screen, it can't hurt'","right":"Online harm and fear are very real"},{"left":"'They should have known better'","right":"A tricked child is a victim, not at fault"},{"left":"'Only strangers are dangerous'","right":"Known adults can groom online too"},{"left":"'Spying on everything keeps them safe'","right":"Staying close and tellable does"},{"left":"'Just delete it and forget'","right":"Keep evidence, then report"}],"relearn":"Online harm is real, victims aren't at fault, known adults are a risk; stay close and report.","cat":"safe-online-and-off"},
  {"id":"sa-1111","type":"match","persona":"any","source":"info to share or guard online","hook":"Match each piece of information to how to handle it with a new online contact.","pairs":[{"left":"Home address and school name","right":"Never share with an online stranger"},{"left":"Live location and empty-house times","right":"Keep strictly private"},{"left":"Private photos of themselves","right":"Don't send, even if pressured"},{"left":"A favourite film or sport","right":"Harmless to mention"},{"left":"A public game nickname","right":"Fine to use in the game"}],"relearn":"Guard address, school, live location and private photos with online strangers; harmless likes are fine to share.","cat":"safe-online-and-off"},
  {"id":"sa-1112","type":"match","persona":"Vikram","source":"protective habit to payoff","hook":"Match each steady online-safety habit to the protection it gives.","pairs":[{"left":"An open, no-blame door about online life","right":"A child who tells you when something's wrong"},{"left":"Screens in shared family spaces","right":"Fewer hidden, risky private contacts"},{"left":"Talking about tricks before they happen","right":"A child who recognises the flag early"},{"left":"Knowing the report routes","right":"Fast action when something does happen"},{"left":"Modelling safe choices yourself","right":"Kids who copy the safe reflex"}],"relearn":"An open door, shared screens, talk and known routes each protect a child online.","cat":"safe-online-and-off"},
  {"id":"sa-1113","type":"match","persona":"Divya","source":"reassuring line to fear it answers","hook":"Match each reassuring line to the fear it lifts for a child after an online scare.","pairs":[{"left":"'I'm glad you told me'","right":"Fear that telling you was a mistake"},{"left":"'This is not your fault'","right":"Shame that they caused it"},{"left":"'You're not in trouble'","right":"Fear of being punished"},{"left":"'We'll handle this together'","right":"Feeling alone with the problem"},{"left":"'You can always come to me'","right":"Worry that the door is now closed"}],"relearn":"Naming the fear and lifting it, 'glad you told me, not your fault, not in trouble, together', helps a child heal.","cat":"safe-online-and-off"},
  {"id":"sa-1114","type":"match","persona":"any","source":"online red flag to good response","hook":"Match each online red flag to the protective parent response.","pairs":[{"left":"Online friend asks to keep secrets","right":"Talk it through; secrets with adults aren't okay"},{"left":"Threat to leak a private image","right":"Keep evidence, don't pay, report to 1930"},{"left":"Stranger wants to meet alone","right":"Refuse calmly and explain the risk"},{"left":"Child gone secretive about the screen","right":"Gentle check-in, keep the door open"},{"left":"Adult posing as a kid in a game","right":"Stay involved and review who they chat with"}],"relearn":"Each online red flag meets a calm, protective move that keeps a child safe.","cat":"safe-online-and-off"},
  {"id":"sa-1115","type":"reflect","persona":"Vikram","source":"same rule online and off","hook":"Lensy: the rule that protects a child online is the same one that protects them off, be the calm, tellable adult.","prompt":"Sit with that for a moment.","options":["Same rule, both worlds","Be the tellable one","Calm, not fearful"],"affirm":"Online or off, the protection is one thing: a calm adult a child can tell anything, who keeps the door open.","cat":"safe-online-and-off","relearn":"Online or off, the protection is the same: a calm adult a child can tell anything, with the door open."},
  {"id":"sa-1116","type":"reflect","persona":"any","source":"close not surveillance","hook":"Lensy: safety online comes from closeness, not control, the goal is a child who turns to you, not one who hides.","prompt":"What feels true here?","options":["Closeness over control","A child who turns to me","Less hiding, more telling"],"affirm":"Staying close and tellable, not surveilling, is what makes a child bring their online trouble to you.","cat":"safe-online-and-off","relearn":"Staying close and tellable, not surveilling, makes a child bring their online trouble to you."},
  {"id":"sa-1117","type":"reflect","persona":"Divya","source":"victim never at fault","hook":"Lensy: if your child is ever tricked or pressured online, they are the victim, never the one to blame.","prompt":"Let that settle.","options":["My child, the victim","Never their fault","Belief, not blame"],"affirm":"A child tricked, pressured or sextorted online is a victim; meeting them with belief, not blame, is what protects them.","cat":"safe-online-and-off","relearn":"A child tricked or sextorted online is a victim; meeting them with belief, not blame, protects them."},
  {"id":"sa-1118","type":"reflect","persona":"Vikram","source":"prepare despite fear","hook":"Lensy: knowing the online flags and the report routes before you ever need them is itself an act of protection.","prompt":"How does that land?","options":["Ready before I need it","Knowing is protecting","Prepared, not scared"],"affirm":"An informed, ready parent, who knows the flags and the routes, is a child's safety when an online scare actually comes.","cat":"safe-online-and-off","relearn":"Knowing the online flags and report routes before you need them is itself an act of protection."},
  {"id":"sa-1119","type":"reflect","persona":"any","source":"thank the telling","hook":"Lensy: the moment a child shows you something scary online, your calm 'thank you for telling me' is the whole game.","prompt":"Notice what that asks of you.","options":["Calm beats panic","Thank, don't punish","Keep them telling"],"affirm":"Greeting a hard online disclosure with calm thanks, not panic or punishment, keeps your child telling you next time.","cat":"safe-online-and-off","relearn":"Calm thanks for a hard online disclosure, not panic or punishment, keeps a child telling you."},
  {"id":"sa-1120","type":"reflect","persona":"any","source":"door stays open online","hook":"Lensy: the same open door from My Body, My Rules carries online, your child can bring you anything from a screen too.","prompt":"Let it connect.","options":["The door carries online","Anything, screen too","One open door"],"affirm":"The open, no-blame door the whole journey relies on works online too: a child can bring you anything they meet on a screen.","cat":"safe-online-and-off","relearn":"The open, no-blame door the whole journey relies on works online too; a child can bring you anything."},
  {"id":"sa-1121","type":"reflect","persona":"Kamla","source":"small steady steps","hook":"Lensy: you don't need to master every app, just stay interested, keep talking, and be reachable when it matters.","prompt":"Breathe with that.","options":["Interested, not expert","Keep talking","Reachable when it counts"],"affirm":"You don't have to know every app; staying interested, talking often and being reachable is what keeps a child safe online.","cat":"safe-online-and-off","relearn":"You needn't master every app; staying interested, talking and being reachable keeps a child safe online."},
  {"id":"sa-1122","type":"spot","persona":"any","source":"catch the grooming flags","hook":"An online 'friend' has been chatting with your child. Spot the two grooming red flags.","scene":[{"id":"a","text":"Asks your child to keep their chats a total secret","trick":true},{"id":"b","text":"Says 'good game' after a match","trick":false},{"id":"c","text":"Offers gifts and game codes if they stay close","trick":true},{"id":"d","text":"Mentions their own favourite cartoon","trick":false},{"id":"e","text":"Wishes your child a happy festival","trick":false}],"why":"Demanding secrecy and offering gifts to earn closeness are classic grooming moves; the rest is ordinary chat.","cat":"safe-online-and-off","relearn":"Demanding secrecy and offering gifts to earn closeness are grooming flags; the rest is ordinary chat."},
  {"id":"sa-1123","type":"spot","persona":"Vikram","source":"catch the unsafe reactions","hook":"Your child just showed you a scary online message. Spot the two reactions that make things worse.","scene":[{"id":"a","text":"You thank them calmly for showing you","trick":false},{"id":"b","text":"You shout that it's their own fault","trick":true},{"id":"c","text":"You save the screenshots as evidence","trick":false},{"id":"d","text":"You smash the phone in front of them","trick":true},{"id":"e","text":"You decide together to report it to 1930","trick":false}],"why":"Blaming and rage make a child hide the next danger; calm thanks, keeping evidence and reporting are the safe moves.","cat":"safe-online-and-off","relearn":"Blame and rage make a child hide the next danger; calm thanks, evidence and reporting keep them safe."},
  {"id":"sa-1124","type":"spot","persona":"any","source":"catch the surveillance moves","hook":"You want to keep your child safe online. Spot the two moves that are control, not safety.","scene":[{"id":"a","text":"Asking with interest who they chat and game with","trick":false},{"id":"b","text":"Secretly reading every private message","trick":true},{"id":"c","text":"Agreeing together on which apps are okay","trick":false},{"id":"d","text":"Threatening to track them every minute","trick":true},{"id":"e","text":"Inviting them to flag anyone who feels off","trick":false}],"why":"Secret message-reading and constant tracking are control that makes a child hide; interest builds trust.","cat":"safe-online-and-off","relearn":"Secret message-reading and constant tracking are control that makes a child hide."},
  {"id":"sa-1125","type":"spot","persona":"any","source":"catch the oversharing","hook":"Your child is chatting with someone they just met online. Spot the two things they must not share.","scene":[{"id":"a","text":"Their home address and school name","trick":true},{"id":"b","text":"That they like cricket","trick":false},{"id":"c","text":"A private photo of themselves","trick":true},{"id":"d","text":"Their favourite film","trick":false},{"id":"e","text":"A public game nickname","trick":false}],"why":"Home address, school and private photos must never go to an online stranger; harmless likes and a public nickname are fine.","cat":"safe-online-and-off","relearn":"Home address, school and private photos never go to an online stranger; harmless likes are fine."},
  {"id":"sa-1126","type":"spot","persona":"any","source":"catch the myths","hook":"Friends are sharing online-safety 'advice'. Spot the two myths that put a child at risk.","scene":[{"id":"a","text":"'A sextorted child is a victim, never at fault'","trick":false},{"id":"b","text":"'If they sent a photo, it's their own problem'","trick":true},{"id":"c","text":"'Keep evidence, then report online abuse'","trick":false},{"id":"d","text":"'Online harm isn't real, it's just a screen'","trick":true},{"id":"e","text":"'Stay close and keep the door open'","trick":false}],"why":"'Their own problem' and 'online harm isn't real' are dangerous myths; the others protect a child.","cat":"safe-online-and-off","relearn":"'Their own problem' and 'online harm isn't real' are dangerous myths; the rest protect a child."},
  {"id":"sa-1127","type":"spot","persona":"Vikram","source":"catch the wrong sextortion moves","hook":"Your teen is being sextorted online. Spot the two responses that would make it worse.","scene":[{"id":"a","text":"Reassure them it's not their fault","trick":false},{"id":"b","text":"Pay the blackmailer to make it stop","trick":true},{"id":"c","text":"Keep the evidence safe","trick":false},{"id":"d","text":"Tell them they brought this on themselves","trick":true},{"id":"e","text":"Report it to cybercrime 1930","trick":false}],"why":"Paying invites more demands and blame isolates a victim; reassurance, keeping evidence and reporting to 1930 are right.","cat":"safe-online-and-off","relearn":"Paying invites more demands and blame isolates a victim; reassure, keep evidence, report to 1930."},
  {"id":"sa-1128","type":"spot","persona":"any","source":"catch the known-adult-online flags","hook":"A trusted adult is contacting your child online. Spot the two moves that are grooming flags.","scene":[{"id":"a","text":"Messages only your child, privately and at night","trick":true},{"id":"b","text":"Wishes the whole family well in the group","trick":false},{"id":"c","text":"Says your child is their 'special favourite'","trick":true},{"id":"d","text":"Shares homework help in the class group","trick":false},{"id":"e","text":"Sends a festival greeting to everyone","trick":false}],"why":"Private one-to-one contact and 'special favourite' are grooming flags even from a trusted adult.","cat":"safe-online-and-off","relearn":"Private one-to-one contact and 'special favourite' are grooming flags even from a trusted adult."},
  {"id":"sa-1129","type":"spot","persona":"any","source":"catch the evidence mistakes","hook":"You're about to report online harassment of your child. Spot the two moves that would wreck the report.","scene":[{"id":"a","text":"Screenshot the messages and the profile first","trick":false},{"id":"b","text":"Delete everything to feel clean","trick":true},{"id":"c","text":"Note the dates and usernames","trick":false},{"id":"d","text":"Reply angrily so they delete and vanish","trick":true},{"id":"e","text":"Then report it to cybercrime 1930","trick":false}],"why":"Deleting wipes the proof and angry replies tip the abuser off; keep evidence first, then report to 1930.","cat":"safe-online-and-off","relearn":"Deleting wipes the proof and angry replies tip the abuser off; keep evidence first, then report."},
  {"id":"sa-1130","type":"role-play","persona":"Vikram","source":"set up online openness","hook":"You want your child to feel they can tell you about anything strange online, before anything goes wrong.","setup":"Set the open door warmly:","yourLine":[{"text":"\"If anyone online ever makes you uneasy or asks for something odd, just tell me, you'll never be in trouble.\"","best":true},{"text":"\"If something happens online, that's between you and your screen, sort it yourself.\""}],"relearn":"Promising no-trouble openness about anything uneasy online makes a child far likelier to tell you before harm grows.","cat":"safe-online-and-off"},
  {"id":"sa-1131","type":"role-play","persona":"Vikram","source":"steady a sextorted teen","hook":"Your teen, shaking, says someone is threatening to leak a private photo unless they pay.","setup":"Say the steadying words:","yourLine":[{"text":"\"This is not your fault and we'll face it together, don't pay, let's save the proof and report to cybercrime 1930.\"","best":true},{"text":"\"How could you be so stupid as to send that?\""}],"relearn":"A sextorted child needs 'not your fault, together, we'll report'; blame leaves them to face the blackmailer alone.","cat":"safe-online-and-off"},
  {"id":"sa-1132","type":"role-play","persona":"any","source":"thank fast telling","hook":"Your child rushes to you the second a stranger online sends a creepy message.","setup":"Meet them the right way:","yourLine":[{"text":"\"Thank you for showing me straight away, you did exactly the right thing, let's deal with it together.\"","best":true},{"text":"\"Why are you even talking to people like that? Give me the phone.\""}],"relearn":"Calm thanks for fast telling keeps a child coming to you; scolding the messenger teaches them to hide next time.","cat":"safe-online-and-off"},
  {"id":"sa-1133","type":"role-play","persona":"any","source":"refuse the meet calmly","hook":"Your child wants to meet an online-only friend alone and is upset you're hesitant.","setup":"Hold the line with care:","yourLine":[{"text":"\"I'm not angry with you, but meeting someone you've only met online isn't safe, let's find another way.\"","best":true},{"text":"\"Fine, go, just don't come crying to me if it goes wrong.\""}],"relearn":"Refusing an online-only meet calmly, without anger or blame, keeps a child safe and still willing to talk to you.","cat":"safe-online-and-off"},
  {"id":"sa-1134","type":"role-play","persona":"Divya","source":"steady a panicking friend","hook":"A friend is panicking that their child is being targeted online and wants to just smash the phone.","setup":"Steady them toward action:","yourLine":[{"text":"\"Stay calm and support your child, save the messages, and report to cybercrime 1930, that's how you protect them.\"","best":true},{"text":"\"Just take the phone away and never let them online again.\""}],"relearn":"Steadying a friend toward reassurance, evidence and reporting protects the child better than a panicked over-reaction.","cat":"safe-online-and-off"},
  {"id":"sa-1135","type":"role-play","persona":"any","source":"name the grooming flag","hook":"Your child mentions an online friend who keeps asking them to keep their chats a secret.","setup":"Name it gently and clearly:","yourLine":[{"text":"\"A grown-up or friend who wants secret chats with you is a worry, you can always tell me, no trouble.\"","best":true},{"text":"\"If they want it secret, that's your business, none of mine.\""}],"relearn":"Naming secrecy as a flag while promising no trouble teaches a child to spot grooming and keep telling you.","cat":"safe-online-and-off"},
  {"id":"sa-1136","type":"role-play","persona":"Vikram","source":"reassure after a shared photo","hook":"Your child confesses they sent a photo to an online contact and are terrified of your reaction.","setup":"Lift the fear first:","yourLine":[{"text":"\"I'm glad you told me, this isn't the end and it's not your fault, we'll sort it out together.\"","best":true},{"text":"\"You've shamed this family, I can't even look at you.\""}],"relearn":"Leading with 'glad you told me, not your fault, together' turns a frightened confession into a problem you can handle.","cat":"safe-online-and-off"},
  {"id":"sa-1137","type":"role-play","persona":"Kamla","source":"open door despite not knowing apps","hook":"You don't understand all the apps, but you want your child to know they can still come to you.","setup":"Say it in your own honest words:","yourLine":[{"text":"\"I may not know every app, but if anything online ever scares you, come to me, I'll always help you.\"","best":true},{"text":"\"I don't understand any of that, so don't bother bringing it to me.\""}],"relearn":"You don't need to master every app; promising to always help makes a child bring online trouble to you.","cat":"safe-online-and-off"},
  {"id":"sa-1170","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"He's family — relatives are the safest people for my child to be around.\"","myth":{"un":"He's family — relatives are the safest people for my child to be around.","re":"Being a relative is not the same as being safe; most harm to children comes from known, trusted adults, so stay gently alert even with family.","why":"Familiarity is access, not a guarantee of safety."},"relearn":"Being a relative isn't proof of safety; most harm is by known adults, so stay gently alert even within the family.","persona":"Kamla","source":"relative not safe"},
  {"id":"sa-1171","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"A teacher or coach who showers my child with attention is just being kind.\"","myth":{"un":"A teacher or coach who showers my child with attention is just being kind.","re":"Kindness is normal, but singling one child out with gifts, secrets and alone time is a grooming pattern worth watching calmly.","why":"Favouritism plus secrecy is a pattern, not just warmth."},"relearn":"Genuine kindness is fine, but singling one child out with gifts, secrets and alone time is a pattern to watch calmly.","persona":"Vikram","source":"favouritism pattern"},
  {"id":"sa-1172","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If my child were being hurt, there'd be marks I could see.\"","myth":{"un":"If my child were being hurt, there'd be marks I could see.","re":"Much harm leaves no marks; sudden fear, withdrawal or regression in a child can be the only sign, so behaviour matters as much as the body.","why":"Many signs are in behaviour, not on the skin."},"relearn":"Much harm leaves no marks; sudden fear, withdrawal or regression can be the only sign, so watch behaviour, not just the body.","persona":"any","source":"no visible marks"},
  {"id":"sa-1173","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"My child loves spending time with him, so there's nothing to worry about.\"","myth":{"un":"My child loves spending time with him, so there's nothing to worry about.","re":"A child can adore an adult who is grooming them; affection isn't proof of safety, so notice the gifts, secrets and alone time calmly.","why":"Grooming often makes a child fond of the adult."},"relearn":"A child can adore an adult who is grooming them; affection isn't proof of safety, so notice the pattern, not just the fondness.","persona":"any","source":"fondness not proof"},
  {"id":"sa-1174","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Only girls are at risk, so I don't need to watch out for my son.\"","myth":{"un":"Only girls are at risk, so I don't need to watch out for my son.","re":"Children of every gender can be harmed; boys are at real risk too and are often less likely to tell, so the same calm vigilance protects them.","why":"Harm reaches children of every gender."},"relearn":"Children of every gender can be harmed; boys are at risk too and often less likely to tell, so the same vigilance protects them.","persona":"Priya","source":"boys at risk too"},
  {"id":"sa-1175","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"My quiet, well-behaved child has nothing they'd ever need to hide.\"","myth":{"un":"My quiet, well-behaved child has nothing they'd ever need to hide.","re":"Quiet good behaviour can also be fear or shutting down; a sudden change in a calm child is worth noticing gently, not ignoring.","why":"Withdrawal can look like 'being good'."},"relearn":"Quiet good behaviour can also be fear; a sudden change in a calm child is worth noticing gently, not waving away.","persona":"Meena","source":"quiet can be fear"},
  {"id":"sa-1176","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Watching for signs means treating everyone around my child as a suspect.\"","myth":{"un":"Watching for signs means treating everyone around my child as a suspect.","re":"Calm vigilance is not suspicion of everyone; it means knowing the red flags and trusting your child's discomfort, while still keeping warm relationships.","why":"Awareness is not paranoia."},"relearn":"Calm vigilance isn't suspecting everyone; it's knowing the flags and trusting your child's discomfort while keeping warm bonds.","persona":"any","source":"vigilance not suspicion"},
  {"id":"sa-1177","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"An adult who keeps asking my child to keep little secrets is just playing.\"","myth":{"un":"An adult who keeps asking my child to keep little secrets is just playing.","re":"Teaching a child to keep secrets from you is a grooming tool; safe adults talk about 'surprises', not secrets your child must hide from you.","why":"Secrecy from parents is a known red flag."},"relearn":"Teaching a child to keep secrets from you is a grooming tool; safe adults use happy surprises, not secrets hidden from you.","persona":"any","source":"secrets vs surprises"},
  {"id":"sa-1178","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"He gives my child lovely gifts all the time — that just shows he cares.\"","myth":{"un":"He gives my child lovely gifts all the time — that just shows he cares.","re":"Frequent special gifts can build secrecy and obligation in a child; generosity paired with alone time and secrets is worth noticing calmly.","why":"Gifts can be used to buy silence."},"relearn":"Frequent special gifts can build obligation and secrecy; generosity paired with alone time and secrets is worth watching calmly.","persona":"Kamla","source":"gifts build obligation"},
  {"id":"sa-1179","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"My child started wetting the bed and acting younger again — they're just being naughty.\"","myth":{"un":"My child started wetting the bed and acting younger again — they're just being naughty.","re":"Suddenly acting younger, like new bed-wetting or clinginess, can be regression under stress, not naughtiness; meet it with gentle attention, not punishment.","why":"Regression is a signal to check in, not scold."},"relearn":"Suddenly acting younger can be regression under stress, not naughtiness; meet it with gentle attention, not punishment.","persona":"Meena","source":"regression not naughty"},
  {"id":"sa-1180","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If I just teach 'don't talk to strangers', my child is protected.\"","myth":{"un":"If I just teach 'don't talk to strangers', my child is protected.","re":"Stranger-danger misses where most harm comes from — known, trusted adults; teach body-safety and an open door, which protect against anyone.","why":"Most risk is from known adults, not strangers."},"relearn":"Stranger-danger misses where most harm comes from; teach body-safety and an open door, which protect against known adults too.","persona":"Vikram","source":"beyond stranger danger"},
  {"id":"sa-1181","cat":"spot-the-signs","type":"sort","hook":"Sort each into Grooming red flag or Ordinary kindness.","items":[{"id":"a","text":"Insisting on lots of alone time with your child"},{"id":"b","text":"Helping with homework at the kitchen table"},{"id":"c","text":"Asking your child to keep secrets from you"},{"id":"d","text":"Cheering at your child's match with the family"},{"id":"e","text":"Special gifts given only to your child, in private"},{"id":"f","text":"Bringing sweets to share with all the kids openly"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"ok","label":"Ordinary kindness","valence":"pos"}],"key":{"a":"flag","b":"ok","c":"flag","d":"ok","e":"flag","f":"ok"},"relearn":"Alone time, secrets and private gifts are red flags; open help, family cheering and shared sweets are ordinary.","persona":"Vikram","source":"flag or kindness"},
  {"id":"sa-1182","cat":"spot-the-signs","type":"sort","hook":"Sort each into Worth a gentle check-in or Ordinary childhood.","items":[{"id":"a","text":"Sudden fear of a person they used to like"},{"id":"b","text":"Wanting to wear a favourite shirt every day"},{"id":"c","text":"New nightmares and not wanting to be alone"},{"id":"d","text":"Getting bored of an old hobby"},{"id":"e","text":"Going quiet and pulling away from everyone"},{"id":"f","text":"Asking a hundred questions about everything"}],"bins":[{"id":"checkin","label":"Worth a check-in","valence":"uhoh"},{"id":"ordinary","label":"Ordinary","valence":"pos"}],"key":{"a":"checkin","b":"ordinary","c":"checkin","d":"ordinary","e":"checkin","f":"ordinary"},"relearn":"Sudden fear, nightmares and pulling away are worth a gentle check-in; favourite shirts, bored hobbies and questions are ordinary.","persona":"any","source":"checkin or ordinary"},
  {"id":"sa-1183","cat":"spot-the-signs","type":"sort","hook":"Sort each into Calm vigilance or Paranoia.","items":[{"id":"a","text":"Knowing the grooming red flags"},{"id":"b","text":"Accusing every relative of being an abuser"},{"id":"c","text":"Trusting your child's discomfort with someone"},{"id":"d","text":"Refusing to let your child near any adult ever"},{"id":"e","text":"Checking in gently when something seems off"},{"id":"f","text":"Reading danger into every normal hug"}],"bins":[{"id":"calm","label":"Calm vigilance","valence":"pos"},{"id":"para","label":"Paranoia","valence":"neg"}],"key":{"a":"calm","b":"para","c":"calm","d":"para","e":"calm","f":"para"},"relearn":"Knowing flags, trusting discomfort and gentle check-ins are calm vigilance; blanket accusation and fearing every hug are paranoia.","persona":"any","source":"vigilance or paranoia"},
  {"id":"sa-1184","cat":"spot-the-signs","type":"sort","hook":"Sort each into Respecting your child's body or Overriding it.","items":[{"id":"a","text":"Letting your child say no to a hug"},{"id":"b","text":"Forcing a kiss for a relative 'to be polite'"},{"id":"c","text":"Offering a wave instead of a hug"},{"id":"d","text":"Telling your child to stop fussing and sit on a lap"},{"id":"e","text":"Believing them when they shy away"},{"id":"f","text":"Shaming them for not wanting tickles"}],"bins":[{"id":"respect","label":"Respecting","valence":"pos"},{"id":"override","label":"Overriding","valence":"neg"}],"key":{"a":"respect","b":"override","c":"respect","d":"override","e":"respect","f":"override"},"relearn":"Letting a child say no, a wave and believing their unease respect their body; forced kisses, laps and shaming override it.","persona":"Kamla","source":"respect or override"},
  {"id":"sa-1185","cat":"spot-the-signs","type":"sort","hook":"Sort each into Helps you notice or Leaves you blind.","items":[{"id":"a","text":"Knowing the real warning signs"},{"id":"b","text":"Believing 'it can't happen in our family'"},{"id":"c","text":"Keeping an open, no-blame door"},{"id":"d","text":"Assuming respectability means safety"},{"id":"e","text":"Listening when your child seems off"},{"id":"f","text":"Brushing off a sudden change as a phase"}],"bins":[{"id":"helps","label":"Helps you notice","valence":"pos"},{"id":"blind","label":"Leaves you blind","valence":"neg"}],"key":{"a":"helps","b":"blind","c":"helps","d":"blind","e":"helps","f":"blind"},"relearn":"Knowing signs, an open door and listening help you notice; denial, assuming respectability is safety and brushing off changes blind you.","persona":"any","source":"notice or blind"},
  {"id":"sa-1186","cat":"spot-the-signs","type":"sort","hook":"Sort each into Online red flag or Ordinary online life.","items":[{"id":"a","text":"An online 'friend' wanting your child's chats kept secret"},{"id":"b","text":"Watching cartoons on a shared screen"},{"id":"c","text":"A stranger online sending your child gifts or money"},{"id":"d","text":"Playing a game in the family room"},{"id":"e","text":"Someone pushing your child to a private app"},{"id":"f","text":"Video-calling grandparents at the weekend"}],"bins":[{"id":"flag","label":"Online red flag","valence":"neg"},{"id":"ok","label":"Ordinary online life","valence":"pos"}],"key":{"a":"flag","b":"ok","c":"flag","d":"ok","e":"flag","f":"ok"},"relearn":"Secret chats, gifts from strangers and private apps are online red flags; shared screens and family calls are ordinary.","persona":"Vikram","source":"online flag or ok"},
  {"id":"sa-1187","cat":"spot-the-signs","type":"sort","hook":"Sort each into A signal to pay attention or Not a sign on its own.","items":[{"id":"a","text":"Flinching when a certain adult comes near"},{"id":"b","text":"Liking spicy food less than before"},{"id":"c","text":"New, unexplained distress around someone"},{"id":"d","text":"Growing two centimetres taller"},{"id":"e","text":"Suddenly not wanting to visit a familiar home"},{"id":"f","text":"Preferring blue to red this month"}],"bins":[{"id":"signal","label":"Pay attention","valence":"uhoh"},{"id":"not","label":"Not a sign","valence":"neutral"}],"key":{"a":"signal","b":"not","c":"signal","d":"not","e":"signal","f":"not"},"relearn":"Flinching, unexplained distress and avoiding a familiar home are signals to pay attention; tastes, height and colours are not signs.","persona":"any","source":"signal or not"},
  {"id":"sa-1188","cat":"spot-the-signs","type":"sort","hook":"Sort each into A safe adult's habit or A grooming tactic.","items":[{"id":"a","text":"Talking about touch openly, door open"},{"id":"b","text":"Engineering reasons to be alone with one child"},{"id":"c","text":"Respecting a child's 'no' and boundaries"},{"id":"d","text":"Teaching a child to hide things from parents"},{"id":"e","text":"Encouraging the child to tell parents anything"},{"id":"f","text":"Testing limits with 'just one little secret'"}],"bins":[{"id":"safe","label":"Safe adult habit","valence":"pos"},{"id":"groom","label":"Grooming tactic","valence":"neg"}],"key":{"a":"safe","b":"groom","c":"safe","d":"groom","e":"safe","f":"groom"},"relearn":"Open talk, respecting 'no' and encouraging telling are safe; alone time, secrets and testing limits are grooming.","persona":"any","source":"safe habit or grooming"},
  {"id":"sa-1189","cat":"spot-the-signs","type":"sort","hook":"Sort each into Worth noticing in a teen or Ordinary teen stuff.","items":[{"id":"a","text":"Sudden secrecy and panic over their phone"},{"id":"b","text":"Wanting more privacy in their room"},{"id":"c","text":"New fear of a specific older 'friend'"},{"id":"d","text":"Listening to loud new music"},{"id":"e","text":"Unexplained money or gifts they won't explain"},{"id":"f","text":"Sleeping in late on holidays"}],"bins":[{"id":"notice","label":"Worth noticing","valence":"uhoh"},{"id":"ordinary","label":"Ordinary teen stuff","valence":"pos"}],"key":{"a":"notice","b":"ordinary","c":"notice","d":"ordinary","e":"notice","f":"ordinary"},"relearn":"Phone panic, fear of an older 'friend' and unexplained gifts are worth noticing; wanting privacy, loud music and sleeping in are ordinary.","persona":"Vikram","source":"teen notice or ordinary"},
  {"id":"sa-1190","cat":"spot-the-signs","type":"sort","hook":"Sort each into Reads silence as fear or Reads silence as betrayal.","items":[{"id":"a","text":"\"They may be too scared or ashamed\""},{"id":"b","text":"\"They didn't tell me, so they distrust me\""},{"id":"c","text":"\"Someone may have threatened them\""},{"id":"d","text":"\"If real, they'd have told me at once\""},{"id":"e","text":"\"I'll keep the door open for later\""},{"id":"f","text":"\"Silence means it can't have happened\""}],"bins":[{"id":"fear","label":"Reads it as fear","valence":"pos"},{"id":"betray","label":"Reads it as betrayal","valence":"neg"}],"key":{"a":"fear","b":"betray","c":"fear","d":"betray","e":"fear","f":"betray"},"relearn":"Reading silence as fear, threats or an open door is right; reading it as distrust or proof of nothing is not.","persona":"Kamla","source":"silence fear or betrayal"},
  {"id":"sa-1191","cat":"spot-the-signs","type":"sort","hook":"Sort each into A protective response or A response that exposes.","items":[{"id":"a","text":"Trusting your gut when an adult feels 'off'"},{"id":"b","text":"Forcing contact because relatives expect it"},{"id":"c","text":"Gently checking in on a changed child"},{"id":"d","text":"Letting someone talk you out of a real worry"},{"id":"e","text":"Keeping the door open and not punishing telling"},{"id":"f","text":"Hushing a concern to keep the peace"}],"bins":[{"id":"protect","label":"Protective","valence":"pos"},{"id":"expose","label":"Exposes the child","valence":"neg"}],"key":{"a":"protect","b":"expose","c":"protect","d":"expose","e":"protect","f":"expose"},"relearn":"Trusting your gut, checking in and an open door protect; forcing contact, being talked out of a worry and hushing expose.","persona":"Kamla","source":"protect or expose"},
  {"id":"sa-1192","cat":"spot-the-signs","type":"match","hook":"Match each grooming red flag to what it's quietly building.","pairs":[{"left":"Engineering alone time with your child","right":"The access harm needs"},{"left":"Special gifts only for your child","right":"A sense of secret obligation"},{"left":"\"This is our little secret\"","right":"Silence the parent can't hear"},{"left":"Ignoring your child's 'no'","right":"Eroded boundaries"},{"left":"Picking one child as the favourite","right":"Isolation from others"}],"relearn":"Alone time builds access, gifts build obligation, secrets build silence, ignoring 'no' erodes boundaries, favouritism isolates.","persona":"any","source":"flag builds"},
  {"id":"sa-1193","cat":"spot-the-signs","type":"match","hook":"Match each warning sign in a child to a calm, protective response.","pairs":[{"left":"Sudden fear of a familiar adult","right":"Take it seriously and stay close"},{"left":"New withdrawal and quietness","right":"A gentle, loving check-in"},{"left":"Regression, like new bed-wetting","right":"Comfort, not punishment"},{"left":"Flinching from a particular person","right":"Don't force the contact"},{"left":"Unexplained distress you can't place","right":"Keep the door open to talk"}],"relearn":"Meet sudden fear with closeness, withdrawal with a check-in, regression with comfort, and distress with an open door.","persona":"any","source":"sign to response"},
  {"id":"sa-1194","cat":"spot-the-signs","type":"match","hook":"Match each protective practice to the risk it guards against.","pairs":[{"left":"Knowing grooming red flags","right":"Manipulation by a trusted adult"},{"left":"Respecting your child's 'no'","right":"Boundaries being tested away"},{"left":"Staying gently observant","right":"Harm going unnoticed"},{"left":"Trusting your child's discomfort","right":"Their instinct being overruled"},{"left":"Keeping the known-adult risk in mind","right":"False comfort in respectability"}],"relearn":"Knowing flags, respecting 'no', observing, trusting discomfort and remembering the known-adult risk each guard against how harm takes hold.","persona":"Kamla","source":"practice guards risk"},
  {"id":"sa-1195","cat":"spot-the-signs","type":"match","hook":"Match each myth to the calm fact that replaces it.","pairs":[{"left":"\"Danger is mainly strangers\"","right":"Most harm is by known adults"},{"left":"\"A respectable adult is safe\"","right":"Respectability isn't safety"},{"left":"\"There'd be marks if real\"","right":"Many signs are behavioural"},{"left":"\"My child would tell me at once\"","right":"Fear and shame silence children"},{"left":"\"Watching is paranoia\"","right":"Calm vigilance is awareness"}],"relearn":"Most harm is by known adults, respectability isn't safety, signs can be behavioural, fear silences children.","persona":"any","source":"myth to fact"},
  {"id":"sa-1196","cat":"spot-the-signs","type":"match","hook":"Match each online red flag to why it's worth noticing.","pairs":[{"left":"An online 'friend' wanting secret chats","right":"Building secrecy from you"},{"left":"Gifts or game-credit from a stranger","right":"Creating obligation"},{"left":"Pushing to a private, hidden app","right":"Isolating your child"},{"left":"Asking for photos 'just between us'","right":"Setting up exploitation"},{"left":"Knowing oddly personal details","right":"Grooming research"}],"relearn":"Online secrets build silence, gifts build obligation, private apps isolate, photo requests set up exploitation, and personal details signal grooming.","persona":"Vikram","source":"online flag why"},
  {"id":"sa-1197","cat":"spot-the-signs","type":"match","hook":"Match each safe-adult habit to the protection it gives a child.","pairs":[{"left":"Talking about touch openly","right":"A child who can name what's wrong"},{"left":"Letting your child refuse affection","right":"Body autonomy they can use"},{"left":"Never punishing hard news","right":"A child who will tell you"},{"left":"Believing their discomfort","right":"Trust in their own instinct"},{"left":"Keeping the door open in advance","right":"A path back when something's off"}],"relearn":"Open touch-talk lets a child name harm, refusing affection builds autonomy, no punishment keeps them telling, and an open door is a path back.","persona":"any","source":"habit gives protection"},
  {"id":"sa-1198","cat":"spot-the-signs","type":"match","hook":"Match each calm reading of silence to the fear behind it.","pairs":[{"left":"\"They went quiet, not cold\"","right":"They may be scared, not distant"},{"left":"\"They didn't say at once\"","right":"Shame can delay telling"},{"left":"\"They kept it secret\"","right":"Someone may have threatened them"},{"left":"\"They seem confused about it\"","right":"Children can struggle to make sense of it"},{"left":"\"They haven't told me yet\"","right":"The door staying open lets them later"}],"relearn":"Silence can be fear not coldness, shame can delay telling, threats can force secrecy, confusion is common, and an open door lets a child tell later.","persona":"Kamla","source":"silence to fear"},
  {"id":"sa-1199","cat":"spot-the-signs","type":"match","hook":"Match each situation to whether it's a sign or ordinary life.","pairs":[{"left":"Sudden terror of bath time with one person","right":"A sign worth noticing"},{"left":"Outgrowing a babyish toy","right":"Ordinary growing up"},{"left":"New, unexplained marks plus distress","right":"A second sign worth noticing"},{"left":"Preferring friends to family outings","right":"Ordinary part of growing up"},{"left":"Going silent and clingy after visiting someone","right":"A third sign worth noticing"}],"relearn":"Sudden terror of one person, marks with distress and new silence after a visit are signs; outgrowing toys is ordinary.","persona":"any","source":"sign or ordinary life"},
  {"id":"sa-1200","cat":"spot-the-signs","type":"reflect","hook":"Lensy: most harm to children comes from someone they know and trust, not a stranger. How does that land for you?","prompt":"What's true for you?","options":["It changes where I look","Known adults, not strangers","I'll stay gently alert"],"affirm":"Knowing that most harm comes from a known, trusted adult is exactly what helps you protect your child — gently, not fearfully.","relearn":"Most harm comes from a known, trusted adult; holding that calmly is what helps you protect your child.","persona":"any","source":"known-adult lands"},
  {"id":"sa-1201","cat":"spot-the-signs","type":"reflect","hook":"Lensy: you can stay alert to the signs without slipping into suspicion of everyone. Does that feel possible?","prompt":"How does that sit?","options":["It feels possible","Calm, not fearful","Aware, not suspicious"],"affirm":"Calm vigilance, not paranoia, is the goal — you can know the red flags and still keep warm, trusting relationships.","relearn":"You can know the red flags and stay alert while keeping warm relationships — calm vigilance, not paranoia.","persona":"any","source":"alert not suspicious"},
  {"id":"sa-1202","cat":"spot-the-signs","type":"reflect","hook":"Lensy: respecting your child's discomfort with someone — even a relative — is protective, not rude. Agree?","prompt":"What do you think?","options":["It's protective","Their 'no' counts","I'll back them up"],"affirm":"Backing your child's discomfort, instead of forcing affection 'to be polite', tells them their body and instincts matter.","relearn":"Respecting a child's discomfort, even with a relative, is protective; it tells them their body and instincts matter.","persona":"Kamla","source":"discomfort protective"},
  {"id":"sa-1203","cat":"spot-the-signs","type":"reflect","hook":"Lensy: a sign is a reason to check in gently, not proof, and not a reason to interrogate your child. Sit right?","prompt":"Does that sit right?","options":["It sits right","A signal, not proof","Check in, don't grill"],"affirm":"A sign means pay attention and check in gently — it isn't proof, and your child should never feel interrogated.","relearn":"A sign is a signal to pay attention and check in gently, not proof, and never a reason to interrogate a child.","persona":"any","source":"signal not proof"},
  {"id":"sa-1204","cat":"spot-the-signs","type":"reflect","hook":"Lensy: noticing a change early — and trusting yourself enough to ask gently — is part of being the safe adult. Land okay?","prompt":"How does it land?","options":["It lands okay","I can notice early","I'll trust my gut"],"affirm":"Trusting yourself to notice a change and check in early, calmly, is one of the quiet strengths of a safe adult.","relearn":"Noticing a change early and trusting yourself to check in gently is part of being the safe adult.","persona":"Divya","source":"notice early"},
  {"id":"sa-1205","cat":"spot-the-signs","type":"reflect","hook":"Lensy: an adult who keeps engineering secrets and alone time with your child is worth a second look, even if they're well-liked. Agree?","prompt":"What's your take?","options":["Worth a second look","Liked isn't always safe","I'll watch the pattern"],"affirm":"Being well-liked isn't proof of safety; secrets, gifts and alone time are a pattern worth noticing calmly, whoever they are.","relearn":"Being well-liked isn't proof of safety; secrets, gifts and alone time are a pattern worth noticing calmly.","persona":"any","source":"liked not safe"},
  {"id":"sa-1206","cat":"spot-the-signs","type":"reflect","hook":"Lensy: a boy can be at risk too, and may be even less likely to tell — so the same calm watchfulness protects him. Ring true?","prompt":"Does that ring true?","options":["It rings true","Boys are at risk too","Same care for everyone"],"affirm":"Children of every gender can be harmed; watching for the same signs and keeping the same open door protects them all.","relearn":"Children of every gender can be harmed; the same signs and the same open door protect them all.","persona":"Priya","source":"boys risk reflect"},
  {"id":"sa-1207","cat":"spot-the-signs","type":"spot","hook":"Spot the two grooming red flags around your child.","scene":[{"id":"a","text":"Keeps engineering reasons to be alone with your child","trick":true},{"id":"b","text":"Helps with homework at the kitchen table","trick":false},{"id":"c","text":"Gives secret gifts to hide from you","trick":true},{"id":"d","text":"Cheers for your child at the family match","trick":false},{"id":"e","text":"Respects it when your child says 'no'","trick":false}],"why":"Engineered alone time and secret gifts are red flags; open help and respecting 'no' are safe.","relearn":"Engineered alone time and secret gifts are red flags; open help and respecting 'no' are safe.","persona":"Vikram","source":"spot grooming flags"},
  {"id":"sa-1208","cat":"spot-the-signs","type":"spot","hook":"Spot the two lines that treat respectability as safety.","scene":[{"id":"a","text":"\"He's so respectable, he could never be a risk\"","trick":true},{"id":"b","text":"\"I'll stay gently alert even with people I trust\"","trick":false},{"id":"c","text":"\"Such a nice family man, no need to watch\"","trick":true},{"id":"d","text":"\"Respectability isn't the same as being safe\"","trick":false},{"id":"e","text":"\"I'll trust my child's discomfort\"","trick":false}],"why":"The caught lines treat respectability as proof of safety; calm vigilance is what protects.","relearn":"Respectability isn't proof of safety; staying gently alert and trusting discomfort protects.","persona":"any","source":"spot respectability myth"},
  {"id":"sa-1209","cat":"spot-the-signs","type":"spot","hook":"Spot the two red flags in this online 'friend' your teen has made.","scene":[{"id":"a","text":"Wants all their chats kept secret from you","trick":true},{"id":"b","text":"Plays the game in the family room","trick":false},{"id":"c","text":"Sends gifts and pushes to a private hidden app","trick":true},{"id":"d","text":"Chats about the match score in the group","trick":false},{"id":"e","text":"Is happy for you to see the conversation","trick":false}],"why":"Demanding secret chats and pushing to a hidden app with gifts are grooming red flags; open, visible play is not.","relearn":"Secret chats and a push to a private app with gifts are online red flags; open, visible play is fine.","persona":"Vikram","source":"spot online flags"},
  {"id":"sa-1210","cat":"spot-the-signs","type":"spot","hook":"Spot the two responses that ignore the warning signs.","scene":[{"id":"a","text":"Forcing them to hug the relative they now fear","trick":true},{"id":"b","text":"Staying close and gently asking what changed","trick":false},{"id":"c","text":"Scolding their new bed-wetting as naughtiness","trick":true},{"id":"d","text":"Comforting them when they seem withdrawn","trick":false},{"id":"e","text":"Keeping the door open so they can tell you","trick":false}],"why":"Forcing feared contact and scolding regression ignore the signs; closeness and comfort honour them.","relearn":"Forcing feared contact and scolding regression ignore the signs; closeness and an open door honour them.","persona":"any","source":"spot ignoring signs"},
  {"id":"sa-1211","cat":"spot-the-signs","type":"spot","hook":"Spot the two lines that tip vigilance into paranoia.","scene":[{"id":"a","text":"\"I'll never let my child near any adult again\"","trick":true},{"id":"b","text":"\"I'll learn the red flags and stay gently alert\"","trick":false},{"id":"c","text":"\"Every relative is a suspect till proven safe\"","trick":true},{"id":"d","text":"\"I'll trust my child's discomfort with someone\"","trick":false},{"id":"e","text":"\"I can stay warm and watchful at once\"","trick":false}],"why":"Cutting off all adults or suspecting everyone is paranoia; learning flags is calm vigilance.","relearn":"Cutting off all adults or suspecting everyone is paranoia; learning flags and staying warm is vigilance.","persona":"any","source":"spot paranoia"},
  {"id":"sa-1212","cat":"spot-the-signs","type":"spot","hook":"Spot the two 'secret' moves that are red flags.","scene":[{"id":"a","text":"\"Don't tell your parents, it's our secret\"","trick":true},{"id":"b","text":"\"Let's surprise Mum on Sunday\"","trick":false},{"id":"c","text":"\"This stays between us or you'll be in trouble\"","trick":true},{"id":"d","text":"\"You can always tell your parents anything\"","trick":false},{"id":"e","text":"\"We'll surprise the family with cake later\"","trick":false}],"why":"Secrets a child must hide from you, especially with threats, are red flags; happy surprises are fine.","relearn":"Secrets a child must hide from you are red flags; happy surprises everyone soon shares are fine.","persona":"any","source":"spot secrets vs surprises"},
  {"id":"sa-1213","cat":"spot-the-signs","type":"spot","hook":"Spot the two beliefs that would blind you to harm.","scene":[{"id":"a","text":"\"It can't happen in a family like ours\"","trick":true},{"id":"b","text":"\"Harm can reach any child, so I'll stay ready\"","trick":false},{"id":"c","text":"\"If it were real, there'd be marks to see\"","trick":true},{"id":"d","text":"\"Many signs show in behaviour, not the body\"","trick":false},{"id":"e","text":"\"A sudden change is worth a gentle check-in\"","trick":false}],"why":"'It can't happen here' and 'there'd be marks' are myths that blind a parent; readiness keeps you alert.","relearn":"'It can't happen here' and 'there'd be marks' blind a parent; readiness and watching behaviour keep you alert.","persona":"any","source":"spot blinding beliefs"},
  {"id":"sa-1214","cat":"spot-the-signs","type":"spot","hook":"Spot the two things that override your child's body.","scene":[{"id":"a","text":"Forcing a kiss for an uncle 'to be polite'","trick":true},{"id":"b","text":"Letting your child offer a wave instead","trick":false},{"id":"c","text":"Shaming them for not wanting to sit on a lap","trick":true},{"id":"d","text":"Believing them when they shy away","trick":false},{"id":"e","text":"Letting your child decide who hugs them","trick":false}],"why":"Forcing a kiss and shaming override a child's body; a wave, belief and choice protect it.","relearn":"Forcing affection and shaming override a child's body; a wave, belief and choice protect it.","persona":"Kamla","source":"spot override body"},
  {"id":"sa-1215","cat":"spot-the-signs","type":"branch","hook":"A trusted uncle keeps taking your child off alone, with gifts and 'secrets'.","options":[{"text":"Stay nearby, keep things open, and watch the pattern","consequence":"You close off the alone time without an accusation.","outcome":"stay-open","best":true},{"text":"Tell yourself he's family, so it's rude to think twice","consequence":"Dismissing it as 'family' ignores a real red flag."}],"debrief":"Alone time, gifts and secrets: keep things open and watch, don't dismiss it.","relearn":"Meet engineered alone time, gifts and secrets by keeping things open and watching calmly.","persona":"Kamla","source":"uncle alone time"},
  {"id":"sa-1216","cat":"spot-the-signs","type":"branch","hook":"Your child suddenly cries and clings whenever a familiar neighbour visits.","options":[{"text":"Take it seriously, stay close, gently ask what's changed","consequence":"You honour the signal and stay their safe place.","outcome":"take-seriously","best":true},{"text":"Make them greet the neighbour so you don't seem rude","consequence":"Forcing contact overrides your child's clear distress."}],"debrief":"A sudden, specific fear of someone familiar is a signal: stay close and ask gently.","relearn":"Treat a sudden fear of someone familiar as a signal; stay close and ask gently, don't force it.","persona":"any","source":"sudden clinging"},
  {"id":"sa-1217","cat":"spot-the-signs","type":"branch","hook":"An older 'friend' online showers your teen with gifts and asks them to keep it secret.","options":[{"text":"Stay calm, keep the door open, talk it through, watch","consequence":"You stay involved without shaming your teen into hiding it.","outcome":"stay-involved","best":true},{"text":"Snatch the phone and ban everything in a rage","consequence":"Punishing in anger drives a worried teen to hide more."}],"debrief":"Secret gifts from an older online 'friend' are a flag: stay calm and keep the door open.","relearn":"Meet secret gifts from an older online 'friend' with calm closeness and an open door, not rage.","persona":"Vikram","source":"online older friend"},
  {"id":"sa-1218","cat":"spot-the-signs","type":"branch","hook":"Another parent insists you're 'overthinking' your unease about an adult near your child.","options":[{"text":"Thank them, but trust your instinct and stay close","consequence":"You stay the safe adult even when others dismiss you.","outcome":"trust-instinct","best":true},{"text":"Let them talk you out of it to avoid looking paranoid","consequence":"Being talked out of a real worry can leave a child exposed."}],"debrief":"When someone dismisses your unease about an adult near your child, trust your instinct.","relearn":"Trust your protective instinct even when others dismiss it, not your fear of looking paranoid.","persona":"Kamla","source":"others dismiss worry"},
  {"id":"sa-1219","cat":"spot-the-signs","type":"branch","hook":"A respected coach gives your child 'special' one-on-one sessions behind closed doors.","options":[{"text":"Calmly ask for sessions to stay open and observed","consequence":"You remove the secret access without accusing anyone.","outcome":"keep-open","best":true},{"text":"Feel flattered and let the closed-door sessions continue","consequence":"Flattery at being chosen can blind you to engineered alone time."}],"debrief":"Closed-door 'special' alone time is a flag whoever it is: keep it open and observed.","relearn":"Closed-door 'special' alone time is a flag; calmly keep sessions open, not trusting respect alone.","persona":"Vikram","source":"coach closed door"},
  {"id":"sa-1220","cat":"spot-the-signs","type":"branch","hook":"Your once-cheerful child has gone quiet and withdrawn, and you can't place why.","options":[{"text":"Gently check in, stay warm, keep the door open","consequence":"You invite your child to open up at their own pace.","outcome":"gentle-checkin","best":true},{"text":"Interrogate them with sharp questions till they answer","consequence":"Interrogation can frighten a child into shutting down more."}],"debrief":"A sudden withdrawal calls for a gentle check-in and an open door, not interrogation.","relearn":"Meet a sudden withdrawal with a gentle check-in and an open door, not interrogation.","persona":"Meena","source":"withdrawn child"},
  {"id":"sa-1221","cat":"spot-the-signs","type":"branch","hook":"You spot unexplained marks on your child along with new distress.","options":[{"text":"Stay calm, comfort them, give gentle space to talk","consequence":"You hold steady and let your child feel safe, not grilled.","outcome":"calm-space","best":true},{"text":"Panic visibly and fire off questions about every detail","consequence":"Visible panic and detailed questioning can make a child shut down."}],"debrief":"Unexplained marks plus distress deserve calm comfort and gentle space, not panic.","relearn":"Meet unexplained marks plus distress with calm comfort and gentle space, not panic or grilling.","persona":"any","source":"marks plus distress"},
  {"id":"sa-1222","cat":"spot-the-signs","type":"branch","hook":"At a family gathering, relatives press your shy child to 'give a kiss' to everyone.","options":[{"text":"Step in and offer a wave or high-five instead","consequence":"You protect their body autonomy and back their 'no'.","outcome":"offer-wave","best":true},{"text":"Push your child to comply so the family isn't offended","consequence":"Forcing affection teaches a child their 'no' doesn't count."}],"debrief":"Forced 'give a kiss' moments override a child's body; offer a wave instead.","relearn":"Don't force affection 'to be polite'; offer a wave and let a child's 'no' stand.","persona":"Kamla","source":"forced family kiss"},
  {"id":"sa-1223","cat":"spot-the-signs","type":"role-play","hook":"Your child has gone quiet and you want to open a door without alarming them.","setup":"Check in gently:","yourLine":[{"text":"\"You've seemed a bit quiet lately, sweetheart. I'm here and you can tell me anything, with no trouble.\"","best":true},{"text":"\"Why are you being so moody all the time? Stop it.\""}],"relearn":"A gentle, no-trouble check-in invites a withdrawn child to open up; impatience makes them retreat further.","persona":"Kamla","source":"quiet check-in"},
  {"id":"sa-1224","cat":"spot-the-signs","type":"role-play","hook":"Your child suddenly doesn't want to visit an uncle they used to love.","setup":"Honour the signal:","yourLine":[{"text":"\"You don't have to go if you don't want to. Can you tell me what changed? I'm listening.\"","best":true},{"text":"\"Don't be silly, he's your uncle. You're going and that's final.\""}],"relearn":"Backing a child's sudden reluctance and asking gently honours the signal; forcing the visit overrides their instinct.","persona":"any","source":"reluctant visit"},
  {"id":"sa-1225","cat":"spot-the-signs","type":"role-play","hook":"A relative is pushing your shy child to sit on their lap and hug.","setup":"Protect their body autonomy:","yourLine":[{"text":"\"She'll wave hello — she gets to choose who hugs her, and that's okay.\"","best":true},{"text":"\"Go on, give a hug, don't be rude to your aunty.\""}],"relearn":"Letting a child choose who hugs them protects their body autonomy; forcing affection teaches their 'no' doesn't count.","persona":"Kamla","source":"lap pressure"},
  {"id":"sa-1226","cat":"spot-the-signs","type":"role-play","hook":"You want to set up secrets-vs-surprises with your child, in advance.","setup":"Teach the difference:","yourLine":[{"text":"\"Happy surprises we share soon are fun. But no grown-up should ask you to keep a secret from me — you can always tell me.\"","best":true},{"text":"\"Good children keep whatever secrets grown-ups tell them to.\""}],"relearn":"Teaching that no adult should ask a child to keep secrets from you removes a grooming tool; demanding obedience to adults' secrets hands it back.","persona":"any","source":"secrets vs surprises talk"},
  {"id":"sa-1227","cat":"spot-the-signs","type":"role-play","hook":"Another parent calls your watchfulness about an adult 'paranoid'.","setup":"Hold your calm vigilance:","yourLine":[{"text":"\"I'm not accusing anyone. I just keep things open and trust my child's comfort — that's how I look out for her.\"","best":true},{"text":"\"You're right, I'm probably overreacting. I'll stop paying attention.\""}],"relearn":"Naming your watchfulness as calm, open vigilance holds the protective line; abandoning it to avoid looking paranoid drops your guard.","persona":"any","source":"called paranoid"},
  {"id":"sa-1228","cat":"spot-the-signs","type":"role-play","hook":"Your teen mentions an older online 'friend' who wants to keep things secret.","setup":"Keep the door open, not slammed:","yourLine":[{"text":"\"Thanks for telling me. Anyone asking you to keep secrets from me is a worry — let's look at this together, you're not in trouble.\"","best":true},{"text":"\"That's it, you're banned from your phone. I don't want to hear another word.\""}],"relearn":"Thanking a teen and staying calm keeps them telling you; a furious ban teaches them to hide the next, bigger problem.","persona":"Vikram","source":"teen online secret"},
  {"id":"sa-1229","cat":"spot-the-signs","type":"role-play","hook":"You notice your child acting younger again — new clinginess and bed-wetting.","setup":"Respond to the regression with care:","yourLine":[{"text":"\"It's okay, these things happen, I'm not cross. I'm right here if anything's been worrying you.\"","best":true},{"text":"\"You're too big for this. I'm very disappointed in you.\""}],"relearn":"Meeting regression with reassurance keeps a stressed child close; shaming them shuts the door you need open.","persona":"Meena","source":"regression care"},
  {"id":"sa-1260","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"They were 16 and said yes, so it isn't really a POCSO matter.\"","myth":{"un":"They were 16 and said yes, so it isn't a crime.","re":"Under POCSO, an under-18 can't legally consent, so the offence is still a crime.","why":"The law sets the line at 18; a child's 'yes' can't make harm legal."},"relearn":"An under-18 can't consent; it's still a crime, child still the victim.","persona":"any","source":"under 18 cannot consent"},
  {"id":"sa-1261","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"It was an adult woman and a boy, so POCSO doesn't apply.\"","myth":{"un":"POCSO only protects girls.","re":"POCSO is gender-neutral; it protects every child under 18, boys and girls alike.","why":"A harmed boy is just as much a protected victim under the law."},"relearn":"POCSO is gender-neutral; it protects every child, boys and girls.","persona":"Vikram","source":"gender-neutral law"},
  {"id":"sa-1262","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"I'm not a teacher or doctor, so it isn't my job to report this.\"","myth":{"un":"Only officials have to report child abuse.","re":"Anyone who knows or suspects a child is being abused can and should report it.","why":"You don't need a title to pick up the phone and protect a child."},"relearn":"Any adult who suspects child abuse can report it; you needn't be an official.","persona":"Kamla","source":"anyone can report"},
  {"id":"sa-1263","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"If I report and I'm wrong, I'll be in trouble for it.\"","myth":{"un":"You'll be punished if your report turns out wrong.","re":"A genuine good-faith concern is exactly what the system wants; professionals assess it.","why":"You report a worry, not a verdict; deciding is their job."},"relearn":"Report a good-faith concern; pros assess it, you needn't be proven right.","persona":"Divya","source":"good-faith report"},
  {"id":"sa-1264","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"He's family and he's sorry, so the law shouldn't get involved.\"","myth":{"un":"If the relative apologises, the law needn't get involved.","re":"An apology doesn't undo a crime against a child; it still needs reporting.","why":"Sorry isn't safety; the child's protection comes before family peace."},"relearn":"An apology doesn't cancel a crime; report it and protect the child anyway.","persona":"Kamla","source":"apology isn't safety"},
  {"id":"sa-1265","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"Going to the police will traumatise my child all over again.\"","myth":{"un":"Reporting will only re-traumatise the child.","re":"POCSO has child-friendly steps to ease distress; not reporting leaves the child unprotected.","why":"The process is built to be gentler; silence protects only the abuser."},"relearn":"POCSO has child-friendly steps; reporting protects, silence shields the abuser.","persona":"Divya","source":"child-friendly process"},
  {"id":"sa-1266","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"Showing the photos around the colony will shame him into stopping.\"","myth":{"un":"Sharing the images to shame the abuser will fix it.","re":"Sharing images of a child's abuse spreads the harm and is itself an offence.","why":"Circulating it re-victimises the child; only the authorities should hold it."},"relearn":"Never circulate images of abuse; give evidence only to the authorities.","persona":"Vikram","source":"don't circulate evidence"},
  {"id":"sa-1267","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"It happened two years ago, so it's too late to report now.\"","myth":{"un":"Old abuse is too late to report.","re":"A child can disclose long after harm; a past offence can still be reported now.","why":"Children often tell late; reporting still protects them and others."},"relearn":"Abuse can be reported long after; late disclosure still deserves action.","persona":"Kamla","source":"late disclosure counts"},
  {"id":"sa-1268","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"Let's settle it quietly with money and keep it out of court.\"","myth":{"un":"A quiet cash settlement is a fine way to handle it.","re":"A sexual offence against a child is a crime, not a debt to settle privately.","why":"You can't buy off a child's safety; reporting is what protects them."},"relearn":"Abuse is a crime to report, not a debt to settle quietly with money.","persona":"any","source":"not a settlement"},
  {"id":"sa-1269","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"I should confront and gather proof myself before telling anyone.\"","myth":{"un":"I must investigate and get proof before reporting.","re":"Investigating yourself can warn the abuser; report and let professionals gather evidence.","why":"Your job is to flag and protect; building the case is theirs."},"relearn":"Don't self-investigate; report and let professionals gather evidence.","persona":"Vikram","source":"don't self-investigate"},
  {"id":"sa-1270","cat":"the-law-and-the-call","type":"strike-rewrite","hook":"\"If I report, my child will be taken away from me.\"","myth":{"un":"Reporting means my child gets taken from me.","re":"Reporting aims to stop the person harming the child, not punish a protective parent.","why":"A parent protecting their child is what the system wants."},"relearn":"Reporting targets the abuser, not the protective parent; you're the child's ally.","persona":"Kamla","source":"protective parent"},
  {"id":"sa-1271","cat":"the-law-and-the-call","type":"match","hook":"Match each route to when you'd use it (India).","pairs":[{"left":"Childline 1098","right":"A child in distress, any hour"},{"left":"POCSO e-Box","right":"Reporting a child sexual offence online"},{"left":"Cybercrime 1930","right":"Online grooming or sextortion of a child"},{"left":"Local police","right":"Filing a complaint in person"},{"left":"Emergency 112","right":"A child being harmed right now"}],"relearn":"Childline 1098, the e-Box, cybercrime 1930, police and 112 each fit a need.","persona":"any","source":"route to need"},
  {"id":"sa-1272","cat":"the-law-and-the-call","type":"match","hook":"Match each plain idea to the POCSO truth behind it.","pairs":[{"left":"\"A child can't consent\"","right":"An under-18 can't legally agree to it"},{"left":"\"A crime, not a quarrel\"","right":"An offence against a child is criminal"},{"left":"\"The child didn't cause this\"","right":"The child is the victim, never to blame"},{"left":"\"Telling is required\"","right":"Reporting a concern is obliged"},{"left":"\"Not legal advice\"","right":"Route real concerns to the authorities"}],"relearn":"A child can't consent, it's a crime, the child is the victim, reporting is obliged.","persona":"Kamla","source":"ideas to law"},
  {"id":"sa-1273","cat":"the-law-and-the-call","type":"match","hook":"Match each parent's worry to the answer that frees them to act.","pairs":[{"left":"\"What if I'm wrong?\"","right":"Pros assess it; report in good faith"},{"left":"\"It's a family matter\"","right":"Abuse is a crime, not private"},{"left":"\"It's too shameful\"","right":"The shame is the abuser's"},{"left":"\"I have no proof\"","right":"You report a concern, not a case"},{"left":"\"Who do I call?\"","right":"Childline 1098 or the police"}],"relearn":"Each worry has an answer: report in good faith, it's a crime, no proof needed.","persona":"Divya","source":"worry to answer"},
  {"id":"sa-1274","cat":"the-law-and-the-call","type":"match","hook":"Match each situation to the first route that fits (India).","pairs":[{"left":"A stranger online pressures your child for photos","right":"Cybercrime 1930"},{"left":"A child next door seems in danger tonight","right":"Emergency 112"},{"left":"You want to talk through a worry","right":"Childline 1098"},{"left":"You're ready to formally report","right":"Police or the e-Box"},{"left":"You're unsure it's serious enough","right":"Childline 1098 can guide"}],"relearn":"Match it to the route: 1930 online, 112 now, 1098 to talk, police or e-Box to file.","persona":"Vikram","source":"situation to route"},
  {"id":"sa-1275","cat":"the-law-and-the-call","type":"match","hook":"Match each false belief to the fact that corrects it.","pairs":[{"left":"\"POCSO only covers girls\"","right":"It protects every child under 18"},{"left":"\"A 16-year-old can consent\"","right":"Under 18 cannot consent"},{"left":"\"Only officials report\"","right":"Any adult can and should"},{"left":"\"An apology settles it\"","right":"A crime still needs reporting"},{"left":"\"Too late after years\"","right":"Late disclosure can still be reported"}],"relearn":"POCSO covers all children who can't consent; anyone can report; late harm still counts.","persona":"any","source":"belief to fact"},
  {"id":"sa-1276","cat":"the-law-and-the-call","type":"match","hook":"Match each routes-card line to who it reaches (India).","pairs":[{"left":"1098","right":"Childline, the child help number"},{"left":"1930","right":"The cybercrime reporting line"},{"left":"112","right":"The all-in-one emergency number"},{"left":"POCSO e-Box","right":"The online child-offence report box"},{"left":"The police station","right":"Filing a complaint in person"}],"relearn":"1098 is Childline, 1930 cybercrime, 112 emergency; the e-Box and police take reports.","persona":"any","source":"number to who"},
  {"id":"sa-1277","cat":"the-law-and-the-call","type":"match","hook":"Match each protective belief to the action it leads to.","pairs":[{"left":"The child is the victim","right":"Comfort them, never blame"},{"left":"Reporting is obliged","right":"Make the call, don't sit on it"},{"left":"You needn't be certain","right":"Flag a good-faith concern"},{"left":"Not legal advice","right":"Route the real worry to authorities"},{"left":"Online harm is real harm","right":"Keep evidence and report to 1930"}],"relearn":"Each belief drives an action: support, report, flag, route, and keep evidence.","persona":"Vikram","source":"belief to action"},
  {"id":"sa-1278","cat":"the-law-and-the-call","type":"match","hook":"Match each plain phrase to the route it points to (India).","pairs":[{"left":"\"A child needs help right now\"","right":"Childline 1098 or 112"},{"left":"\"It started on a chat app\"","right":"Cybercrime 1930"},{"left":"\"I want to lodge a complaint\"","right":"Police or the e-Box"},{"left":"\"I'm not sure where to start\"","right":"Childline 1098 to talk"},{"left":"\"Someone's in danger this minute\"","right":"Emergency 112"}],"relearn":"Phrases map to routes: 1098 or 112 for help now, 1930 online, police or e-Box to file.","persona":"Kamla","source":"phrase to route"},
  {"id":"sa-1279","cat":"the-law-and-the-call","type":"sort","hook":"Sort each step: protects the child, or leaves them at risk?","items":[{"id":"a","text":"Reporting the offence to the police"},{"id":"b","text":"Believing the child and getting help"},{"id":"c","text":"Hiding it to protect the family name"},{"id":"d","text":"Telling the child to forget it"},{"id":"e","text":"Calling Childline 1098 to talk it through"},{"id":"f","text":"Paying the abuser to stay quiet"}],"bins":[{"id":"protects","label":"Protects the child","valence":"pos"},{"id":"risk","label":"Leaves them at risk","valence":"neg"}],"key":{"a":"protects","b":"protects","c":"risk","d":"risk","e":"protects","f":"risk"},"relearn":"Reporting, believing and calling 1098 protect; hiding, silencing or paying off don't.","persona":"any","source":"protects vs risk"},
  {"id":"sa-1280","cat":"the-law-and-the-call","type":"sort","hook":"Sort: which line under the law is true, and which is a myth?","items":[{"id":"a","text":"An under-18 cannot consent"},{"id":"b","text":"The child is always the victim"},{"id":"c","text":"If the child agreed, it's not a crime"},{"id":"d","text":"Reporting a concern is obliged"},{"id":"e","text":"Boys aren't covered by the law"},{"id":"f","text":"You can settle it privately for money"}],"bins":[{"id":"true","label":"True under the law","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"true","e":"myth","f":"myth"},"relearn":"Under-18s can't consent, the child is the victim, reporting is obliged; the rest are myths.","persona":"Kamla","source":"law true vs myth"},
  {"id":"sa-1281","cat":"the-law-and-the-call","type":"sort","hook":"Sort each route by what it's mainly for (India).","items":[{"id":"a","text":"Childline 1098"},{"id":"b","text":"Cybercrime 1930"},{"id":"c","text":"Emergency 112"},{"id":"d","text":"POCSO e-Box"},{"id":"e","text":"Telling a friend instead"},{"id":"f","text":"Posting about it online"}],"bins":[{"id":"real","label":"A real reporting route","valence":"pos"},{"id":"not","label":"Not a reporting route","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"real","e":"not","f":"not"},"relearn":"1098, 1930, 112 and the e-Box are real routes; venting or posting online isn't reporting.","persona":"Vikram","source":"real route vs not"},
  {"id":"sa-1282","cat":"the-law-and-the-call","type":"sort","hook":"Sort: a reason the law gives to act, or an excuse to stay silent?","items":[{"id":"a","text":"The child is the victim and needs protection"},{"id":"b","text":"Reporting is obliged, not optional"},{"id":"c","text":"\"It would shame the family\""},{"id":"d","text":"\"I might be wrong, so I'll wait\""},{"id":"e","text":"Acting now can stop ongoing harm"},{"id":"f","text":"\"It's a private matter\""}],"bins":[{"id":"act","label":"Reason to act","valence":"pos"},{"id":"excuse","label":"An excuse to stay silent","valence":"neg"}],"key":{"a":"act","b":"act","c":"excuse","d":"excuse","e":"act","f":"excuse"},"relearn":"Protecting the victim, the duty to report and stopping harm are reasons; the rest are excuses.","persona":"any","source":"reason vs excuse"},
  {"id":"sa-1283","cat":"the-law-and-the-call","type":"sort","hook":"Sort: a verified POCSO basic, or going beyond what you know?","items":[{"id":"a","text":"An offence against an under-18 is a crime"},{"id":"b","text":"The child is always the victim"},{"id":"c","text":"\"The abuser gets exactly seven years\""},{"id":"d","text":"Reporting is obliged"},{"id":"e","text":"\"I can explain court procedure\""},{"id":"f","text":"Real concerns go to the authorities"}],"bins":[{"id":"verified","label":"A verified basic","valence":"pos"},{"id":"beyond","label":"Beyond what you know","valence":"uhoh"}],"key":{"a":"verified","b":"verified","c":"beyond","d":"verified","e":"beyond","f":"verified"},"relearn":"Stick to basics: it's a crime, child is victim, reporting obliged; leave sentences to pros.","persona":"Divya","source":"verified vs beyond"},
  {"id":"sa-1284","cat":"the-law-and-the-call","type":"sort","hook":"Sort: keeps a child safe, or works against the law's intent?","items":[{"id":"a","text":"Preserving messages as evidence"},{"id":"b","text":"Letting professionals question the child"},{"id":"c","text":"Deleting the chat to avoid fuss"},{"id":"d","text":"Reporting to cybercrime 1930"},{"id":"e","text":"Warning the abuser to delete everything"},{"id":"f","text":"Confronting the abuser, then dropping it"}],"bins":[{"id":"safe","label":"Keeps the child safe","valence":"pos"},{"id":"against","label":"Works against it","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"against","d":"safe","e":"against","f":"against"},"relearn":"Preserving evidence, pros questioning, and reporting to 1930 help; the rest don't.","persona":"Vikram","source":"safe vs against"},
  {"id":"sa-1285","cat":"the-law-and-the-call","type":"sort","hook":"Sort each route by how urgent it is (India).","items":[{"id":"a","text":"A child hurt this minute: 112"},{"id":"b","text":"A child needs help today: 1098"},{"id":"c","text":"An online offence: cybercrime 1930"},{"id":"d","text":"A formal complaint: police or e-Box"},{"id":"e","text":"\"I'll get to it next month\""},{"id":"f","text":"\"I'll wait and see if it repeats\""}],"bins":[{"id":"timely","label":"A timely route","valence":"pos"},{"id":"delay","label":"A harmful delay","valence":"neg"}],"key":{"a":"timely","b":"timely","c":"timely","d":"timely","e":"delay","f":"delay"},"relearn":"112, 1098, 1930 and police or e-Box are timely; 'next month' or 'wait' are delays.","persona":"any","source":"timely vs delay"},
  {"id":"sa-1286","cat":"the-law-and-the-call","type":"sort","hook":"Sort each role: a protected victim, or responsible for the offence?","items":[{"id":"a","text":"The child who was harmed"},{"id":"b","text":"A younger sibling who saw it"},{"id":"c","text":"The adult who did the harm"},{"id":"d","text":"A teen pressured into it"},{"id":"e","text":"The person who groomed them"},{"id":"f","text":"An adult who lured them online"}],"bins":[{"id":"victim","label":"A protected victim","valence":"pos"},{"id":"liable","label":"Responsible for it","valence":"neg"}],"key":{"a":"victim","b":"victim","c":"liable","d":"victim","e":"liable","f":"liable"},"relearn":"Every child involved is a protected victim; the adult who harms or grooms is responsible.","persona":"Kamla","source":"victim vs responsible"},
  {"id":"sa-1287","cat":"the-law-and-the-call","type":"sort","hook":"Sort each thought: frees you to report, or traps you in silence?","items":[{"id":"a","text":"\"I only need a concern, not proof\""},{"id":"b","text":"\"The shame belongs to the abuser\""},{"id":"c","text":"\"People will gossip about us\""},{"id":"d","text":"\"It's the child's safety first\""},{"id":"e","text":"\"What if the family is angry?\""},{"id":"f","text":"\"Maybe I'm overreacting\""}],"bins":[{"id":"free","label":"Frees you to report","valence":"pos"},{"id":"trap","label":"Traps you in silence","valence":"neg"}],"key":{"a":"free","b":"free","c":"trap","d":"free","e":"trap","f":"trap"},"relearn":"Concern-not-proof, the abuser's shame and the child's safety free you; the rest trap you.","persona":"Divya","source":"free vs trap"},
  {"id":"sa-1288","cat":"the-law-and-the-call","type":"sort","hook":"Sort each step of reporting: helps, or harms the case?","items":[{"id":"a","text":"Noting what the child said, in their words"},{"id":"b","text":"Keeping screenshots safe"},{"id":"c","text":"Asking the child to repeat it over and over"},{"id":"d","text":"Calling a route and asking what's next"},{"id":"e","text":"Coaching the child on what to say"},{"id":"f","text":"Posting the abuser's name publicly"}],"bins":[{"id":"helps","label":"Helps the case","valence":"pos"},{"id":"harms","label":"Harms the case","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"harms","d":"helps","e":"harms","f":"harms"},"relearn":"The child's own words, saved evidence and asking a route help; re-questioning or coaching harm it.","persona":"Vikram","source":"helps vs harms"},
  {"id":"sa-1289","cat":"the-law-and-the-call","type":"branch","hook":"A neighbour's child hints an uncle touched them. You believe them. What now?","options":[{"text":"Reassure the child, then call Childline 1098 or the police","consequence":"The right people step in to protect them.","outcome":"report","best":true},{"text":"Speak to the uncle first to hear his side","consequence":"Tipping off the abuser can silence the child."},{"text":"Wait to see if the child says more","consequence":"Waiting leaves the child exposed."}],"debrief":"Believe the child, then route it to 1098 or police; don't confront the suspect yourself.","relearn":"Believe and report to 1098 or police; never confront the suspect first.","persona":"Kamla","source":"believe then report"},
  {"id":"sa-1290","cat":"the-law-and-the-call","type":"branch","hook":"A relative has been sending your 13-year-old explicit messages.","options":[{"text":"Keep the messages and report to cybercrime 1930 and police","consequence":"Evidence is saved and the right line handles it.","outcome":"cyber","best":true},{"text":"Delete it all so your child isn't embarrassed","consequence":"Deleting destroys the evidence the case needs."},{"text":"Reply from the child's phone to trap them","consequence":"Posing as the child can put them at risk."}],"debrief":"For online abuse, keep evidence and report to cybercrime 1930 and police.","relearn":"Preserve the messages; report online abuse to cybercrime 1930 and police.","persona":"Vikram","source":"online to 1930"},
  {"id":"sa-1291","cat":"the-law-and-the-call","type":"branch","hook":"At a wedding you see something that frightens you about an adult and a child.","options":[{"text":"Keep the child close now, then report the concern after","consequence":"The child is safe and the concern still reaches help.","outcome":"protect","best":true},{"text":"Cause a scene and accuse the adult on the spot","consequence":"A public scene can frighten the child."},{"text":"Tell yourself it's a wedding and let it go","consequence":"Letting it go leaves no one watching out."}],"debrief":"Protect the child quietly, then report; no public confrontation needed.","relearn":"Keep the child safe now and report after; no public scene needed.","persona":"any","source":"protect then report"},
  {"id":"sa-1292","cat":"the-law-and-the-call","type":"branch","hook":"You're sure something is wrong but have no hard proof at all.","options":[{"text":"Call Childline 1098, describe it, and ask how to proceed","consequence":"You get expert guidance without needing proof.","outcome":"guidance","best":true},{"text":"Drop it until you can prove it beyond doubt","consequence":"Demanding proof can leave a child unprotected."},{"text":"Question the child in detail to build a case","consequence":"Interrogating the child distresses them."}],"debrief":"Take an unproven worry to Childline 1098; you report a concern, not a proven case.","relearn":"With no proof, call 1098 for guidance; you report a concern, not a case.","persona":"Divya","source":"no proof, call"},
  {"id":"sa-1293","cat":"the-law-and-the-call","type":"branch","hook":"A school staff member dismisses your worry about a child as 'nothing'.","options":[{"text":"Thank them, then report it yourself to 1098 or police","consequence":"The concern still reaches people who must act.","outcome":"escalate","best":true},{"text":"Accept their word; assume they'd know better","consequence":"One brush-off can leave real harm unaddressed."},{"text":"Argue until they agree, doing nothing else","consequence":"Arguing instead of reporting wastes time."}],"debrief":"If one adult dismisses your worry, report it yourself to 1098 or police anyway.","relearn":"If someone brushes it off, report it yourself to 1098 or police anyway.","persona":"any","source":"one brush-off"},
  {"id":"sa-1294","cat":"the-law-and-the-call","type":"branch","hook":"You see a child being hurt right now and freeze, unsure who to call.","options":[{"text":"Get the child to safety and call 112 straight away","consequence":"Immediate danger gets the fastest response.","outcome":"emergency","best":true},{"text":"Film it carefully before doing anything","consequence":"Filming first leaves the child in danger longer."},{"text":"Go home and look up the number later","consequence":"Delaying lets harm continue now."}],"debrief":"In immediate danger, get the child safe and call 112 first; details can follow.","relearn":"For a child in danger now, get them safe and call 112.","persona":"any","source":"danger, 112"},
  {"id":"sa-1295","cat":"the-law-and-the-call","type":"branch","hook":"Relatives beg you to 'keep it in the family' after a child discloses.","options":[{"text":"Say the child's safety comes first, and report it","consequence":"The child is protected and the duty honoured.","outcome":"child-first","best":true},{"text":"Agree to handle it privately to keep the peace","consequence":"Keeping it private leaves the child unprotected."},{"text":"Promise the child you'll never tell anyone","consequence":"Total secrecy can trap the child with no way out."}],"debrief":"Put the child's safety over family peace; never promise total secrecy.","relearn":"Choose the child's safety over family peace, and never promise total secrecy.","persona":"Kamla","source":"safety over secrecy"},
  {"id":"sa-1296","cat":"the-law-and-the-call","type":"branch","hook":"You found out months ago and feel it's too late to do anything now.","options":[{"text":"Report it now to 1098 or police; later beats never","consequence":"The child can still be protected and harm stopped.","outcome":"not-too-late","best":true},{"text":"Decide the moment has passed and stay quiet","consequence":"Staying quiet leaves the child at risk."},{"text":"Wait for the child to bring it up again","consequence":"Waiting can leave them unprotected."}],"debrief":"It's never too late to report; call 1098 or police even months later.","relearn":"Report even months later; it's never too late to protect a child.","persona":"Divya","source":"never too late"},
  {"id":"sa-1297","cat":"the-law-and-the-call","type":"branch","hook":"You're scared the abuser is powerful and could come after you.","options":[{"text":"Report through 1098 or police, who can advise on safety","consequence":"The child is protected and you get guidance.","outcome":"safely","best":true},{"text":"Stay silent because the person has influence","consequence":"Silence rewards power and exposes the child."},{"text":"Confront the powerful person to make them stop","consequence":"Confronting them alone can endanger you both."}],"debrief":"Even when the abuser is powerful, report to 1098 or police and ask about your safety.","relearn":"Report to 1098 or police even if the abuser is powerful.","persona":"any","source":"report despite power"},
  {"id":"sa-1298","cat":"the-law-and-the-call","type":"branch","hook":"Your teen confesses they sent a photo and a stranger is now threatening them.","options":[{"text":"Stay calm, say it's not their fault, report to 1930","consequence":"The child is reassured and it's routed right.","outcome":"sextortion","best":true},{"text":"Scold them for sending it in the first place","consequence":"Blame makes the child shut down."},{"text":"Tell them to just pay or block and say nothing","consequence":"Paying or hiding it lets the threats continue."}],"debrief":"Sextortion is never the child's fault; stay calm, keep evidence, report to 1930.","relearn":"For sextortion, reassure the child, keep evidence, report to cybercrime 1930.","persona":"Vikram","source":"sextortion to 1930"},
  {"id":"sa-1299","cat":"the-law-and-the-call","type":"branch","hook":"You want to report but worry you'll have to narrate everything to a stranger.","options":[{"text":"Call Childline 1098 first; they listen and guide you","consequence":"You get a gentle start without facing it alone.","outcome":"soft","best":true},{"text":"Put it off until you feel completely ready","consequence":"Waiting to feel ready delays the child's protection."},{"text":"Try to handle the whole thing alone","consequence":"Going it alone can overwhelm you and stall it."}],"debrief":"Start with Childline 1098 — they listen and guide; you don't report alone.","relearn":"Start with 1098; they guide you, so you needn't report it all alone.","persona":"Kamla","source":"start with 1098"},
  {"id":"sa-1300","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: under the law the child is always the victim, never to blame, and reporting is the protective thing to do. Sitting with that?","prompt":"What lands for you?","options":["The child is the victim","Reporting protects them","Never their fault"],"affirm":"Under the law the child is always the victim and never to blame, and reporting a concern is the protective thing to do.","relearn":"The child is always the victim, never to blame; reporting is protective.","persona":"any","source":"child is victim"},
  {"id":"sa-1301","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: you don't need certainty to report — a genuine concern is enough, and professionals take it from there. How does that sit?","prompt":"What feels true?","options":["Concern is enough","I needn't be sure","Pros take it from there"],"affirm":"You don't need to be certain to report; a genuine, good-faith concern is enough, and trained people assess it.","relearn":"A good-faith concern is enough; you needn't be certain, and pros assess it.","persona":"Divya","source":"concern is enough"},
  {"id":"sa-1302","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: the shame of abuse belongs to the abuser, never to your child or your family. Let that settle.","prompt":"Where does the shame belong?","options":["With the abuser","Never the child","Not my family's"],"affirm":"The shame of abuse belongs entirely to the abuser; it is never your child's burden, and protecting them is nothing to be ashamed of.","relearn":"The shame belongs to the abuser, never the child; protecting your child is right.","persona":"Kamla","source":"shame is the abuser's"},
  {"id":"sa-1303","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: knowing even a few routes — 1098, 1930, 112 — means you'd act, not freeze, if a child needed you. How does that feel?","prompt":"What comes up?","options":["I'd know who to call","I'd act, not freeze","Ready to help"],"affirm":"Knowing even a few routes means that if a child ever needs you, you can act calmly instead of freezing.","relearn":"Knowing the routes lets you act calmly, not freeze, if a child needs you.","persona":"Vikram","source":"ready not frozen"},
  {"id":"sa-1304","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: this teaches the basics, not legal advice — and routing a real worry to the authorities is the right move. Okay with that?","prompt":"What sits right?","options":["Basics, not advice","Route real worries","Authorities can help"],"affirm":"This is the basics, not legal advice; for a real concern, routing it to the authorities is exactly right.","relearn":"This teaches the basics, not legal advice; route real concerns to the authorities.","persona":"any","source":"basics not advice"},
  {"id":"sa-1305","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: a boy who is harmed is just as protected by the law as a girl. Sit with that for a moment.","prompt":"What do you notice?","options":["Boys are protected too","The law covers everyone","Same care, any child"],"affirm":"The law protects every child equally; a boy who is harmed is just as much a victim deserving belief and protection.","relearn":"The law protects every child equally; a harmed boy deserves the same care.","persona":"Priya","source":"boys protected too"},
  {"id":"sa-1306","cat":"the-law-and-the-call","type":"reflect","hook":"Lensy: deciding now that you'd report rather than hush it means a future child would have a real protector. How does that land?","prompt":"What's true for you?","options":["I'd report, not hush","A child would have me","Decided in advance"],"affirm":"Deciding in advance that you would report rather than hush things up means a child in your life has a real protector.","relearn":"Deciding now to report, not hush, means a child has a protector when it counts.","persona":"any","source":"decide in advance"},
  {"id":"sa-1307","cat":"the-law-and-the-call","type":"role-play","hook":"You're on the phone to Childline, nervous and unsure how to begin.","setup":"Open the call:","yourLine":[{"text":"\"Hello, I'm worried a child may be being harmed and want advice on what to do.\"","best":true},{"text":"\"Sorry to bother you, it's probably nothing, never mind.\""}],"relearn":"Open a report by stating your worry and asking for advice; that's what the line is for.","persona":"Kamla","source":"opening the call"},
  {"id":"sa-1308","cat":"the-law-and-the-call","type":"role-play","hook":"A relative insists you stay quiet 'for the family's sake'.","setup":"Hold the line:","yourLine":[{"text":"\"The child's safety comes first, so I'm going to report this.\"","best":true},{"text":"\"Fine, I suppose we can keep it between us for now.\""}],"relearn":"You can name the child's safety as the priority and report, even under family pressure.","persona":"Kamla","source":"hold the line"},
  {"id":"sa-1309","cat":"the-law-and-the-call","type":"role-play","hook":"Your teen is terrified after a stranger online threatened to leak a photo.","setup":"Say it to them:","yourLine":[{"text":"\"This is not your fault, I'm glad you told me, and we'll report it together.\"","best":true},{"text":"\"How could you send that? Now look what's happened.\""}],"relearn":"Telling a sextorted child it isn't their fault and you'll report together keeps them safe.","persona":"Vikram","source":"reassure then report"},
  {"id":"sa-1310","cat":"the-law-and-the-call","type":"role-play","hook":"You doubt yourself: 'maybe I'm overreacting, maybe I should wait.'","setup":"Answer your own doubt:","yourLine":[{"text":"\"A concern is enough to call about; I don't need proof to protect a child.\"","best":true},{"text":"\"I'll wait until I'm completely certain before I do anything.\""}],"relearn":"Reminding yourself a concern is enough — proof isn't required — helps you act.","persona":"Divya","source":"answer the doubt"},
  {"id":"sa-1311","cat":"the-law-and-the-call","type":"role-play","hook":"Someone says, 'He's respectable, surely the police needn't be involved.'","setup":"Reply:","yourLine":[{"text":"\"A crime against a child is a crime whoever did it; it still needs reporting.\"","best":true},{"text":"\"You're right, someone like him probably wouldn't really harm a child.\""}],"relearn":"A child's protection doesn't bend to an abuser's good reputation; report regardless.","persona":"any","source":"respectability isn't a pass"},
  {"id":"sa-1312","cat":"the-law-and-the-call","type":"role-play","hook":"Your child asks, 'Will I be in trouble for telling about what happened?'","setup":"Reassure them:","yourLine":[{"text":"\"You're not in any trouble; you did the right thing, and I'll keep you safe.\"","best":true},{"text":"\"Well, let's not tell anyone else and just see what happens.\""}],"relearn":"Telling a child they're not in trouble and you'll keep them safe lets them stay open.","persona":"Kamla","source":"not in trouble"},
  {"id":"sa-1313","cat":"the-law-and-the-call","type":"role-play","hook":"A friend wants to confront the suspected abuser with you tonight.","setup":"Steer it right:","yourLine":[{"text":"\"Let's not tip him off; we'll report it and let the professionals handle it.\"","best":true},{"text":"\"Okay, let's go and have it out with him ourselves right now.\""}],"relearn":"Reporting rather than confronting keeps evidence intact and the child safer.","persona":"Vikram","source":"report don't confront"},
  {"id":"sa-1314","cat":"the-law-and-the-call","type":"sort","hook":"Sort: a fact this game teaches, or something it leaves to the professionals?","items":[{"id":"a","text":"The child is the victim, never to blame"},{"id":"b","text":"Reporting a concern is obliged"},{"id":"c","text":"The exact charge to file"},{"id":"d","text":"The routes: 1098, 1930, 112"},{"id":"e","text":"How a trial will be run"},{"id":"f","text":"It's educational, not legal advice"}],"bins":[{"id":"teach","label":"This game teaches it","valence":"pos"},{"id":"pros","label":"Left to the professionals","valence":"uhoh"}],"key":{"a":"teach","b":"teach","c":"pros","d":"teach","e":"pros","f":"teach"},"relearn":"It teaches the victim, the duty and the routes; charges and trials are for the pros.","persona":"Divya","source":"teach vs leave to pros"},
  {"id":"sa-1315","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two lines that are myths, not law.","scene":[{"id":"a","text":"An under-18 cannot legally consent","trick":false},{"id":"b","text":"\"If the child agreed, it's not a crime\"","trick":true},{"id":"c","text":"The child is always the victim","trick":false},{"id":"d","text":"\"POCSO only protects girls\"","trick":true},{"id":"e","text":"Reporting a concern is obliged","trick":false}],"why":"'They agreed' and 'only girls' are myths; under-18s can't consent and the law protects every child.","relearn":"'They agreed' and 'only girls' are myths; a child can't consent and every child is protected.","persona":"Kamla","source":"spot the law myths"},
  {"id":"sa-1316","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two choices that leave a child at risk.","scene":[{"id":"a","text":"Calling Childline 1098 to report","trick":false},{"id":"b","text":"\"Keep it in the family, don't tell\"","trick":true},{"id":"c","text":"Believing and comforting the child","trick":false},{"id":"d","text":"\"Settle it quietly for some money\"","trick":true},{"id":"e","text":"Letting professionals investigate","trick":false}],"why":"'Keep it in the family' and 'settle for money' leave a child unprotected and the abuser free.","relearn":"Don't hush it or settle it privately; report, believe the child, and let pros investigate.","persona":"any","source":"spot the risky choices"},
  {"id":"sa-1317","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two routes that aren't real reporting routes.","scene":[{"id":"a","text":"Childline 1098","trick":false},{"id":"b","text":"Posting it on social media","trick":true},{"id":"c","text":"Cybercrime 1930","trick":false},{"id":"d","text":"Just warning the abuser off","trick":true},{"id":"e","text":"The police or POCSO e-Box","trick":false}],"why":"Posting online and warning the abuser aren't reporting; 1098, 1930 and the police or e-Box are.","relearn":"Use 1098, 1930 or the police and e-Box; posting online or warning the abuser isn't reporting.","persona":"Vikram","source":"spot the non-routes"},
  {"id":"sa-1318","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two responses that wrongly put blame on the child.","scene":[{"id":"a","text":"\"It's not your fault, I'm glad you told me\"","trick":false},{"id":"b","text":"\"Why did you let it happen?\"","trick":true},{"id":"c","text":"\"You're not in any trouble\"","trick":false},{"id":"d","text":"\"You should have known better\"","trick":true},{"id":"e","text":"\"I'll keep you safe\"","trick":false}],"why":"'Why did you let it' and 'should have known better' blame the child; the child is never to blame.","relearn":"Never ask why a child 'let it' happen; the child is the victim, never to blame.","persona":"any","source":"spot the blame"},
  {"id":"sa-1319","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two moves that would harm a future case.","scene":[{"id":"a","text":"Noting the child's words as they said them","trick":false},{"id":"b","text":"Deleting the chat to avoid fuss","trick":true},{"id":"c","text":"Keeping screenshots safe","trick":false},{"id":"d","text":"Coaching the child on what to say","trick":true},{"id":"e","text":"Calling a route to ask what's next","trick":false}],"why":"Deleting the chat and coaching the child both damage the case; preserve evidence and the child's own words.","relearn":"Don't delete evidence or coach the child; keep proof and their own words, and ask a route.","persona":"Vikram","source":"spot case-harming moves"},
  {"id":"sa-1320","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two beliefs that wrongly stop a parent reporting.","scene":[{"id":"a","text":"\"A concern is enough; I needn't have proof\"","trick":false},{"id":"b","text":"\"He's respectable, so it can't be true\"","trick":true},{"id":"c","text":"\"The shame is the abuser's, not ours\"","trick":false},{"id":"d","text":"\"It's private, the law shouldn't come in\"","trick":true},{"id":"e","text":"\"The child's safety comes first\"","trick":false}],"why":"'He's respectable' and 'it's private' wrongly block reporting; respectability isn't safety and abuse isn't private.","relearn":"Respectability isn't safety and abuse isn't private; report the concern regardless.","persona":"any","source":"spot the blocking beliefs"},
  {"id":"sa-1321","cat":"the-law-and-the-call","type":"spot","hook":"Spot the two online responses that fail a sextorted child.","scene":[{"id":"a","text":"\"This isn't your fault\"","trick":false},{"id":"b","text":"\"How could you send that?\"","trick":true},{"id":"c","text":"Keeping the messages as evidence","trick":false},{"id":"d","text":"Telling them to just pay and stay quiet","trick":true},{"id":"e","text":"Reporting to cybercrime 1930","trick":false}],"why":"Blaming the child and telling them to pay quietly fail them; reassure, keep evidence, and report to 1930.","relearn":"Don't blame a sextorted child or tell them to pay; reassure, keep evidence, report to 1930.","persona":"Vikram","source":"spot the online fails"},
  {"id":"sa-1350","cat":"tools-and-respond","type":"branch","hook":"Your daughter mentions an uncle's 'special game' and goes quiet. What's your first move?","options":[{"text":"Stay calm, say you believe her, and let her talk at her own pace","consequence":"She feels safe to tell more, and you can act to protect her.","outcome":"safe","best":true},{"text":"Fire off questions to get every detail right now","consequence":"Interrogating her can make her shut down."}],"debrief":"The disclosure tool is the sequence: believe, stay calm, no blame, don't interrogate, then act.","relearn":"On a disclosure, run the steps: believe, stay calm, no blame, let her talk at her pace, then act.","persona":"Kamla","source":"first move"},
  {"id":"sa-1351","cat":"tools-and-respond","type":"branch","hook":"Your son has seemed withdrawn for two weeks since a relative started visiting.","options":[{"text":"Sit with him warmly and gently ask how he's been feeling lately","consequence":"An open check-in lets him share if something is wrong.","outcome":"open","best":true},{"text":"Wait and hope it passes on its own","consequence":"Ignoring a clear change leaves a struggling child alone with it."}],"debrief":"For a withdrawn or changed child, the tool is a gentle, open check-in, not waiting it out.","relearn":"A changed or withdrawn child is a signal to check in gently and openly, not to wait it out or interrogate.","persona":"Vikram","source":"the check-in"},
  {"id":"sa-1352","cat":"tools-and-respond","type":"branch","hook":"A child at the tuition centre quietly tells you the tutor touches her oddly.","options":[{"text":"Believe her, keep her away from him, and call Childline 1098 to report","consequence":"You protect her and route it to people who can act.","outcome":"reported","best":true},{"text":"Have a quiet word with the tutor and let it go","consequence":"Handling it privately leaves the child at risk."}],"debrief":"On a disclosure, the tool is to believe, protect and report via Childline 1098, never handle it quietly.","relearn":"Believe a disclosing child, keep her safe, and report through Childline 1098, never settle it privately.","persona":"any","source":"tuition centre"},
  {"id":"sa-1353","cat":"tools-and-respond","type":"branch","hook":"Your child shows you a stranger's late-night messages asking for photos.","options":[{"text":"Stay calm, save the messages as evidence, and report to cybercrime 1930","consequence":"Keeping evidence and reporting gets it stopped.","outcome":"reported","best":true},{"text":"Snatch the phone and delete everything in a panic","consequence":"Deleting destroys the evidence a report needs."}],"debrief":"For an online threat: stay calm, keep evidence, and report to cybercrime 1930, never blame the child.","relearn":"Online danger: stay calm, keep the evidence, report to cybercrime 1930; a tricked child is a victim, not at fault.","persona":"Vikram","source":"messages"},
  {"id":"sa-1354","cat":"tools-and-respond","type":"branch","hook":"Relatives want to 'keep the family's name clean' after your nephew disclosed.","options":[{"text":"Insist the child's safety comes first and that you'll report it","consequence":"You protect the child even when the family pushes back.","outcome":"protected","best":true},{"text":"Agree to stay silent to keep peace at home","consequence":"Silence for the family's image leaves the child in danger."}],"debrief":"The first priority is always the child's safety, over the family's image or comfort.","relearn":"The child's safety comes first, over the family's image; reporting is protective, not a betrayal of the family.","persona":"any","source":"family's name"},
  {"id":"sa-1355","cat":"tools-and-respond","type":"branch","hook":"You keep putting off learning the signs and saving the numbers, the topic scares you.","options":[{"text":"Save Childline 1098 and cybercrime 1930 today and read the signs once","consequence":"A few minutes now means you're ready if it ever counts.","outcome":"ready","best":true},{"text":"Tell yourself you'll handle it on the day","consequence":"Crisis is the worst time to start learning the steps."}],"debrief":"Prepare despite the fear: an informed, ready parent is a child's safety when it counts.","relearn":"Prepare despite the fear; save the numbers and learn the signs now, as crisis is the hardest time to learn.","persona":"Kamla","source":"put off"},
  {"id":"sa-1356","cat":"tools-and-respond","type":"branch","hook":"Your child went silent and clingy after a sleepover at a friend's house.","options":[{"text":"Cuddle up and gently ask, with no pressure, how the sleepover felt","consequence":"A warm, open check-in lets a worry surface safely.","outcome":"open","best":true},{"text":"Cross-examine her about every hour she was away","consequence":"Interrogation frightens a child into silence."}],"debrief":"A sudden change is a signal to check in gently, take it seriously, and keep the door open.","relearn":"Take a sudden change in a child seriously; a gentle, open check-in is the tool, never interrogation or dismissal.","persona":"Divya","source":"after the sleepover"},
  {"id":"sa-1357","cat":"tools-and-respond","type":"branch","hook":"Mid-disclosure, your child stops and says 'promise you won't tell anyone'.","options":[{"text":"Say you'll keep her safe, but can't promise total secrecy","consequence":"Honest reassurance keeps trust while letting you act.","outcome":"honest","best":true},{"text":"Promise you'll never tell a single soul","consequence":"A secrecy promise you must break later breaks her trust."}],"debrief":"Never promise total secrecy; say what you can: 'I believe you, it's not your fault, I'll keep you safe.'","relearn":"Never promise total secrecy; reassure 'I believe you, it's not your fault, I'll keep you safe' while free to act.","persona":"Kamla","source":"promise secrecy"},
  {"id":"sa-1358","cat":"tools-and-respond","type":"match","hook":"Match each toolkit piece to what it actually does.","pairs":[{"left":"The signs checklist","right":"Helps you notice changes, calmly"},{"left":"The response steps","right":"Believe, stay calm, no blame, act"},{"left":"The helpline card","right":"Tells you exactly who to call"},{"left":"The open door","right":"Lets a child come to you at all"},{"left":"Calm preparation","right":"Means you're ready before the moment"}],"relearn":"The toolkit is the signs checklist, the response steps, the helpline card, an open door, and calm preparation.","persona":"any","source":"toolkit pieces"},
  {"id":"sa-1359","cat":"tools-and-respond","type":"match","hook":"Match each situation to the right route to call.","pairs":[{"left":"A child says someone hurt them","right":"Childline 1098"},{"left":"A stranger is grooming them online","right":"Cybercrime 1930"},{"left":"A child is in danger right now","right":"Emergency 112"},{"left":"A withdrawn, changed child","right":"A gentle, open check-in"},{"left":"You feel too scared to act","right":"Lean on the saved numbers"}],"relearn":"Each situation has its route: 1098 for a disclosure, 1930 for online, 112 in immediate danger, a check-in for change.","persona":"Vikram","source":"situation to route"},
  {"id":"sa-1360","cat":"tools-and-respond","type":"match","hook":"Match each disclosure-response step to why it matters.","pairs":[{"left":"Believe","right":"Children very rarely lie about this"},{"left":"Stay calm","right":"Horror can make a child shut down"},{"left":"No blame","right":"The fault is entirely the abuser's"},{"left":"Don't interrogate","right":"Detailed questioning is for professionals"},{"left":"Then act","right":"Protecting comes before the family's image"}],"relearn":"Believe, stay calm, no blame, don't interrogate, then act, each step protects the child in a different way.","persona":"any","source":"step to reason"},
  {"id":"sa-1361","cat":"tools-and-respond","type":"match","hook":"Match each parent worry to the steady, toolkit answer.","pairs":[{"left":"'What if I freeze?'","right":"Practise the four steps in advance"},{"left":"'What if I don't believe it?'","right":"Children rarely lie; start by believing"},{"left":"'What if I say the wrong thing?'","right":"'I believe you, it's not your fault'"},{"left":"'What if I make it worse?'","right":"Stay calm; don't interrogate"},{"left":"'What if I forget who to call?'","right":"Keep the helpline card saved"}],"relearn":"Practising the steps and saving the card turns 'what if I freeze' into a calm, ready response when it counts.","persona":"Kamla","source":"worry to answer"},
  {"id":"sa-1362","cat":"tools-and-respond","type":"match","hook":"Match each phrase to whether it's a safe-adult tool or a trap to drop.","pairs":[{"left":"'I'm glad you told me'","right":"A tool: makes telling safe"},{"left":"'Are you sure that happened?'","right":"A trap: doubt silences a child"},{"left":"'None of this is your fault'","right":"A tool: lifts the blame off"},{"left":"'Don't tell anyone about this'","right":"A trap: secrecy hides the harm"},{"left":"'I'll keep you safe'","right":"A tool: honest, protective promise"}],"relearn":"'I believe you', 'not your fault', 'I'll keep you safe' are tools; doubt and secrecy are traps to drop.","persona":"any","source":"tool or trap"},
  {"id":"sa-1363","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"I'll just figure out what to do if the awful moment ever comes.\"","myth":{"un":"I'll just figure out what to do if the awful moment ever comes.","re":"Learn the signs and the response steps and save the numbers now; a crisis is the hardest time to start learning.","why":"An informed, ready parent is a child's safety when it counts."},"relearn":"Don't wait for the crisis to learn; an informed, ready parent is a child's safety when it counts most.","persona":"Kamla","source":"figure it out later"},
  {"id":"sa-1364","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"A good parent reacts with shock and fury when a child reveals abuse.\"","myth":{"un":"A good parent reacts with shock and fury when a child reveals abuse.","re":"Visible horror or rage can make a child shut down or feel blamed; staying calm is what keeps them talking and safe.","why":"Calm is a tool that protects the child, not a sign you don't care."},"relearn":"On a disclosure, calm protects; visible horror or rage can make a child shut down, so steadiness is the safe-adult tool.","persona":"any","source":"shock and fury"},
  {"id":"sa-1365","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"If I keep asking enough questions, I'll get the whole story straight myself.\"","myth":{"un":"If I keep asking enough questions, I'll get the whole story straight myself.","re":"Let the child talk at their own pace and leave detailed questioning to professionals; your job is to listen and protect.","why":"Interrogation can distress a child and muddle the account."},"relearn":"Don't interrogate; let the child talk at their own pace and leave detailed questioning to trained professionals.","persona":"any","source":"the whole story"},
  {"id":"sa-1366","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"Knowing one helpline is plenty; the rest I'll never need.\"","myth":{"un":"Knowing one helpline is plenty; the rest I'll never need.","re":"Different situations need different routes: Childline 1098, cybercrime 1930 for online, and emergency 112 in danger.","why":"The right route saves time when a child's safety is on the line."},"relearn":"Keep the whole helpline card: 1098 for a disclosure, 1930 for online harm, and 112 when a child is in danger now.","persona":"Vikram","source":"one helpline"},
  {"id":"sa-1367","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"If I get the toolkit ready, I'm basically inviting trouble to my home.\"","myth":{"un":"If I get the toolkit ready, I'm basically inviting trouble to my home.","re":"Being prepared doesn't cause harm; it just means you can notice and respond right if harm ever reaches your child.","why":"Readiness is protection, the same as knowing first aid you hope never to use."},"relearn":"Preparing doesn't invite harm; it's like first aid you hope never to use, so you can respond right if it's ever needed.","persona":"any","source":"inviting trouble"},
  {"id":"sa-1368","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"Once it's reported, the kindest thing is to never speak of it again.\"","myth":{"un":"Once it's reported, the kindest thing is to never speak of it again.","re":"A child heals better when you affirm their bravery, their blamelessness, and that your door stays open, than in silence.","why":"Silence can feel like shame; steady, open support helps healing."},"relearn":"After reporting, affirm a child's bravery and blamelessness and keep the door open; silence can feel like shame.","persona":"Kamla","source":"never speak again"},
  {"id":"sa-1369","cat":"tools-and-respond","type":"strike-rewrite","hook":"\"My child seems fine, so I can put the whole safe-adult toolkit away.\"","myth":{"un":"My child seems fine, so I can put the whole safe-adult toolkit away.","re":"Stay the tellable, alert, ready adult anyway; the open door and the saved numbers matter at every age, online and off.","why":"The safe adult stays the safe adult, not just during a crisis."},"relearn":"Stay tellable, alert and ready even when all seems fine; the open door and the toolkit matter at every age.","persona":"any","source":"seems fine"},
  {"id":"sa-1370","cat":"tools-and-respond","type":"reflect","hook":"Lensy: the toolkit is just three things, a way to notice, a way to respond, and a way to get help. Sit with that.","prompt":"What do you think?","options":["I can hold three things","Notice, respond, get help","I'm becoming ready"],"affirm":"Notice the signs, respond with the steps, get help with the card, that's the whole safe-adult toolkit you can carry.","relearn":"The toolkit is three carryable things: a way to notice, a way to respond, and a way to get help.","persona":"any","source":"three things"},
  {"id":"sa-1371","cat":"tools-and-respond","type":"reflect","hook":"Lensy: the most powerful tool you own is just being the adult a child is sure they can come to. Feel its weight?","prompt":"What's your take?","options":["Feel its weight","I'll be that adult","The door stays open"],"affirm":"Every other tool only works because a child believes they can come to you; that open door is your strongest one.","relearn":"The open, no-blame door is the tool every other one depends on; being reachable is your strongest protection.","persona":"Kamla","source":"strongest tool"},
  {"id":"sa-1372","cat":"tools-and-respond","type":"reflect","hook":"Lensy: 'I believe you, it's not your fault, I'm glad you told me, I'll keep you safe.' Let those words settle in.","prompt":"How do they land?","options":["Let them settle","I can say these","These keep a child safe"],"affirm":"Those four lines are the heart of the response tool; said calmly, they tell a child they're safe and not to blame.","relearn":"The response script is 'I believe you, it's not your fault, I'm glad you told me, I'll keep you safe.'","persona":"any","source":"settle the words"},
  {"id":"sa-1373","cat":"tools-and-respond","type":"reflect","hook":"Lensy: being ready isn't about fear, it's about love that prepared itself. Notice the difference?","prompt":"What do you feel?","options":["Notice the difference","Love that prepared","Ready, not afraid"],"affirm":"Learning the signs and saving the numbers isn't dread; it's love getting itself ready so it can act if it must.","relearn":"Readiness isn't fear; it's love that prepared itself, so you can act calmly if your child ever needs you.","persona":"Kamla","source":"love prepared"},
  {"id":"sa-1374","cat":"tools-and-respond","type":"reflect","hook":"Lensy: a withdrawn child doesn't need an interrogation, just a parent who sits down and gently asks. Picture it.","prompt":"What comes up?","options":["Picture it","A gentle sitting-down","I can just ask"],"affirm":"For a changed or quiet child, the tool is simply to sit close and ask gently how they are, no pressure at all.","relearn":"The check-in tool is just sitting close and asking gently how a withdrawn child is, with no pressure.","persona":"Divya","source":"sit and ask"},
  {"id":"sa-1375","cat":"tools-and-respond","type":"reflect","hook":"Lensy: when you don't sit on a worry but pick up the phone, that single act can change a child's whole story. Sit with it.","prompt":"What's your take?","options":["Sit with it","I won't sit on it","One call can change everything"],"affirm":"When a concern is real, using the helpline card instead of sitting on it is the act that can change a child's path.","relearn":"When you have a real concern, the tool is to use the helpline card, not to sit on it and hope it passes.","persona":"any","source":"pick up the phone"},
  {"id":"sa-1376","cat":"tools-and-respond","type":"reflect","hook":"Lensy: you carry the signs, the steps, and the numbers now, the whole kit fits in a calm, ready heart. Feel that?","prompt":"How does it sit?","options":["Feel that","The kit is mine","Calm and ready"],"affirm":"The signs, the response steps, and the helpline card together make you the ready, steady adult a child can count on.","relearn":"You carry the whole kit now, the signs, the steps, and the numbers, in one calm, ready, reachable heart.","persona":"any","source":"carry the kit"},
  {"id":"sa-1377","cat":"tools-and-respond","type":"reflect","hook":"Lensy: a child who came through something hard doesn't need it erased, just your steady reminder that they were brave. Feel it?","prompt":"What rises?","options":["Feel it","They were brave","My door stays open"],"affirm":"Affirming a child's bravery and blamelessness, and that your door stays open, helps healing far more than silence.","relearn":"After hard things, affirm a child's bravery and blamelessness and keep your door open; that supports healing.","persona":"Kamla","source":"they were brave"},
  {"id":"sa-1378","cat":"tools-and-respond","type":"role-play","hook":"Your child whispers that a coaching teacher made her uncomfortable. You want your very first words to be right.","setup":"Your first words:","yourLine":[{"text":"\"Thank you for telling me. I believe you, none of it is your fault, and I'm going to keep you safe.\"","best":true},{"text":"\"Are you certain? He's such a respected teacher, you may have misread it.\""}],"relearn":"Open a disclosure with belief and reassurance: 'I believe you, it's not your fault, I'll keep you safe.'","persona":"Kamla","source":"first words"},
  {"id":"sa-1379","cat":"tools-and-respond","type":"role-play","hook":"A neighbour's child quietly tells you an adult at home hurts him. You want to respond as the safe adult.","setup":"You say:","yourLine":[{"text":"\"I believe you and I'm glad you told me. You're not in trouble. Let's get you help, I'll call Childline 1098.\"","best":true},{"text":"\"That's a family matter, I really shouldn't get involved in it.\""}],"relearn":"Believe a child who tells you, reassure them they're not in trouble, and route to help via Childline 1098.","persona":"any","source":"neighbour's child"},
  {"id":"sa-1380","cat":"tools-and-respond","type":"role-play","hook":"Your spouse wants to confront the suspected relative directly and loudly. You want to steer to the real tool.","setup":"You steady them:","yourLine":[{"text":"\"Let's not tip him off or scare our child. We keep her close, stay calm, and call Childline 1098 to report.\"","best":true},{"text":"\"Yes, let's storm over and have it out with him right now.\""}],"relearn":"Don't confront in a rage; keep the child close and calm and report through Childline 1098, the professionals act.","persona":"Vikram","source":"steady the spouse"},
  {"id":"sa-1381","cat":"tools-and-respond","type":"role-play","hook":"Your child is talking through what happened, slowly and out of order. You want to use the listening tool.","setup":"You respond:","yourLine":[{"text":"\"Take all the time you need. I'm here and I'm listening, you don't have to say it all at once.\"","best":true},{"text":"\"Wait, start from the beginning and tell me exactly what happened, step by step.\""}],"relearn":"Let a child talk at their own pace; listen without interrogating, and leave detailed questioning to professionals.","persona":"any","source":"out of order"},
  {"id":"sa-1382","cat":"tools-and-respond","type":"role-play","hook":"Your scared child asks you to promise you'll never tell anyone. You want to be honest and reassuring.","setup":"You answer:","yourLine":[{"text":"\"I'll always keep you safe, and because you matter so much, I can't promise to keep this just between us.\"","best":true},{"text":"\"I promise, this stays a secret between only us two, forever.\""}],"relearn":"Never promise total secrecy; reassure that you'll keep the child safe while staying honest that you may need to act.","persona":"Kamla","source":"never tell anyone"},
  {"id":"sa-1383","cat":"tools-and-respond","type":"role-play","hook":"A friend whose child just disclosed is frozen and panicking on the phone. You want to hand them the steps.","setup":"You guide them:","yourLine":[{"text":"\"Breathe. Tell her you believe her and it's not her fault, keep her safe, and let's call Childline 1098 together.\"","best":true},{"text":"\"Just don't react, pretend it's nothing, and maybe it'll all blow over.\""}],"relearn":"Guide a panicking parent through the steps: believe, no blame, keep safe, and call Childline 1098 together.","persona":"Divya","source":"frozen friend"},
  {"id":"sa-1384","cat":"tools-and-respond","type":"role-play","hook":"Your child admits a stranger online tricked them into sending a photo and is now threatening them. You respond.","setup":"You say:","yourLine":[{"text":"\"You're not in trouble, this is on him, not you. We'll save the messages and report to cybercrime 1930 together.\"","best":true},{"text":"\"Why on earth would you send that? You've made a real mess for yourself.\""}],"relearn":"A sextorted child is a victim, not at fault; reassure, keep evidence, and report to cybercrime 1930 together.","persona":"Vikram","source":"online threat"},
  {"id":"sa-1385","cat":"tools-and-respond","type":"role-play","hook":"Relatives in the room urge you to hush up what your child just shared. You want to hold the line out loud.","setup":"You tell them:","yourLine":[{"text":"\"My child's safety comes before our comfort. We believe her, we protect her, and we will report this.\"","best":true},{"text":"\"You're right, let's keep it in the family and not make a fuss about it.\""}],"relearn":"The child's safety comes before the family's comfort; believe, protect, and report rather than hush it up.","persona":"any","source":"hold the line aloud"},
  {"id":"sa-1386","cat":"tools-and-respond","type":"role-play","hook":"You notice your withdrawn child needs an opening, not a grilling. You sit down beside them.","setup":"You open gently:","yourLine":[{"text":"\"I've noticed you seem a bit down lately. I'm here whenever you want to talk, about anything at all.\"","best":true},{"text":"\"What's wrong with you these days? Out with it, I don't have all evening.\""}],"relearn":"Open a check-in gently: name the change, offer your presence, and leave the door open with no pressure.","persona":"Divya","source":"gentle opening"},
  {"id":"sa-1387","cat":"tools-and-respond","type":"role-play","hook":"Your child comes through a hard ordeal with your support. You want your closing words to help them heal.","setup":"You tell them:","yourLine":[{"text":"\"You were so brave to tell me. None of it was ever your fault, and I'm always here, for anything.\"","best":true},{"text":"\"Let's just forget it ever happened and never bring it up again.\""}],"relearn":"Affirm a child's bravery and blamelessness and your permanent open door; that supports healing far more than silence.","persona":"Kamla","source":"closing words"},
  {"id":"sa-1388","cat":"tools-and-respond","type":"role-play","hook":"Your teenager tests you: 'If something bad ever happened, would you actually freak out?' You want them to know the answer.","setup":"You answer honestly:","yourLine":[{"text":"\"No. I'd stay calm, I'd believe you, and I'd help you, always. You can bring me anything.\"","best":true},{"text":"\"Honestly? I'd probably lose it completely and we'd both fall apart.\""}],"relearn":"Tell a child in advance you'd stay calm, believe them, and help; that promise makes you the adult they can tell.","persona":"any","source":"would you freak out"},
  {"id":"sa-1389","cat":"tools-and-respond","type":"role-play","hook":"A worried parent says they don't know who to even call. You want to hand them the helpline card clearly.","setup":"You tell them:","yourLine":[{"text":"\"Save these now: Childline 1098 for a child, cybercrime 1930 for anything online, and 112 if they're in danger.\"","best":true},{"text":"\"I'm not sure, just search online if something ever actually happens.\""}],"relearn":"The helpline card is Childline 1098, cybercrime 1930 for online, and 112 in immediate danger, save them now.","persona":"Vikram","source":"who to call"},
  {"id":"sa-1390","cat":"tools-and-respond","type":"role-play","hook":"Your child quietly says a domestic helper has been hurting them while you're at work. You respond as the safe adult.","setup":"You say:","yourLine":[{"text":"\"I believe you and I'm so glad you told me. You're not in trouble at all, and I will keep you safe now.\"","best":true},{"text":"\"But they've worked for us for years, are you sure you understood it right?\""}],"relearn":"Believe a child even about a trusted, long-known adult; respectability isn't safety, reassure and protect them.","persona":"Kamla","source":"the helper"},
  {"id":"sa-1391","cat":"tools-and-respond","type":"role-play","hook":"You catch yourself about to react with horror as your child speaks. You want to land your tone right instead.","setup":"You steady yourself and say:","yourLine":[{"text":"\"I'm right here with you and I'm not upset with you at all. Take your time, I'm listening.\"","best":true},{"text":"\"Oh my God, this is horrifying! How could this happen to you?!\""}],"relearn":"Catch the horror; keep your tone calm and steady so the child keeps talking and never feels they caused your distress.","persona":"any","source":"catch the horror"},
  {"id":"sa-1392","cat":"tools-and-respond","type":"role-play","hook":"You're walking your nervous co-parent through what to do the moment a child discloses. You give them the sequence.","setup":"You coach them:","yourLine":[{"text":"\"Believe first, stay calm, say it's not their fault, don't interrogate, then we act and call for help.\"","best":true},{"text":"\"Just grill them for every detail first, we'll worry about staying calm afterwards.\""}],"relearn":"The response sequence is: believe, stay calm, no blame, don't interrogate, then act and call for help.","persona":"Vikram","source":"the sequence"},
  {"id":"sa-1393","cat":"tools-and-respond","type":"sort","hook":"Sort each move: a safe-adult tool, or the wrong response to drop?","items":[{"id":"a","text":"Saying 'I believe you, it's not your fault'"},{"id":"b","text":"Demanding every detail at once"},{"id":"c","text":"A gentle, open check-in"},{"id":"d","text":"Reacting with visible horror"},{"id":"e","text":"Saving the helpline numbers"},{"id":"f","text":"Hushing it up for the family"}],"bins":[{"id":"tool","label":"Safe-adult tool","valence":"pos"},{"id":"drop","label":"Drop it","valence":"neg"}],"key":{"a":"tool","b":"drop","c":"tool","d":"drop","e":"tool","f":"drop"},"relearn":"Belief, a gentle check-in and saved numbers are tools; interrogating, showing horror and hushing up are to drop.","persona":"any","source":"tool or drop"},
  {"id":"sa-1394","cat":"tools-and-respond","type":"sort","hook":"Sort each line by the response step it belongs to.","items":[{"id":"a","text":"'I believe you'"},{"id":"b","text":"'None of this is your fault'"},{"id":"c","text":"'I'm staying calm, I'm here'"},{"id":"d","text":"'Let's call Childline 1098'"},{"id":"e","text":"'You can stay at your own pace'"},{"id":"f","text":"'I'm glad you told me'"}],"bins":[{"id":"believe","label":"Believe & welcome","valence":"pos"},{"id":"calm","label":"Calm & no blame","valence":"tell"},{"id":"act","label":"Act & get help","valence":"uhoh"}],"key":{"a":"believe","f":"believe","b":"calm","c":"calm","e":"calm","d":"act"},"relearn":"The steps group as believe-and-welcome, stay-calm-and-no-blame, and act-and-get-help via Childline 1098.","persona":"any","source":"line to step"},
  {"id":"sa-1395","cat":"tools-and-respond","type":"sort","hook":"Sort each concern by the right route to reach for.","items":[{"id":"a","text":"A child says a relative hurt them"},{"id":"b","text":"An online stranger is grooming them"},{"id":"c","text":"A child is in danger right this minute"},{"id":"d","text":"Threatening messages demanding photos"},{"id":"e","text":"A disclosure of abuse by a teacher"},{"id":"f","text":"A child cornered and at risk now"}],"bins":[{"id":"childline","label":"Childline 1098","valence":"tell"},{"id":"cyber","label":"Cybercrime 1930","valence":"uhoh"},{"id":"emergency","label":"Emergency 112","valence":"neg"}],"key":{"a":"childline","e":"childline","b":"cyber","d":"cyber","c":"emergency","f":"emergency"},"relearn":"Route by concern: Childline 1098 for a disclosure, cybercrime 1930 for online, emergency 112 for immediate danger.","persona":"Vikram","source":"concern to route"},
  {"id":"sa-1396","cat":"tools-and-respond","type":"sort","hook":"Sort each thing by where it belongs in your readiness plan.","items":[{"id":"a","text":"Childline 1098 saved in your phone"},{"id":"b","text":"Knowing sudden fear is a sign"},{"id":"c","text":"'Believe, calm, no blame, act'"},{"id":"d","text":"Cybercrime 1930 saved too"},{"id":"e","text":"Noticing new withdrawal"},{"id":"f","text":"Letting a child talk at their pace"}],"bins":[{"id":"notice","label":"Ways to notice","valence":"pos"},{"id":"respond","label":"Ways to respond","valence":"tell"},{"id":"help","label":"Ways to get help","valence":"uhoh"}],"key":{"b":"notice","e":"notice","c":"respond","f":"respond","a":"help","d":"help"},"relearn":"Your plan sorts into ways to notice signs, ways to respond with the steps, and ways to get help with the card.","persona":"any","source":"readiness plan"},
  {"id":"sa-1397","cat":"tools-and-respond","type":"sort","hook":"Sort each parent thought: a steady, ready mindset, or one to reset?","items":[{"id":"a","text":"'I'll prepare now, calmly'"},{"id":"b","text":"'It could never happen to us'"},{"id":"c","text":"'My child can tell me anything'"},{"id":"d","text":"'I'd rather not think about it'"},{"id":"e","text":"'I know who I'd call'"},{"id":"f","text":"'I'd handle it somehow on the day'"}],"bins":[{"id":"ready","label":"Ready mindset","valence":"pos"},{"id":"reset","label":"Reset this","valence":"neg"}],"key":{"a":"ready","c":"ready","e":"ready","b":"reset","d":"reset","f":"reset"},"relearn":"A ready mindset prepares calmly, stays tellable, and knows who to call; denial and avoidance need a reset.","persona":"Kamla","source":"mindset to reset"},
  {"id":"sa-1398","cat":"tools-and-respond","type":"sort","hook":"Sort each priority for when a child may be at risk: first, or never first.","items":[{"id":"a","text":"The child's immediate safety"},{"id":"b","text":"The family's reputation"},{"id":"c","text":"Getting the child the right help"},{"id":"d","text":"Avoiding awkwardness with relatives"},{"id":"e","text":"Believing and reassuring the child"},{"id":"f","text":"Protecting an adult's standing"}],"bins":[{"id":"first","label":"Comes first","valence":"pos"},{"id":"never","label":"Never first","valence":"neg"}],"key":{"a":"first","c":"first","e":"first","b":"never","d":"never","f":"never"},"relearn":"The child's safety, getting help, and believing them come first; reputation and awkwardness never come first.","persona":"any","source":"comes first"},
  {"id":"sa-1399","cat":"tools-and-respond","type":"sort","hook":"Sort each habit: build it into your toolkit, or unlearn it?","items":[{"id":"a","text":"Saving the helpline numbers today"},{"id":"b","text":"Promising a child total secrecy"},{"id":"c","text":"Checking in gently on changes"},{"id":"d","text":"Questioning whether a child made it up"},{"id":"e","text":"Naming feelings without panic"},{"id":"f","text":"Waiting for elders to decide"}],"bins":[{"id":"build","label":"Build it in","valence":"pos"},{"id":"unlearn","label":"Unlearn it","valence":"neg"}],"key":{"a":"build","c":"build","e":"build","b":"unlearn","d":"unlearn","f":"unlearn"},"relearn":"Build in saved numbers, gentle check-ins and calm; unlearn secrecy promises, doubting a child, and waiting on elders.","persona":"any","source":"build or unlearn"},
  {"id":"sa-1400","cat":"tools-and-respond","type":"spot","hook":"Spot the two responses to a disclosure that you should NOT use.","scene":[{"id":"a","text":"'I believe you and I'm glad you told me'","trick":false},{"id":"b","text":"'Are you sure you're not exaggerating?'","trick":true},{"id":"c","text":"Staying calm and letting them talk","trick":false},{"id":"d","text":"Reacting with loud horror and panic","trick":true},{"id":"e","text":"'None of this is your fault'","trick":false}],"why":"Doubting the child and reacting with loud horror are the wrong responses; belief, calm and 'not your fault' are right.","relearn":"Drop doubt and visible horror; respond with belief, calm, and 'it's not your fault' when a child discloses.","persona":"any","source":"two not to use"},
  {"id":"sa-1401","cat":"tools-and-respond","type":"spot","hook":"Spot the two moves here that fail a child's safety.","scene":[{"id":"a","text":"Keeping a child close and away from the risk","trick":false},{"id":"b","text":"Hushing it up to protect the family name","trick":true},{"id":"c","text":"Calling Childline 1098 to report","trick":false},{"id":"d","text":"Confronting the suspect in a loud rage","trick":true},{"id":"e","text":"Believing and reassuring the child","trick":false}],"why":"Hushing it up and confronting in a rage fail a child; keeping them close, reporting and reassuring protect them.","relearn":"Don't hush it up or confront in a rage; keep the child close, report via Childline 1098, and reassure them.","persona":"any","source":"two that fail"},
  {"id":"sa-1402","cat":"tools-and-respond","type":"spot","hook":"Spot the two 'tools' that aren't real tools at all.","scene":[{"id":"a","text":"A gentle, open check-in on a changed child","trick":false},{"id":"b","text":"Promising you'll never tell a soul","trick":true},{"id":"c","text":"The saved helpline card","trick":false},{"id":"d","text":"Interrogating the child for full details","trick":true},{"id":"e","text":"'Believe, stay calm, no blame, act'","trick":false}],"why":"A secrecy promise and interrogation aren't safe tools; the check-in, the card and the response steps are.","relearn":"Secrecy promises and interrogation aren't tools; the check-in, the helpline card and the response steps are.","persona":"any","source":"not real tools"},
  {"id":"sa-1403","cat":"tools-and-respond","type":"spot","hook":"Spot the two thoughts that leave a parent unready.","scene":[{"id":"a","text":"'I'll learn the signs and save the numbers now'","trick":false},{"id":"b","text":"'It's too scary, I'd rather not know'","trick":true},{"id":"c","text":"'My child can come to me with anything'","trick":false},{"id":"d","text":"'I'll just figure it out on the day'","trick":true},{"id":"e","text":"'I'll stay calm and believe them'","trick":false}],"why":"Avoiding the topic and 'I'll figure it out later' leave a parent unready; preparing and staying tellable don't.","relearn":"Avoiding the topic and 'I'll figure it out later' leave you unready; prepare now and stay the tellable adult.","persona":"Kamla","source":"unready thoughts"},
  {"id":"sa-1404","cat":"tools-and-respond","type":"spot","hook":"Spot the two lines that quietly put image above the child.","scene":[{"id":"a","text":"'My child's safety comes before anything'","trick":false},{"id":"b","text":"'Think of what people will say about us'","trick":true},{"id":"c","text":"'We believe her and we'll get her help'","trick":false},{"id":"d","text":"'Let's keep this in the family, quietly'","trick":true},{"id":"e","text":"'Reporting is how we protect her'","trick":false}],"why":"Worrying about gossip and keeping it 'in the family' put image first; safety, belief and reporting put the child first.","relearn":"Drop 'what will people say' and 'keep it in the family'; the child's safety and reporting come before image.","persona":"any","source":"image above child"},
  {"id":"sa-1405","cat":"tools-and-respond","type":"spot","hook":"Spot the two online responses that would harm, not help, a tricked child.","scene":[{"id":"a","text":"'This is on him, not you, you're not in trouble'","trick":false},{"id":"b","text":"'How could you be so careless?'","trick":true},{"id":"c","text":"Saving the messages as evidence","trick":false},{"id":"d","text":"Deleting everything in a panic","trick":true},{"id":"e","text":"Reporting to cybercrime 1930","trick":false}],"why":"Blaming the child and deleting the evidence harm; reassuring, keeping evidence and reporting to 1930 help.","relearn":"Don't blame a tricked child or delete evidence; reassure them, keep the evidence, and report to cybercrime 1930.","persona":"Vikram","source":"online harm not help"},
  {"id":"sa-1406","cat":"tools-and-respond","type":"spot","hook":"Spot the two reactions that would make a withdrawn child clam up.","scene":[{"id":"a","text":"Sitting close and asking gently how they are","trick":false},{"id":"b","text":"Snapping 'what is wrong with you lately?'","trick":true},{"id":"c","text":"Offering your time with no pressure","trick":false},{"id":"d","text":"Forcing them to explain on the spot","trick":true},{"id":"e","text":"Letting them know the door is always open","trick":false}],"why":"Snapping at them and forcing an explanation make a child clam up; a gentle, unpressured check-in opens the door.","relearn":"Snapping or forcing an explanation closes a child down; check in gently, offer time, and keep the door open.","persona":"Divya","source":"clam up"},
  {"id":"sa-1407","cat":"tools-and-respond","type":"match","hook":"Match each safe-adult skill to the moment it's for.","pairs":[{"left":"Noticing sudden fear of someone","right":"When a child's behaviour shifts"},{"left":"'I believe you, it's not your fault'","right":"The moment a child discloses"},{"left":"Calling cybercrime 1930","right":"When harm comes from online"},{"left":"A gentle, open check-in","right":"When a child goes quiet"},{"left":"Calling Childline 1098","right":"When you need to report abuse"}],"relearn":"Each skill has its moment: notice shifts, believe on disclosure, 1930 for online, a check-in for quiet, 1098 to report.","persona":"any","source":"skill to moment"},
  {"id":"sa-1408","cat":"tools-and-respond","type":"match","hook":"Match each online red flag to the safe move it calls for.","pairs":[{"left":"An online 'friend' wants secrecy","right":"Keep the door open; talk it through"},{"left":"They pressure your child for a photo","right":"Reassure them; it's not their fault"},{"left":"Threats arrive demanding more","right":"Save evidence; report to 1930"},{"left":"Gifts and special attention online","right":"Treat it as grooming; stay close"},{"left":"Your child seems scared of their phone","right":"A gentle, open check-in"}],"relearn":"Online red flags, secrecy, pressure, threats, gifts, fear, each call for staying close, reassuring and reporting.","persona":"Vikram","source":"red flag to move"},
  {"id":"sa-1409","cat":"tools-and-respond","type":"sort","hook":"Just after a disclosure, sort each thing: do it now, or it can wait.","items":[{"id":"a","text":"Tell the child you believe them"},{"id":"b","text":"Figure out the exact dates and times"},{"id":"c","text":"Make sure the child is safe right now"},{"id":"d","text":"Decide what to tell distant relatives"},{"id":"e","text":"Say 'it's not your fault'"},{"id":"f","text":"Draft a long message to the school"}],"bins":[{"id":"now","label":"Do it now","valence":"pos"},{"id":"wait","label":"Can wait","valence":"neutral"}],"key":{"a":"now","c":"now","e":"now","b":"wait","d":"wait","f":"wait"},"relearn":"Right after a disclosure, believe, reassure and make the child safe now; details, relatives and letters can wait.","persona":"any","source":"now or wait"},
];

